    IPAddress,
    Location,
    AutonomousSystemNumber,
    ResultType,
    ResultDescription,
    AuthenticationDetails,
    AppDisplayName,
    UserAgent,
    AppId,
    UserId,
    OriginalRequestId,
    CorrelationId

