// Title: AgentCostAnomalyByDimension.yaml
// Source: https://www.kqlsearch.com/query/AgentCostAnomalyByDimension&cmqtvorkq008ebljhbocmiq0c
// Section: KQL
// Author: David Alonso
// Description:
// Hunts hourly token-consumption anomalies broken out per model, using
// series_decompose_anomalies over a 14-day baseline. Where the per-agent
// token-spike analytic rule answers "which agent spiked", this hunt slices
// the spend by model dimension so you can spot cost / denial-of-wallet
// anomalies concentrated on a specific (and often more expensive) model -
// including ones spread thinly across many agents that no single per-agent
// rule would catch.
//
// Reads gen_ai.usage.input_tokens + gen_ai.usage.output_tokens from the
// AppDependencies span property bag (Properties). Swap the "by Model"
// grouping for Agent or a tool dimension to pivot cost differently. The
// anomaly sensitivity (2.5) and the recentWindow filter are tunable.

let lookback = 14d;
let step = 1h;
let recentWindow = 1d;
AppDependencies
| where TimeGenerated > ago(lookback)
| where isnotempty(Properties["gen_ai.usage.input_tokens"])
     or isnotempty(Properties["gen_ai.usage.output_tokens"])
| extend
    Model  = tostring(Properties["gen_ai.request.model"]),
    InTok  = tolong(Properties["gen_ai.usage.input_tokens"]),
    OutTok = tolong(Properties["gen_ai.usage.output_tokens"])
| extend Model = iff(isempty(Model), "unknown-model", Model)
| extend TotalTok = coalesce(InTok, 0) + coalesce(OutTok, 0)
| make-series Tokens = sum(TotalTok) default = 0
    on TimeGenerated from ago(lookback) to now() step step by Model
| extend (anom, score, baseline) = series_decompose_anomalies(Tokens, 2.5)
| mv-expand
    TimeGenerated to typeof(datetime),
    Tokens   to typeof(long),
    anom     to typeof(long),
    score    to typeof(double),
    baseline to typeof(long)
| where anom == 1 and Tokens > baseline and TimeGenerated > ago(recentWindow)
| project TimeGenerated, Model, Tokens, BaselineTokens = baseline, AnomalyScore = score
| order by AnomalyScore desc

// Title: AgentDormancyBreak.yaml
// Source: https://www.kqlsearch.com/query/AgentDormancyBreak&cmqtvhsrt0078bljhszvetp34
// Section: KQL
// Author: David Alonso
// Description:
// Finds connector targets (and agent app versions) that were silent for
// >=7 days and then became active again in the recent window. A dormant-
// then-active pattern can indicate a re-enabled stale action, a forgotten
// integration being abused, or staged tooling that only lights up during
// an operation.

let reactivationWindow = 1d;
let silenceDays = 7d;
let conn = AppDependencies
           | where AppRoleName == "Microsoft Copilot Studio" or DependencyType == "Connector";
let recent = conn | where TimeGenerated > ago(reactivationWindow)
             | summarize RecentCalls = count(), LastSeen = max(TimeGenerated) by Target;
let priorActivity = conn
             | where TimeGenerated between (ago(60d) .. ago(reactivationWindow + silenceDays))
             | summarize PriorLastSeen = max(TimeGenerated) by Target;
let recentlySilent = conn
             | where TimeGenerated between (ago(reactivationWindow + silenceDays) .. ago(reactivationWindow))
             | distinct Target;
recent
| join kind=inner priorActivity on Target
| join kind=leftanti recentlySilent on Target
| extend DaysDormant = round(toreal(datetime_diff('day', LastSeen, PriorLastSeen)), 0)
| project LastSeen, Target, RecentCalls, PriorLastSeen, DaysDormant
| order by DaysDormant desc

// Title: AI Agent Third-Party Plugin with Internal Data Access
