// Title: Auto Close Low Priority Score Incidents
// Source: https://www.kqlsearch.com/query/Auto%20Close%20Low%20Priority%20Score%20Incidents&cmobhqah30002nl81gjn5n4iy
// Section: KQL
// Author: Benjamin Zulliger
// Description:
// <img width="1279" height="720" alt="image" src="https://github.com/user-attachments/assets/aa964c5c-ef2e-47c3-94a0-76e0d75da0d0" />

<img width="1279" height="720" alt="image" src="https://github.com/user-attachments/assets/aa964c5c-ef2e-47c3-94a0-76e0d75da0d0" />


**Description**

Azure Logic App to automatically close low-priority Microsoft Defender incidents based on the Priority Score. Incidents below a configurable threshold are resolved via Microsoft Graph API, reducing SOC noise and alert fatigue while preserving traceability through custom tags.

Link to Full Article: https://www.linkedin.com/pulse/use-microsoft-defender-priority-score-reduce-noise-benjamin-zulliger-ja3re/

```json
{
    "definition": {
        "metadata": {
            "notes": {}
        },
        "$schema": "https://schema.management.azure.com/providers/Microsoft.Logic/schemas/2016-06-01/workflowdefinition.json#",
        "contentVersion": "1.0.0.0",
        "triggers": {
            "Recurrence": {
                "type": "Recurrence",
                "recurrence": {
                    "frequency": "Minute",
                    "interval": 5,
                    "timeZone": "W. Europe Standard Time"
                }
            }
        },
        "actions": {
            "HTTP": {
                "type": "Http",
                "inputs": {
                    "uri": "https://graph.microsoft.com/v1.0/security/incidents",
                    "method": "GET",
                    "queries": {
                        "$filter": "status eq 'Active'"
                    },
                    "authentication": {
                        "type": "ManagedServiceIdentity",
                        "audience": "https://graph.microsoft.com"
                    }
                },
                "runAfter": {},
                "runtimeConfiguration": {
                    "contentTransfer": {
                        "transferMode": "Chunked"
                    }
                }
            },
            "Initialize_Variable_ExcludedTitleKeywords": {
                "type": "InitializeVariable",
                "inputs": {
                    "variables": [
                        {
                            "name": "excludedTitleKeywords",
                            "type": "Array",
                            "value": [
                                "Anomalous Token usage",
                                "demo",
                                "false positive"
                            ]
                        }
                    ]
                },
                "runAfter": {
                    "HTTP": [
                        "Succeeded"
                    ]
                }
            },
            "For_each": {
                "type": "Foreach",
                "foreach": "@body('HTTP')['value']",
                "actions": {
                    "Filter_Excluded_Titles": {
                        "type": "Query",
                        "inputs": {
                            "from": "@variables('excludedTitleKeywords')",
                            "where": "@contains(toLower(items('For_each')?['displayName']), toLower(item()))"
                        }
                    },
                    "Condition_Title_Not_Excluded": {
                        "type": "If",
                        "expression": {
                            "equals": [
                                "@length(body('Filter_Excluded_Titles'))",
                                0
                            ]
                        },
                        "actions": {
                            "Condition_PriorityScore_below_25": {
                                "type": "If",
                                "expression": {
                                    "and": [
                                        {
                                            "not": {
                                                "equals": [
                                                    "@item()?['priorityScore']",
                                                    null
                                                ]
                                            }
                                        },
                                        {
                                            "less": [
                                                "@item()?['priorityScore']",
                                                25
                                            ]
                                        }
                                    ]
                                },
                                "actions": {
                                    "HTTP_PATCH_Close_Incident": {
                                        "type": "Http",
                                        "inputs": {
                                            "uri": "https://graph.microsoft.com/v1.0/security/incidents/@{item()?['id']}",
                                            "method": "PATCH",
                                            "headers": {
                                                "Content-Type": "application/json"
                                            },
                                            "body": {
                                                "status": "resolved",
                                                "resolvingComment": "Auto-closed: priorityScore below threshold (25)",
                                                "customTags": "@union(item()?['customTags'], createArray('LowPrioScore'))"
                                            },
                                            "authentication": {
                                                "type": "ManagedServiceIdentity",
                                                "audience": "https://graph.microsoft.com"
                                            }
                                        }
                                    }
                                },
                                "else": {
                                    "actions": {}
                                }
                            }
                        },
                        "else": {
                            "actions": {}
                        },
                        "runAfter": {
                            "Filter_Excluded_Titles": [
                                "Succeeded"
                            ]
                        }
                    }
                },
                "runAfter": {
                    "Initialize_Variable_ExcludedTitleKeywords": [
                        "Succeeded"
                    ]
                }
            }
        },
        "outputs": {},
        "parameters": {
            "$connections": {
                "type": "Object",
                "defaultValue": {}
            }
        }
    },
    "parameters": {
        "$connections": {
            "type": "Object",
            "value": {}
        }
    }
}

// Title: Auto Disable High Risk AD User
// Source: https://www.kqlsearch.com/query/Auto%20Disable%20High%20Risk%20AD%20User&cml5x3916000h3h8t3292cf8h
// Section: KQL
// Author: Nathan Hutchinson
// Description:
// // AH custom detection: disable when user risk flipped HIGH within the lookback (e.g., last 1h)

// AH custom detection: disable when user risk flipped HIGH within the lookback (e.g., last 1h)
// IMPORTANT: When creating the detection rule, set the frequency to run every hour. 
// At 1h frequency, Advanced Hunting evaluates the last 4h of data (lookback).
// This query ensures it only triggers if a user's risk was set to HIGH within a 1h window.
// Requires Defender for Identity
let RiskWindow = 1h;
IdentityLogonEvents
| where Timestamp > ago(30d)   // wide window just to borrow a ReportId (AH requires it)
| summarize arg_max(Timestamp, ReportId, AccountUpn, AccountObjectId, Application, LogonType)
          by AccountObjectId
| join kind=inner (
    IdentityInfo
    | summarize ArgTS = arg_max(Timestamp, RiskLevel, RiskLevelDetails, OnPremSid) by AccountUpn, AccountObjectId
    | where RiskLevel =~ "high" or RiskLevelDetails has "adminConfirmedUserCompromised"
    | where ArgTS > ago(RiskWindow)
    | project AccountObjectId, AccountUpn, OnPremSid,       // <-- include SID
              RiskLevel, RiskLevelDetails, RiskSetTime = ArgTS
) on AccountObjectId
// Exclusions: update these!
| where AccountUpn !in~ ("breakglass1@contoso.com","breakglass2@contoso.com")
| project
    ReportId,                 // REQUIRED for custom detections
    Timestamp,                // REQUIRED (keep name exactly)
    AccountUpn, AccountObjectId,
    OnPremSid,                // <-- REQUIRED for the "Disable user" action
    RiskSetTime, RiskLevel, RiskLevelDetails,
    Application, LogonType

// Title: average-daily-ingestion-per-table-and-plan
// Source: https://www.kqlsearch.com/query/average-daily-ingestion-per-table-and-plan&cmp9ge61z00008xz73c52god9
// Section: Microsoft Sentinel
// Author: Michalis Michalos
// Description:
// The following query calculates the average daily ingestion for each table and plan over the last Timeframe of days as defined in the let statement. It also allows you to define the size of fractional part to fit your need and attention to detail. This query help baseline normal usage and identify outliers.

let Timeframe = 30d; // Define the required Timeframe
let decfra = 2; // Determine the size of fractional part to fit your need
Usage
| where TimeGenerated >= startofday(ago(Timeframe))
| where IsBillable == true
| summarize DailyGB = sum(Quantity) / 1000.0 by bin(TimeGenerated, 1d), DataType, Plan
| summarize AvgDailyGB = round(avg(DailyGB), decfra) by DataType, Plan
| order by AvgDailyGB desc

// Title: AzRbacAssignmentsOfRiskyUser.kusto
// Source: https://www.kqlsearch.com/query/AzRbacAssignmentsOfRiskyUser&cln4hqdu5001j5i0ovg1x41e8
// Section: KQL
// Author: Thomas Naunheim
// Description:
// AADRiskyUsers

AADRiskyUsers
| where RiskLevel == "high" and RiskState == "atRisk"
| extend principalId = tostring(Id)
| join hint.remote=left (arg("").authorizationresources
    | where type =~ 'microsoft.authorization/roleassignments'
    | extend roleDefinitionId = properties.roleDefinitionId
    | extend principalType = properties.principalType
    | extend principalId = tostring(properties.principalId)
    | extend roleAssignmentScope = properties.scope
    | project principalId, roleDefinitionId, roleAssignmentScope
) on principalId
| project UserDisplayName, RiskDetail, RiskLevel, RiskState, roleAssignmentScope, roleDefinitionId

// Title: Azure Active Directory - Password spray attack against Azure AD application
// Source: https://www.kqlsearch.com/query/Azure%20Active%20Directory%20-%20Password%20spray%20attack%20against%20Azure%20AD%20application&clmnym8ow001t5i4s6417bpth
// Section: Microsoft Sentinel
// Author: Alex Verboon
// Description:
// The below query looks at all past Sentinel Incidents for "Password spray attack against Azure AD application" and retrieves the Attackers IP Address, location and other properties.

let lookBack = 7d;
let IncTitle = "Password spray attack against Azure AD application";
let AttackerIpAddresses = (
SecurityIncident
| where TimeGenerated > ago(lookBack)
| where Title == IncTitle
| summarize arg_max(TimeGenerated,*) by IncidentNumber
| mv-expand AlertIds
| extend AlertId = tostring(AlertIds)
| join  (SecurityAlert)
on $left. AlertId == $right. SystemAlertId
| mv-expand parse_json(Entities)
| extend EType = tostring((Entities.Type))
| extend AttackIPAddress = tostring(Entities.Address)
| project AttackIPAddress);
AttackerIpAddresses
| join (SigninLogs
| extend city = tostring(LocationDetails.city)
| extend latitude = tostring(parse_json(tostring(LocationDetails.geoCoordinates)).latitude)
| extend longitude = tostring(parse_json(tostring(LocationDetails.geoCoordinates)).longitude)
| project IPAddress, Location, city, UserAgent, ClientAppUsed, AppDisplayName, UserPrincipalName,ResultType, latitude, longitude
)
on $left. AttackIPAddress == $right. IPAddress 
| distinct AttackIPAddress, Location,city

