// Title: Connections to abused TLDs - DeviceNetworkEvents.kql
// Source: https://www.kqlsearch.com/query/Connections%20to%20abused%20TLDs%20-%20DeviceNetworkEvents&cm3vwm2kb00045ieoc6dd5fq7
// Section: KQL
// Author: Jay Kerai
// Description:
// Get spamhaus TLD list

let spamhausTLDS = (externaldata(['TLD']: string, ['Badness Index']: string)
[h@"https://raw.githubusercontent.com/cyb3rmik3/Hunting-Lists/main/spamhaus-abused-tlds.csv"]with (format="csv"))
| extend TLD = iif(TLD startswith ".",replace_string(TLD,".",""),TLD)
| where TLD != "TLD";
//Get info-sec TLD list
let infosecTLDs = (externaldata(TLD: string)
[h@"https://www.info-sec.ca/tld-block.txt"]with (format="csv"))
| where TLD !startswith "#";
//Union lists together
let list_tlds = union spamhausTLDS, infosecTLDs
| project TLD;
//Exclude potential noise by uncommenting line below
//| where TLD !in ("live","info","link")
DeviceNetworkEvents
| where ActionType == "ConnectionSuccess"
| where isnotempty(RemoteUrl)
//Remove start and end of URL
| extend RemoteUrl = iif(RemoteUrl startswith "https://",replace_string(RemoteUrl,"https://",""),iif(RemoteUrl startswith "http://",replace_string(RemoteUrl, "http://",""),RemoteUrl))
| extend slashindex = indexof(RemoteUrl, "/")
| extend RemoteUrl = iif(RemoteUrl contains "/",substring(RemoteUrl, 0, slashindex),RemoteUrl)
| extend tld = tostring(split(RemoteUrl, ".")[-1])
| extend VT_Link = strcat("https://www.virustotal.com/gui/domain/",RemoteUrl)
| extend Abuse_Link = strcat("https://www.abuseipdb.com/check/",RemoteIP)
//Validate parsed domain by checking TLD against TLDs from threat feed and drop domains where there is no chance of a match
| where tld in~ (list_tlds)
| project-away slashindex
| project-reorder TimeGenerated, tld, VT_Link, Abuse_Link, RemoteUrl, InitiatingProcessAccountUpn, DeviceName
| extend Host_0_HostName = DeviceName
| extend Account_0_Name = InitiatingProcessAccountUpn
| extend URL_0_Url = RemoteUrl
//https://github.com/jkerai1/TLD-TABL-Block

// Title: Copilot - Agents - Allowed Agent Types
// Source: https://www.kqlsearch.com/query/Copilot%20-%20Agents%20-%20Allowed%20Agent%20Types&cmo7jvim0000134v8oqd7phdn
// Section: Defender XDR
// Author: Alex Verboon
// Description:
// Retrieve Copilot - Agent - Allowed Agent Types Settings changes
//
// Allowed agent types allows control of which types of agents users can view and install from the agent catalog. You can select from the following options:
//
// - Allow apps and agents built by Microsoft - Enables users to install agents created by Microsoft.
// - Allow apps and agents built by your organization - Enables users to install custom agents developed within your tenant.
// - Allow apps and agents built by external publishers - Enables users to install non-Microsoft agents built by external developers.
//
// If you disable an option, agents of that type don't appear for users in the Agent store. Agents built by Microsoft are visible to users even if the setting is disabled. Users aren't able to install those agents.

CloudAppEvents
| where Application == "Microsoft 365"
| where ActionType == "UpdateTenantSettings"
| extend AgentTypeSetting = tostring(parse_json(tostring(RawEventData.Resource)).Property)
| where AgentTypeSetting in ("AllowFirstParty","AllowThirdParty","AllowLOB")
| extend NewValue = tostring(parse_json(tostring(parse_json(tostring(RawEventData.Resource)).NewValue)))
| extend OriginalValue = tostring(parse_json(tostring(parse_json(tostring(RawEventData.Resource)).OriginalValue)))
| extend Configuration = case(
    AgentTypeSetting == "AllowFirstParty", "Allow Apps and Agents built by Microsoft",
    AgentTypeSetting == "AllowThirdParty", "Allow Apps and Agents built by external publishers",
    AgentTypeSetting == "AllowLOB",        "Allow Apps and Agent Built by your organization",
    "Unknown"
)
| extend ConfigurationState = case(
    NewValue == "True",  "Enabled",
    NewValue == "False", "Disabled",
    "Unknown"
)
| project TimeGenerated, AgentTypeSetting, Configuration, ConfigurationState,AccountDisplayName
| sort by TimeGenerated

// Title: Copilot - Agents - Sharing
