// Title: Detecting domains where their emails will be routed to Junk folders due to new Outlook requirement
// Source: https://www.kqlsearch.com/query/Detecting%20domains%20where%20their%20emails%20will%20be%20routed%20to%20Junk%20folders%20due%20to%20new%20Outlook%20requirement&cm93gpi4901o0p10f4i1roauq
// Section: KQL
// Author: Sergio Albea
// Description:
// **MITRE ATT&CK Technique(s)**

EmailEvents
| where Timestamp > ago(1d)
| extend SPF = tostring(parse_json(AuthenticationDetails).SPF)
| extend DMARC = tostring(parse_json(AuthenticationDetails).DMARC)
| extend DKIM = tostring(parse_json(AuthenticationDetails).DKIM)
