// Title: Device-Vulnerability-Prioritization-CVSS-EPSS
// Source: https://www.kqlsearch.com/query/Device-Vulnerability-Prioritization-CVSS-EPSS&cmt0gtqe600001bo0j7zmyq8l
// Section: Defender XDR
// Author: Benjamin Zulliger
// Description:
// This KQL query enriches vulnerability data from Defender for Endpoint by joining device inventory, operating system details, MDE onboarding status, and threat intelligence metrics. It correlates device vulnerabilities with CVSS severity and EPSS exploitability scores to prioritize patching based on actionable risk rather than static vulnerability levels.
//
// The RiskScore is a weighted metric ranging from 0 to 100 that combines the technical severity of a vulnerability with its real world likelihood of exploitation. CVSS contributes 35 percent of the overall score to represent potential impact, while EPSS contributes 65 percent to heavily weight active exploitation probability.

// Define weights at the top of the query (must sum up to 1.0)
let CvssWeight = 0.35; // 1 = 100% / 0 = 0%
let EpssWeight = 0.65; // 1 = 100% / 0 = 0%
DeviceTvmSoftwareVulnerabilities
// Join with KB table to fetch CVSS and EPSS scores
| join kind=inner (
    DeviceTvmSoftwareVulnerabilitiesKB
    | project CveId, CvssScore = todouble(CvssScore), EpssScore = todouble(EpssScore)
) on CveId
// Join with DeviceInfo to get current OS details, MDE onboarding status, and LastSeen
| join kind=leftouter (
    DeviceInfo
    | summarize arg_max(Timestamp, OSPlatform, OSVersion, OnboardingStatus) by DeviceId
    | project DeviceId, LastSeen = Timestamp, OSPlatform, OSVersion, OnboardingStatus, IsMdeOnboarded = (OnboardingStatus == "Onboarded")
) on DeviceId
// Calculate weighted risk score using defined weights
| extend RiskScore = round((CvssScore * 10.0 * CvssWeight) + (EpssScore * 100.0 * EpssWeight), 1)
// Assign priority and patch SLA (days)
| extend SlaDays = case(
    RiskScore >= 65.0, 3,
    RiskScore >= 40.0, 14,
    RiskScore >= 20.0, 30,
    90
)
| extend Priority = case(
    RiskScore >= 65.0, "P1 - Critical",
    RiskScore >= 40.0, "P2 - High",
    RiskScore >= 20.0, "P3 - Medium",
    "P4 - Low"
)
// Calculate due date
| extend PatchDueDate = datetime_add('day', SlaDays, now())
| project 
    DeviceName, 
    DeviceId, 
    LastSeen,
    OSPlatform, 
    OSVersion, 
    OnboardingStatus, 
    IsMdeOnboarded, 
    SoftwareVendor, 
    SoftwareName, 
    SoftwareVersion, 
    CveId, 
    CvssScore, 
    EpssScore, 
    RiskScore, 
    Priority, 
    SlaDays, 
    PatchDueDate, 
    VulnerabilitySeverityLevel
| sort by RiskScore desc

// Title: Device Vulnerability & Software Evidence Details
// Source: https://www.kqlsearch.com/query/Device%20Vulnerability%20%26%20Software%20Evidence%20Details&cmszqmi4t0001k12rsx2zkhze
// Section: Defender XDR
// Author: Benjamin Zulliger
// Description:
// Retrieves all software vulnerabilities for a specific device, enriched with underlying detection evidence. It correlates vulnerability data with file paths (DiskPaths) or registry entries (RegistryPaths), making it easy to identify the exact location or reason for each vulnerability finding.

let VulnDevice = "YOURSERVERNAME";
let DeviceScope =
	DeviceInfo
	| where DeviceName startswith VulnDevice or DeviceId =~ VulnDevice
	| summarize arg_max(Timestamp, *) by DeviceId
	| project DeviceId, DeviceName;
let Vulns =
	DeviceTvmSoftwareVulnerabilities
	| join kind=inner DeviceScope on DeviceId;
let Evidence =
	DeviceTvmSoftwareEvidenceBeta
	| join kind=inner DeviceScope on DeviceId
	| project
		DeviceId,
		SoftwareName,
		SoftwareVendor,
		SoftwareVersion,
		DiskPaths,
		RegistryPaths;
Vulns
| join kind=leftouter Evidence on DeviceId, SoftwareName, SoftwareVendor, SoftwareVersion
| extend
	FilePaths = iff(isnotempty(DiskPaths), tostring(DiskPaths), "[]"),
	RegPaths = iff(isnotempty(RegistryPaths), tostring(RegistryPaths), "[]")
| project
	DeviceName,
	CveId,
	VulnerabilitySeverityLevel,
	SoftwareName,
	SoftwareVendor,
	SoftwareVersion,
	RecommendedSecurityUpdate,
	RecommendedSecurityUpdateId,
	FilePaths,
	RegPaths
| order by VulnerabilitySeverityLevel desc, CveId asc

