// Title: DevtunnelRegistry
// Source: https://www.kqlsearch.com/query/DevtunnelRegistry&cm0v4bkqi00xamc0pla79tfih
// Section: Search Query
// Author: Ali Hussein
// Description:
// This detection rule identifies suspicious modifications to the `InProcServer32` registry key where the registry value data contains "msalruntime." Modifying this registry key can be an indication of persistence or DLL injection attacks. The `InProcServer32` key is commonly associated with Component Object Model (COM) hijacking, where adversaries attempt to load malicious DLLs through legitimate processes.

DeviceRegistryEvents
| where RegistryKey contains "inprocserver32"
| where RegistryValueData contains "msalruntime"

// Title: Disabling Global Secure Access by Registry.kql
// Source: https://www.kqlsearch.com/query/Disabling%20Global%20Secure%20Access%20by%20Registry&cm44j21b8005rmc0lz5pqdgbq
// Section: KQL
// Author: Jay Kerai
// Description:
// DeviceRegistryEvents

DeviceRegistryEvents
| where ActionType == "RegistryValueSet" //or ActionType == "RegistryKeyCreated"
| where RegistryKey == @"HKEY_CURRENT_USER\Software\Microsoft\Global Secure Access Client"
| where RegistryValueName == "IsPrivateAccessDisabledByUser"
| where RegistryValueData == "1" ///If the registry value doesn't exist, the default value is 0x0, Private Access is enabled. https://learn.microsoft.com/en-us/entra/global-secure-access/how-to-install-windows-client#disable-or-enable-private-access-on-the-client?WT.mc_id=MVP_473477

// Title: DISCOVERY: Obsolete device connecting to Entra.kql
// Source: https://www.kqlsearch.com/query/DISCOVERY%3A%20Obsolete%20device%20connecting%20to%20Entra&clzh25hrt001y5ivo019z6bme
// Section: KQL
// Author: Steven Lim
// Description:
// DISCOVERY: Obsolete device connecting to Entra
// https://www.linkedin.com/posts/activity-7222163567834230785-BgVr/
// Detect unpatched Windows 10 and 11 clients connecting to your Entra tenant via AADSTS5000611 (Symmetric Key Derivation Function version 'KDFV1' is invalid)

union isfuzzy=true SigninLogs, AADNonInteractiveUserSignInLogs
| where ResultType != 0 and ResultDescription == "Other"
| where ResultType == "500061"
| distinct Category, Identity


// MITRE ATT&CK Mapping

// Based on the KQL query, the following MITRE ATT&CK techniques are relevant:

// T1078 - Valid Accounts:
// This technique involves adversaries using valid accounts to gain access to systems. The query focuses on non-successful sign-ins, which could indicate attempts to use valid accounts with // incorrect credentials or other issues.
// T1110 - Brute Force:
// The query could be used to detect brute force attempts where multiple sign-in attempts fail. Filtering by ResultType != 0 and specific ResultType == "500061" can help identify such patterns.
// T1556 - Modify Authentication Process:
// The query looks at non-interactive user sign-ins, which could be related to attempts to modify or bypass the authentication process.

// Title: DnsEvents-FindStaleDomains.kql
// Source: https://www.kqlsearch.com/query/DnsEvents-FindStaleDomains&clmoypqhz006dmc0ko28xped6
// Section: KQL
// Author: Matt Zorich
// Description:
// Find DNS domains that have not been queried in the last 30 days. These are potentially stale and should be removed.
// Data connector required for this query - DNS

let domain="yourdomain.com";
DnsEvents
| where TimeGenerated > ago(180d)
| where SubType == "LookupQuery"
| where QueryType == "A"
| where Name endswith domain
| summarize LookupCount=count()by Name
//Set a threshold for total lookups to be included, to account for typos and low volume queries
| where LookupCount > 50
| join kind=leftanti 
    (
    DnsEvents
    | where TimeGenerated > ago(30d)
    | where SubType == "LookupQuery"
    | where QueryType == "A"
    | where Name endswith domain
    | summarize arg_max(TimeGenerated, Name) by Name
    | project TimeGenerated, Name)
    on Name

// Title: DomainAdminsEnterpriseAdmins.txt
// Source: https://www.kqlsearch.com/query/DomainAdminsEnterpriseAdmins&clmp0r33b00jvmc0k2y0m3d3a
// Section: KQL
// Author: Rod Trent
// Description:
// New Domain Admins and Enterprise Admins

Event
| where TimeGenerated > ago(7d)
| extend eventData=parse_json(EventData)
| project TimeGenerated, Computer, EventID, eventData.MemberName, eventData.SubjectDomainName, eventData.SubjectUserName, eventData.TargetUserName
