// Title: DormantDeviceReactivation.yaml
// Source: https://www.kqlsearch.com/query/DormantDeviceReactivation&cmqtv9u5m0067bljhxnopuuzq
// Section: KQL
// Author: David Alonso
// Description:
// Identifies Intune-managed devices that were dormant >60 days and recently checked in.
// Reactivated accounts / devices are a known persistence technique.

IntuneDevices
| where TimeGenerated > ago(90d)
| summarize LastSeen = max(TimeGenerated), FirstSeen = min(TimeGenerated),
            arg_max(TimeGenerated, DeviceName, UPN, OS, Ownership, CompliantState)
          by DeviceId = tostring(DeviceId)
| extend DaysIdleBefore = datetime_diff('day', LastSeen, FirstSeen)
| where LastSeen > ago(7d) and DaysIdleBefore >= 60
| project LastSeen, DeviceId, DeviceName,
          UserPrincipalName = tolower(tostring(UPN)),
          OperatingSystem   = tostring(OS),
          OwnerType         = tostring(Ownership),
          ComplianceState   = tostring(CompliantState),
          DaysIdleBefore
| order by LastSeen desc

// Title: EchoSpoofing.kql
// Source: https://www.kqlsearch.com/query/EchoSpoofing&clzh1y878000w5ivocowcgwe6
// Section: KQL
// Author: Steven Lim
// Description:
// By leveraging Defender threat intelligence data to first identify abused Proofpoint email gateways and correlating this with emails that have passed authentication checks (SPF/DKIM/DMARC) from these gateways, you can quickly spot abnormal inbound email counts from legitimate non-business partner domains by reviewing the email statistics. (E.g Disney.com)

let HighRiskProofpointEmailGateways =
CloudAppEvents 
| where ActionType == @"TIMailData-Inline"
| where RawEventData has "pphosted.com" or ISP == @"proofpoint inc."
| extend SenderIP = tostring(RawEventData.SenderIp)
| distinct SenderIP;
EmailEvents
| where SenderIPv4 has_any(HighRiskProofpointEmailGateways)
| extend SenderInfo = geo_info_from_ip_address(SenderIPv4)
| extend AuthDetail = parse_json(AuthenticationDetails)
