// Title: FoundryBlocklistTermMatched.yaml
// Source: https://www.kqlsearch.com/query/FoundryBlocklistTermMatched&cmqtvjee2007ibljha7it1vdz
// Section: KQL
// Author: David Alonso
// Description:
// Raises an incident when an organisation-defined custom blocklist term
// is matched on a Foundry / Agent Service prompt or completion. Confirms
// block lists are firing and surfaces users probing around restricted
// terms (project code-names, regulated keywords, internal identifiers).
//
// Reads the real Foundry telemetry shape: spans in AppDependencies,
// property bag in Properties, verdict in
// microsoft.foundry.content_filter.results. The custom-blocklist field
// name varies by API version, so custom_blocklists and custom_blocklist
// are both parsed defensively. Requires
// AZURE_TRACING_GEN_AI_CONTENT_RECORDING_ENABLED for the prompt text.

AppDependencies
| where isnotempty(Properties["microsoft.foundry.content_filter.results"])
| extend
    Agent     = tostring(Properties["gen_ai.agent.name"]),
    Model     = tostring(Properties["gen_ai.request.model"]),
    ConvId    = tostring(Properties["gen_ai.conversation.id"]),
    ProjectId = tostring(Properties["microsoft.foundry.project.id"]),
    Prompt    = tostring(Properties["gen_ai.input.messages"]),
    FilterArr = todynamic(tostring(Properties["microsoft.foundry.content_filter.results"]))
| mv-expand Entry = FilterArr
| extend
    SourceType = tostring(Entry.source_type),
    Cfr        = todynamic(Entry.content_filter_results)
// Custom blocklists surface as named keys inside content_filter_results
// (e.g. "Profanity", or your own blocklist name) alongside the standard
// harm categories. Treat any non-standard key that tripped as a blocklist
// hit so the rule works regardless of the blocklist name.
| mv-expand Key = bag_keys(Cfr)
| extend BlockListName = tostring(Key)
| where BlockListName !in~ ("jailbreak", "prompt_shield", "indirect_attack", "hate", "sexual", "violence", "self_harm", "protected_material", "protected_material_code", "protected_material_text")
| extend Verdict = todynamic(Cfr[BlockListName])
| where tobool(Verdict.filtered) or tobool(Verdict.detected)
| extend AccountName = iff(isempty(Agent), "unknown-agent", Agent)
| project
    TimeGenerated, AccountName, SourceType, Agent, Model, ProjectId, ConvId,
    BlockListName, VerdictJson = tostring(Verdict), Prompt
| order by TimeGenerated desc

// Title: FoundryCapabilityDisclosureExtended.yaml
// Source: https://www.kqlsearch.com/query/FoundryCapabilityDisclosureExtended&cmqtvjtfr007kbljhhil6i05l
// Section: KQL
// Author: David Alonso
// Description:
// Detects the v2.0 taxonomy's "capability / architecture disclosure"
// failure mode beyond plain system-prompt extraction: the user probes
// for the agent's tool list, function schemas, consent / HitL trigger
// logic or memory interface, and the agent's response leaks structural
// details (tool names, schemas, parameters, consent rules, memory
// primitives). v2.0 highlights this as a key enabler of follow-on
// attacks - turning black-box probing into a white-box exploit path.
//
// This complements FoundrySystemPromptDisclosure (which only looks at
// system-prompt phrasing) by:
// - covering tool / schema / consent / memory probes, and
// - intersecting the response against the project's actual recent
// tool inventory (last 7 days, tools with >= 5 calls) so the rule
// only fires when at least 3 real tool names from the project are
// reflected back to the user.
//
// The "real tool name" intersection is the false-positive control:
// generic answers ("I can summarise text") never reach the threshold.

let probes = dynamic([
    "what tools","list your tools","what functions","describe your functions",
    "what capabilities","what can you do","what actions","what plugins",
    "list your plugins","list your skills","what skills","describe your tools",
    "what is your schema","print your function","reveal your tools",
    "when do you ask for approval","what triggers consent","what triggers hitl",
    "what triggers your guardrails","describe your memory","what memories do you have",
    "what are your operations","what is your tool list","describe your hooks",
    "list your apis","what mcp servers"
]);
let leakMarkers = dynamic([
    "function:","tool:","name:","schema:","parameters","arguments",
    "i have access to","i can use the","my available tools","my tools include",
    "the following tools","tools available","available functions",
    "i ask for approval","i require consent","my memory","memory store",
    "my operations are","my mcp server","my plugins are"
]);
let known =
    toscalar(
        AppDependencies
        | where TimeGenerated between (ago(7d) .. ago(1h))
        | extend ToolName = tolower(tostring(Properties["gen_ai.tool.name"]))
        | where isnotempty(ToolName) and strlen(ToolName) >= 4
        | summarize Calls = count() by ToolName
        | where Calls >= 5
        | summarize KnownTools = make_set(ToolName, 200)
    );
AppDependencies
| where TimeGenerated > ago(1h)
| where isnotempty(Properties["gen_ai.input.messages"])
        and isnotempty(Properties["gen_ai.output.messages"])
| extend
    Agent     = tostring(Properties["gen_ai.agent.name"]),
    Model     = tostring(Properties["gen_ai.request.model"]),
    ConvId    = tostring(Properties["gen_ai.conversation.id"]),
    ProjectId = tostring(Properties["microsoft.foundry.project.id"]),
    Input     = tolower(tostring(Properties["gen_ai.input.messages"])),
    Output    = tolower(tostring(Properties["gen_ai.output.messages"]))
| extend AskedAboutCapabilities = Input has_any (probes)
| extend LeaksStructure         = Output has_any (leakMarkers)
| where AskedAboutCapabilities and LeaksStructure
| extend OutputTokens = extract_all(@"([a-z][a-z0-9_\-]{3,})", Output)
| extend LeakedTools  = set_intersect(OutputTokens, known)
| extend LeakedToolCount = array_length(LeakedTools)
| where LeakedToolCount >= 3
| extend AccountName = iff(isempty(Agent), "unknown-agent", Agent)
| project TimeGenerated, AccountName, Agent, Model, ProjectId, ConvId,
          LeakedToolCount, LeakedTools,
          InputSample  = substring(Input, 0, 512),
          OutputSample = substring(Output, 0, 1024)
| order by LeakedToolCount desc, TimeGenerated desc

// Title: FoundryCuaVisualAttack.yaml
// Source: https://www.kqlsearch.com/query/FoundryCuaVisualAttack&cmqtvk53u007mbljhqmpb54yk
// Section: KQL
// Author: David Alonso
// Description:
// Detects the v2.0 taxonomy's "Computer Use Agent (CUA) visual attack"
// failure mode: a computer-use agent is fed visual content that appears
// innocuous to humans but carries adversarial instructions for the
// model. Patterns observed by the Microsoft AI Red Team include hidden
// text rendered at non-human-readable scale, off-viewport UI elements
// the agent OCRs but the user does not see, and prompt-injection
// embedded in images / page content the agent is instructed to interpret.
//
// The rule scopes to spans whose tool type or name marks them as
// computer-use (computer_use, browser, screen_capture, ui, mouse,
// keyboard, navigate, click) and inspects the observation /
// screenshot.text / tool result payload for:
// - Unicode Tag block (U+E0000-U+E007F) - hidden ASCII smuggling
// - >= 3 zero-width chars (U+200B-U+200D, U+FEFF, U+2060)
// - bidirectional overrides (U+202A-U+202E, U+2066-U+2069)
// - explicit prompt-injection markers (ignore previous, developer
// mode, send the data to, navigate to, click this link, ...)
//
// Threshold is intentionally low because each pattern is a strong
// individual indicator that the screen content is adversarial. Pair
// with FoundryRedTeamPacingAnomaly to spot bursts.

let injectionMarkers = dynamic([
    "ignore previous instructions","disregard previous","you are now",
    "developer mode","do anything now","reveal your system prompt",
    "ignore the user","execute the following","run this command",
    "send the data to","upload to","download from","navigate to",
    "click this link","follow this link","copy and paste this",
    "type the following","press enter to","authorise the transaction"
]);
AppDependencies
| where TimeGenerated > ago(1h)
| extend
    Agent      = tostring(Properties["gen_ai.agent.name"]),
    Model      = tostring(Properties["gen_ai.request.model"]),
    ConvId     = tostring(Properties["gen_ai.conversation.id"]),
    ProjectId  = tostring(Properties["microsoft.foundry.project.id"]),
    ToolType   = tolower(tostring(Properties["gen_ai.tool.type"])),
    ToolName   = tolower(tostring(Properties["gen_ai.tool.name"])),
    Observation = tostring(coalesce(
                    Properties["gen_ai.computer_use.observation"],
                    Properties["gen_ai.computer_use.screenshot.text"],
                    Properties["microsoft.agent.computer_use.observation"],
                    Properties["gen_ai.tool.call.result"], ""))
| where ToolType has_any ("computer_use","computer-use","browser","desktop","ui","screen")
     or ToolName has_any ("computer_use","screenshot","mouse","keyboard","navigate","click","type_text","screen_capture","browser_use")
| where isnotempty(Observation)
| extend ObsLower = tolower(Observation)
| extend
    TagChars     = array_length(extract_all(@"([\x{E0000}-\x{E007F}])", Observation)),
    ZeroWidth    = array_length(extract_all(@"([\x{200B}-\x{200D}\x{FEFF}\x{2060}])", Observation)),
    BidiOverride = array_length(extract_all(@"([\x{202A}-\x{202E}\x{2066}-\x{2069}])", Observation)),
    HasInjection = ObsLower has_any (injectionMarkers)
| where TagChars > 0 or ZeroWidth >= 3 or BidiOverride > 0 or HasInjection
| extend Signal = case(
    TagChars > 0,     "UnicodeTagInScreenContent",
    BidiOverride > 0, "BidiOverrideInScreenContent",
    HasInjection,     "InstructionInScreenContent",
                      "ZeroWidthInScreenContent")
| extend AccountName = iff(isempty(Agent), "unknown-agent", Agent)
| project TimeGenerated, Signal, AccountName, Agent, Model, ProjectId, ConvId,
          ToolType, ToolName, TagChars, ZeroWidth, BidiOverride, HasInjection,
          ObservationSample = substring(Observation, 0, 512)
| order by TimeGenerated desc

// Title: FoundryInterAgentPermissionMismatch.yaml
// Source: https://www.kqlsearch.com/query/FoundryInterAgentPermissionMismatch&cmqtvkw6c007rbljhh033irre
// Section: KQL
// Author: David Alonso
// Description:
// Detects the v2.0 taxonomy's "inter-agent trust escalation" failure
// mode: an orchestrator delegates work to a sub-agent, and that sub-
// agent then exercises tools that are not in its 14-day baseline
// repertoire. The pattern mirrors the confused-deputy problem - the
// orchestrator did not independently verify the sub-agent's claimed
// permissions, and a compromised or self-asserting sub-agent reaches
// capabilities it should not have.
//
// The rule:
// 1. Identifies cross-agent invocations in the last hour (tool type
// agent / connected_agent / agent_call, with the called agent
// resolved from gen_ai.tool.target_agent / microsoft.agent.target_
// agent.name / fallback to the tool name).
// 2. Looks at every tool the called sub-agent invokes within the next
// 30 minutes in the same conversation.
// 3. Joins leftanti against the sub-agent's 14-day tool baseline so
// only tool names it has not used before are kept.
// 4. Fires only when (a) at least 2 distinct new tools are seen, OR
// (b) any of the new tools is sensitive (code interpreter, shell,
// exec, sql, email, http). Both conditions filter onboarding /
// legitimate first-use noise.

let baselineWindow = 14d;
let recentWindow   = 1h;
let calleeBaseline =
    AppDependencies
    | where TimeGenerated between (ago(baselineWindow) .. ago(recentWindow))
    | extend Agent    = tostring(Properties["gen_ai.agent.name"]),
             ToolName = tolower(tostring(Properties["gen_ai.tool.name"]))
    | where isnotempty(Agent) and isnotempty(ToolName)
    | distinct Agent, ToolName;
let crossInvocations =
    AppDependencies
    | where TimeGenerated > ago(recentWindow)
    | extend
        Caller   = tostring(Properties["gen_ai.agent.name"]),
        ConvId   = tostring(Properties["gen_ai.conversation.id"]),
        ToolName = tolower(tostring(Properties["gen_ai.tool.name"])),
        ToolType = tolower(tostring(Properties["gen_ai.tool.type"])),
        Callee   = tolower(tostring(coalesce(
                      Properties["gen_ai.tool.target_agent"],
                      Properties["microsoft.agent.target_agent.name"],
                      Properties["gen_ai.tool.name"])))
    | where ToolType == "agent" or ToolName has "connected_agent" or ToolName has "agent_call"
    | project Caller, ConvId, Callee, InvocationTime = TimeGenerated;
let calleeUsage =
    AppDependencies
    | where TimeGenerated > ago(recentWindow)
    | extend Agent    = tostring(Properties["gen_ai.agent.name"]),
             ConvId   = tostring(Properties["gen_ai.conversation.id"]),
             ToolName = tolower(tostring(Properties["gen_ai.tool.name"])),
             ToolType = tolower(tostring(Properties["gen_ai.tool.type"]))
    | where isnotempty(ToolName)
    | project Agent, ConvId, ToolName, ToolType, ToolTime = TimeGenerated;
crossInvocations
| join kind=inner calleeUsage on ConvId
| where Agent == Callee or Agent has Callee or Callee has Agent
| where ToolTime between (InvocationTime .. (InvocationTime + 30m))
| join kind=leftanti calleeBaseline on Agent, ToolName
| summarize NewToolHits   = count(),
            NewTools      = make_set(ToolName, 16),
            NewToolTypes  = make_set(ToolType, 8),
            FirstSeen     = min(ToolTime),
            LastSeen      = max(ToolTime),
            AnyCaller     = take_any(Caller)
        by Agent, ConvId
| where NewToolHits >= 1
        and (array_length(NewTools) >= 2
             or NewToolTypes has_any ("code_interpreter","shell","exec","sql","email","http","deploy","azure_write"))
| extend AccountName = Agent, Caller = AnyCaller
| project LastSeen, AccountName, Caller, Agent, ConvId, NewToolHits,
          NewTools, NewToolTypes, FirstSeen
| order by NewToolHits desc

// Title: FoundryPromptInjectionPatterns.yaml
// Source: https://www.kqlsearch.com/query/FoundryPromptInjectionPatterns&cmqtvm7jh007zbljh5e4nynap
// Section: KQL
// Author: David Alonso
// Description:
// Hunts Foundry / Agent Service inputs and tool arguments for known
// prompt-injection markers: instructions to ignore previous guidance,
// role-override phrases, tool-coercion phrases, system-prompt disclosure
// requests, and base64 / data-URI blobs embedded in user content. This
// catches injection attempts that Prompt Shields may not have flagged
// (custom phrasings, novel jailbreaks) - pair it with the
// guardrail-jailbreak rule for the model-verdict view.
//
// Reads the real Foundry telemetry shape: spans in AppDependencies, bag
// in Properties. The prompt text lives in gen_ai.input.messages and tool
// arguments in gen_ai.tool.call.arguments, so both require
// AZURE_TRACING_GEN_AI_CONTENT_RECORDING_ENABLED. Without content
// recording this rule will not fire.

let injectionPhrases = dynamic([
    "ignore previous instructions",
    "ignore prior instructions",
    "disregard the above",
    "you are now",
    "act as system",
    "system prompt:",
    "developer mode",
    "bypass safety",
    "reveal your prompt",
    "print your instructions",
    "exfiltrate",
    "send to attacker"
]);
let toolCoercion = dynamic([
    "regardless of restrictions",
    "without confirming",
    "skip approval",
    "use admin privileges",
    "elevate to"
]);
AppDependencies
| where isnotempty(Properties["gen_ai.input.messages"])
    or isnotempty(Properties["gen_ai.tool.call.arguments"])
| extend
    Agent     = tostring(Properties["gen_ai.agent.name"]),
    Model     = tostring(Properties["gen_ai.request.model"]),
    ConvId    = tostring(Properties["gen_ai.conversation.id"]),
    ProjectId = tostring(Properties["microsoft.foundry.project.id"]),
    Prompt    = tostring(Properties["gen_ai.input.messages"]),
    ToolName  = tostring(Properties["gen_ai.tool.name"]),
    ToolArgs  = tostring(Properties["gen_ai.tool.call.arguments"])
| extend Haystack = tolower(strcat(Prompt, " ", ToolArgs))
| where Haystack has_any (injectionPhrases)
    or Haystack has_any (toolCoercion)
    or Haystack matches regex @"data:[a-z/+.\-]+;base64,[A-Za-z0-9+/=]{200,}"
| extend AccountName = iff(isempty(Agent), "unknown-agent", Agent)
| project
    TimeGenerated, AccountName, Agent, Model, ProjectId, ConvId,
    ToolName, Prompt, ToolArgs
| order by TimeGenerated desc

// Title: FoundryThreatIntelUrlMatch.yaml
// Source: https://www.kqlsearch.com/query/FoundryThreatIntelUrlMatch&cmqtvnh880087bljhga0ek7rg
// Section: KQL
// Author: David Alonso
// Description:
// Extracts URLs (and their hosts / IPs) from Foundry / Agent Service
// conversation content - both user input (gen_ai.input.messages) and agent
// output (gen_ai.output.messages) - and correlates them against active
// Microsoft Sentinel threat-intelligence indicators. A match means the
// agent either received or emitted a known malicious / suspicious URL,
// domain or IP, which can indicate a phishing lure fed to the agent, a
// poisoned RAG / knowledge source, or a corrupted agent surfacing attacker
// infrastructure. This is the high-fidelity companion to
// FoundrySuspiciousUrlInContent (which is heuristic): here the verdict
// comes from the TI feed.
//
// Joins against the modern ThreatIntelIndicators table (network observable
// types url:value / domain-name:value / ipv4-addr:value / ipv6-addr:value)
// and only considers active, non-revoked, in-date indicators. Reads agent
// text from AppDependencies (requires
// AZURE_TRACING_GEN_AI_CONTENT_RECORDING_ENABLED).

let dt_lookBack = 1h;
let ioc_lookBack = 14d;
let networkIocTypes = dynamic(["url:value", "domain-name:value", "ipv4-addr:value", "ipv6-addr:value"]);
let TI =
    ThreatIntelIndicators
    | where TimeGenerated > ago(ioc_lookBack)
    | where IsActive == true and Revoked == false
    | where ObservableKey in (networkIocTypes)
    | where isempty(ValidUntil) or ValidUntil > now()
    | summarize arg_max(TimeGenerated, *) by IndicatorId = Id
    | extend IOC = tolower(ObservableValue)
    | where isnotempty(IOC);
let Spans =
    AppDependencies
    | where TimeGenerated > ago(dt_lookBack)
    | where isnotempty(Properties["gen_ai.input.messages"]) or isnotempty(Properties["gen_ai.output.messages"])
    | extend
        Agent     = tostring(Properties["gen_ai.agent.name"]),
        Model     = tostring(Properties["gen_ai.request.model"]),
        ConvId    = tostring(Properties["gen_ai.conversation.id"]),
        ProjectId = tostring(Properties["microsoft.foundry.project.id"]),
        Input     = tostring(Properties["gen_ai.input.messages"]),
        Output    = tostring(Properties["gen_ai.output.messages"]),
        SrcIp     = tostring(column_ifexists("ClientIP", ""));
let FromInput  = Spans | where isnotempty(Input)  | extend Direction = "UserPrompt",    Text = Input;
let FromOutput = Spans | where isnotempty(Output) | extend Direction = "AgentResponse", Text = Output;
let Content =
    union FromInput, FromOutput
    | mv-expand Url = extract_all(@"(https?://[^\s\)\]\}""'<>]+)", Text) to typeof(string)
    | extend
        Url  = tolower(Url),
        Host = tolower(tostring(extract(@"https?://([^/:\s]+)", 1, Url)))
    | mv-expand IOC = pack_array(Url, Host) to typeof(string)
    | where isnotempty(IOC);
Content
| join kind=inner TI on IOC
| extend AccountName = iff(isempty(Agent), "unknown-agent", Agent)
| project
    TimeGenerated, Direction, AccountName, Agent, Model, ProjectId, ConvId,
    MatchedIOC = IOC, ObservableKey, Confidence,
    ThreatType  = tostring(todynamic(Data).indicator_types[0]),
    Description = tostring(todynamic(Data).description),
    Url, Host, SrcIp
| order by TimeGenerated desc

