// Title: Detection Enrichment - Entra Group Membership Enriched
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Data%20Lake/Jobs/Detection%20Enrichment%20-%20Entra%20Group%20Membership.md
// Section: Sentinel
// Author: Bert-JanP
// Description:
// Sentinel Data Lake job to put an aggregated table of group memberships in LAW for filtering/enrichment in detections and automations.

EntraGroupMemberships
| where TimeGenerated > ago(3d)
| summarize arg_max(TimeGenerated, *) by sourceId, targetId
| join kind=leftouter (EntraGroups | where TimeGenerated > ago(3d) |  summarize arg_max(TimeGenerated, TimeGenerated, description, displayName, groupTypes, mailNickname) by id ) on $left.sourceId == $right.id
| project GroupId = sourceId, ObjectId = targetId, tenantId, organizationId, GroupDescription = description, GroupDisplayName = displayName, groupTypes, mailNickname

// Title: Detection Enrichment - Entra User
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Data%20Lake/Jobs/Detection%20Enrichment%20-%20Entra%20User.md
// Section: Sentinel
// Author: Bert-JanP
// Description:
// Sentinel Data Lake job to put an aggregated table of entra users in LAW for filtering/enrichment in detections and automations.

EntraUsers
| where TimeGenerated > ago(3d)
| summarize arg_max(TimeGenerated, * ) by id
| project-away _*
| project-rename ObjectId = id

