// Title: Follina Detection
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Vulnerability%20Exploitation/Follina.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// Follina Detection

// Sources: https://www.reddit.com/r/blueteamsec/comments/v0wgqh/sentinel_kql_detections_for_microsoft_word_zero/ & https://github.com/reprise99/Sentinel-Queries/blob/main/Defender%20for%20Endpoint/Device-msdtPotentialExploit.kql
    (union isfuzzy=true
    (DeviceProcessEvents
    | where ProcessCommandLine contains "msdt.exe"
    | where InitiatingProcessFileName has_any (@"outlook.exe", @"winword.exe", @"excel.exe")),
    (DeviceProcessEvents
    | where InitiatingProcessCommandLine contains "msdt.exe" and ProcessCommandLine !contains "msdt.exe"),
    (DeviceNetworkEvents
    | where InitiatingProcessFileName has_any ("sdiagnhost.exe", "msdt.exe")
    | where RemoteIPType == "Public"
    | where ActionType == "ConnectionSuccess"
    and RemoteUrl !endswith ".visualstudio.com"
    and RemoteUrl !endswith ".microsoft.com")
    )

// Title: Forensics on Registry Run keys in Windows.
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/DFIR/MDE%20-%20Registry-Run-Keys-Forensics.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// Registry Run keys can be used to establish persistence on a device.
//
// The detection covers the following registry key paths:
//
// ```
// HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run
// HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce
// HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run
// HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce
// HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run
// HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\RunOnce
// ```

let CompromisedDevices = dynamic (["workstation01", "server1"]);
let SearchWindow = 7d; //Customizable h = hours, d = days
DeviceRegistryEvents
| where Timestamp > ago(SearchWindow)
| where DeviceName has_any (CompromisedDevices)
| where RegistryKey endswith @'\Software\Microsoft\Windows\CurrentVersion\Run' or  RegistryKey endswith @'\Microsoft\Windows\CurrentVersion\RunOnce'
| project-reorder Timestamp, ActionType, DeviceId, DeviceName, RegistryKey, PreviousRegistryValueData, InitiatingProcessCommandLine

// Title: Forensics on Registry Run keys in Windows. Registry Run keys can be used to establish persistence on a device.
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/DFIR/Defender%20For%20Endpoint/MDE%20-%20Registry-Run-Keys-Forensics.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// let RegistryRunKeys = dynamic ([@"HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Run", @"HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\RunOnce", @"HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Run", @"HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\RunOnce"]);

let RegistryRunKeys = dynamic 
([@"HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Run",
@"HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\RunOnce",
@"HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Run",  
@"HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\RunOnce"]);
let CompromisedDevices = dynamic (["laptop1", "server1"]);
let SearchWindow = 7d; //Customizable h = hours, d = days
DeviceRegistryEvents
| where Timestamp > ago(SearchWindow)
| where DeviceName has_any (CompromisedDevices)
| where RegistryKey has_any (RegistryRunKeys)
| extend RegistryChangeInfo = bag_pack("RegistryKey", RegistryKey, "Action Performed", ActionType, "Old Value", PreviousRegistryKey, "New Value", RegistryValueData)
| summarize TotalRunKeysChanged = count(), RegistryInfo = make_set(RegistryChangeInfo) by DeviceName

// Title: Forensics on Registry Run keys in Windows. Registry Run keys can be used to establish persistence on a device.
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/DFIR/Defender%20For%20Endpoint/MDE%20-%20Registry-Run-Keys-Forensics.md
// Section: Sentinel
// Author: Bert-JanP
// Description:
// let RegistryRunKeys = dynamic ([@"HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Run", @"HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\RunOnce", @"HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Run", @"HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\RunOnce"]);

let RegistryRunKeys = dynamic 
([@"HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Run",
@"HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\RunOnce",
@"HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Run",
@"HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\RunOnce"]);
let CompromisedDevices = dynamic (["laptop1", "server1"]);
let SearchWindow = 7d; //Customizable h = hours, d = days
DeviceRegistryEvents
| where TimeGenerated > ago(SearchWindow)
| where DeviceName has_any (CompromisedDevices)
| where RegistryKey has_any (RegistryRunKeys)
| extend RegistryChangeInfo = pack_dictionary("RegistryKey", RegistryKey, "Action Performed", ActionType, "Old Value", PreviousRegistryKey, "New Value", RegistryValueData)
| summarize TotalRunKeysChanged = count(), RegistryInfo = make_set(RegistryChangeInfo) by DeviceName

// Title: Forensics on Registry Run keys in Windows.
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/DFIR/MDE%20-%20Registry-Run-Keys-Forensics.md
// Section: Sentinel
// Author: Bert-JanP
// Description:
// Registry Run keys can be used to establish persistence on a device.
//
// The detection covers the following registry key paths:
//
// ```
// HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run
// HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce
// HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run
// HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce
// HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run
// HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\RunOnce
// ```

let CompromisedDevices = dynamic (["workstation01", "server1"]);
let SearchWindow = 7d; //Customizable h = hours, d = days
DeviceRegistryEvents
| where Timestamp > ago(SearchWindow)
| where DeviceName has_any (CompromisedDevices)
| where RegistryKey endswith @'\Software\Microsoft\Windows\CurrentVersion\Run' or  RegistryKey endswith @'\Microsoft\Windows\CurrentVersion\RunOnce'
| project-reorder TimeGenerated, ActionType, DeviceId, DeviceName, RegistryKey, PreviousRegistryValueData, InitiatingProcessCommandLine

