// Title: GraphAPI URI Request Statistics
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Graph%20API/GraphAPIAuditEvents%20-%20GraphURIAPIRequestStats.md
// Section: Sentinel
// Author: Bert-JanP
// Description:
// Retrieving request statistics gives us the opportunity for new use cases. One can now summarize all the GraphAPI request types easily with the following query. The unique deltatokens have been removed from the data, returning a better overview of the executed requests.

GraphAPIAuditEvents
| extend ParsedUri = tostring(parse_url(RequestUri).Path)
| summarize TotalRequest = count() by ParsedUri
| sort by TotalRequest

// Title: GraphAPI URI Request Statistics
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Graph%20API/GraphURIAPIRequestStats.md
// Section: Sentinel
// Author: Bert-JanP
// Description:
// Retrieving request statistics gives us the opportunity for new use cases. One can now summarize all the GraphAPI request types easily with the following query. The unique deltatokens have been removed from the data, returning a better overview of the executed requests.

MicrosoftGraphActivityLogs
| extend ParsedUri = tostring(parse_url(RequestUri).Path)
| summarize TotalRequest = count() by ParsedUri
| sort by TotalRequest

// Title: GraphAPIAuditEvents App Enrichment AADNonInteractiveUserSignInLogs Based
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Graph%20API/GraphAPIAuditEvents%20-%20AppEnrichmentAADNonInteractiveUserSignInLogs.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// This query enriches the *GraphAPIAuditEvents* with Application information from the *AADNonInteractiveUserSignInLogs* table to get more context in the results.
//
// This query does have a limitation, a user must have signed in to the application to show up in the logs. An alternative KQL query is available that leverages the externaldata operator to solve this issue: [GraphAPIAuditEvents App Enrichment ExternalData](./GraphAPIAuditEvents%20-%20AppEnrichmentExternalData.md.md)

let ApplicationName = AADNonInteractiveUserSignInLogs
| where TimeGenerated > ago(30d)
| summarize arg_max(TimeGenerated, *) by ResourceIdentity
| project-rename ApplicationName = ResourceDisplayName
| distinct ApplicationName, ResourceIdentity;
GraphAPIAuditEvents
// Your filter here
| lookup kind=leftouter ApplicationName on $left.ApplicationId == $right.ResourceIdentity
| project-reorder ApplicationId, ApplicationName

// Title: GraphAPIAuditEvents App Enrichment ExternalData Based
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Graph%20API/GraphAPIAuditEvents%20-%20AppEnrichmentExternalData.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// This query enriches the *GraphAPIAuditEvents* with Application information Using the Azure_Application_ID list developed by [@Beercow](https://github.com/Beercow) 1000+ AppIds can be enriched with the [externaldata operator](https://learn.microsoft.com/en-us/azure/data-explorer/kusto/query/externaldata-operator?pivots=azuredataexplorer) resulting in the query below.

let ApplicationInformation = externaldata (ApplicationName: string, AppId: string, Reference: string ) [h"https://raw.githubusercontent.com/Beercow/Azure-App-IDs/master/Azure_Application_IDs.csv"] with (ignoreFirstRecord=true, format="csv");
GraphAPIAuditEvents
// Your filter here
| take 1000
| lookup kind=leftouter ApplicationInformation on $left.ApplicationId == $right.AppId
| project-reorder ApplicationId, ApplicationName

// Title: GraphAPIAuditEvents IP Enrichment
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Graph%20API/GraphAPIAuditEvents%20-%20IPEnrichment.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// The IP information can be enriched using the [geo_info_from_ip_address()](https://learn.microsoft.com/en-us/azure/data-explorer/kusto/query/geo-info-from-ip-address-function) function, which returns the country, state, city, latitude and longitude of each IPv4 and IPv6 address.

GraphAPIAuditEvents
| extend GeoIPInfo = geo_info_from_ip_address(IpAddress)
| extend country = tostring(parse_json(GeoIPInfo).country), state = tostring(parse_json(GeoIPInfo).state), city = tostring(parse_json(GeoIPInfo).city), latitude = tostring(parse_json(GeoIPInfo).latitude), longitude = tostring(parse_json(GeoIPInfo).longitude)
| project-reorder IpAddress, country, state, RequestUri

// Title: GraphAPIAuditEvents User Enrichment
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Graph%20API/GraphAPIAuditEvents%20-%20UserEnrichment.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// This query enriches the *MicrosoftGraphActivityLogs* with userinformation from the *IdentityInfo* table to get more context in the results.

GraphAPIAuditEvents
| where EntityType == "user"
| lookup kind=leftouter (IdentityInfo
    | where TimeGenerated > ago(30d)
    | summarize arg_max(TimeGenerated, *) by AccountObjectId
    | project AccountObjectId, AccountDisplayName, AccountUpn)
    on $left.AccountObjectId == $right.AccountObjectId
| project-reorder AccountDisplayName, AccountUpn, RequestMethod, RequestUri

// Title: Group Membership Report
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Azure%20Active%20Directory/GroupMembershipReport.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// This query can be used to draw an report of the Entra ID group memberships of all users.
//
// Note: if a users has more than 1000 memberships remove the 1000 limitation in the make_set to display all groupnames.

let TimeFrame = 30d;
IdentityInfo
| where Timestamp > ago(TimeFrame)
| summarize arg_max(TimeGenerated, *) by AccountObjectId
| mv-expand GroupMembership
| where isnotempty(GroupMembership)
| summarize TotalMemberships = dcount(tostring(GroupMembership)), MemberOf = make_set(tostring(GroupMembership), 1000) by AccountObjectId, AccountDisplayName, AccountUPN
| extend ReportDate = now()

// Title: Group Membership Report
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Azure%20Active%20Directory/GroupMembershipReport.md
// Section: Sentinel
// Author: Bert-JanP
// Description:
// This query can be used to draw an report of the Entra ID group memberships of all users.
//
// Note: if a users has more than 1000 memberships remove the 1000 limitation in the make_set to display all groupnames.

let TimeFrame = 30d;
IdentityInfo
| where TimeGenerated > ago(TimeFrame)
| summarize arg_max(TimeGenerated, *) by AccountObjectId
| mv-expand GroupMembership
| where isnotempty(GroupMembership)
| summarize TotalMemberships = dcount(tostring(GroupMembership)), MemberOf = make_set(tostring(GroupMembership), 1000) by AccountObjectId, AccountDisplayName, AccountUPN
| extend ReportDate = now()

// Title: Guest user with AD roles
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Azure%20Active%20Directory/GuestUsersWithADRoles.md
// Section: Sentinel
// Author: Bert-JanP
// Description:
// This query can be used to display all Guest users in the tenant who have Azure Active Directory roles. Guest users by default have different rights than normal users, at the time these Guest users get additional roles those permissions change. Therefore, the least privilege principle should be applied to Guest (and all other) users, so that these Guest users cannot access sensitive information.

IdentityInfo
| where UserType == "Guest"
// Collect the most recent information for each Guest user
| summarize arg_max(TimeGenerated, *) by AccountUPN
// Only show Guests that have roles in your tentant
| where array_length(AssignedRoles) > 0
| project AccountUPN, AssignedRoles, IsAccountEnabled

// Title: HTTP Request Methods Statistics
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Defender%20For%20Endpoint/HTTPRequestMethodsStatistics.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// HTTP Request Methods Statistics

DeviceNetworkEvents
| where ActionType == "NetworkSignatureInspected"
| extend
     SignatureName = tostring(parse_json(AdditionalFields).SignatureName),
     SignatureMatchedContent = tostring(parse_json(AdditionalFields).SignatureMatchedContent),
     SamplePacketContent = tostring(parse_json(AdditionalFields).SamplePacketContent)
| where SignatureName == "HTTP_Client"
| extend HTTP_Request_Method = tostring(split(SignatureMatchedContent, " /", 0)[0])
| summarize count() by HTTP_Request_Method

// Title: HTTP Traffic
