// Title: Malicious PowerShell Executions From Clipboard Copy-and-Paste
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Defender%20For%20Endpoint/PowerShellExecutionsFromClipboard.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// This query is to hunt for the threat of Fake CAPTCHA / Bot verification social engineering techniques used by the actor to lure the victim to click copy-and-paste button on the website with malicious powershell for the retrieval of the second stage payload and subsequently executed on the victim's device. The idea of the query is to detect the events of clipboard data being accessed and followed by PowerShell execution under 1 minute of time window.

let clipboardEvents = 
    DeviceEvents
    | where ActionType contains "GetClipboardData" 
    and InitiatingProcessFileName contains "explorer.exe";
let powershellEvents = 
    DeviceProcessEvents
    | where (FileName contains "powershell.exe" and (ProcessCommandLine contains "hidden") and ProcessCommandLine contains "http" and ProcessCommandLine !contains "http://localhost") or (FileName contains "mshta.exe" and ProcessCommandLine contains "http" and ProcessCommandLine !contains "http://localhost");
clipboardEvents
| join kind=inner (powershellEvents) on DeviceName
| where abs(datetime_diff('minute', TimeGenerated, TimeGenerated1)) <= 1
| summarize by DeviceName

// Title: Malware File Detected In Office 365
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Office%20365/MalwareFileDetected.md
// Section: Sentinel
// Author: Bert-JanP
// Description:
// This detects a malware file in your Office 365 environment. This activity does not always raise an alert.

OfficeActivity
| where Operation == "FileMalwareDetected"
| project-reorder TimeGenerated, OfficeWorkload, SourceFileName, OfficeObjectId, UserId

// Title: (Mass) Cloud Resource Deletion
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Cloud%20Audit%20Events/CloudResourceDeletion.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// This query can be used to detect (mass) resource deletion in your cloud environment. The query uses the *Threshold* and *BinSize* variables to trigger. The default is set to the deletion of 20 cloud resources in a timespan of 1 day, you can modify this to your needs.

let Threshold = 20;
let BinSize = 1d;
CloudAuditEvents
| where ActionType == "CloudAuditEventDelete"
| summarize TotalActions = count(), arg_max(Timestamp, *) by bin(Timestamp, BinSize), Account, DataSource
| where TotalActions > Threshold

// Title: MDI Sensor Deleted
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Defender%20XDR/MDISensorDeleted.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// This query returns results when a Defender For Identity Sensor has been deleted. This sensor would have been installed on your Domain Controller, ADCS, ADFS or Entra Connect server.

CloudAppEvents
| where ActionType == "SensorDeleted"
| extend Sensor = tostring(parse_json(RawEventData).ResultDescription), InitiatorUpn = tostring(parse_json(RawEventData).UserId)
| project-reorder Timestamp, Sensor, InitiatorUpn

// Title: MDI Sensor Deleted
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Defender%20XDR/MDISensorDeleted.md
// Section: Sentinel
// Author: Bert-JanP
// Description:
// This query returns results when a Defender For Identity Sensor has been deleted. This sensor would have been installed on your Domain Controller, ADCS, ADFS or Entra Connect server.

CloudAppEvents
| where ActionType == "SensorDeleted"
| extend Sensor = tostring(parse_json(RawEventData).ResultDescription), InitiatorUpn = tostring(parse_json(RawEventData).UserId)
| project-reorder TimeGenerated, Sensor, InitiatorUpn

// Title: Microsoft Teams Emoji Reactions
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Fun/TeamsEmojiReactions.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// This query lists the statistics of the Emoji reactions that have been send via Microsoft Teams

CloudAppEvents
| where Application == "Microsoft Teams"
| where ActionType == "ReactedToMessage"
| extend Emoji = tostring(RawEventData.MessageReactionType)
| where isnotempty(Emoji)
| summarize TotalUsage = count() by Emoji
| sort by TotalUsage

// Title: Microsoft Teams Emoji Reactions for each Department
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Fun/TeamsEmojiReactionsByDepartment.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// This query lists the statistics of the Emoji reactions that have been send via Microsoft Teams for each Department.

CloudAppEvents
| where Application == "Microsoft Teams"
| where ActionType == "ReactedToMessage"
| extend Emoji = tostring(RawEventData.MessageReactionType)
| where isnotempty(Emoji)
| project Emoji, AccountObjectId
| join kind=inner (IdentityInfo
    | where Timestamp > ago(30d)
    | summarize arg_max(Timestamp, *) by AccountObjectId
    | project AccountObjectId, Department)
    on $left.AccountObjectId == $right.AccountObjectId
| project Department, Emoji
| evaluate pivot(Department) // If you want to have the Departments on the y axis use | evaluate pivot(Emoji)

// Title: Microsoft Teams Emoji Reactions for each Department
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Fun/TeamsEmojiReactionsByDepartment.md
// Section: Sentinel
// Author: Bert-JanP
// Description:
// This query lists the statistics of the Emoji reactions that have been send via Microsoft Teams for each Department.

CloudAppEvents
| where Application == "Microsoft Teams"
| where ActionType == "ReactedToMessage"
| extend Emoji = tostring(RawEventData.MessageReactionType)
| where isnotempty(Emoji)
| project Emoji, AccountObjectId
| join kind=inner (IdentityInfo
    | where TimeGenerated > ago(30d)
    | summarize arg_max(TimeGenerated, *) by AccountObjectId
    | project AccountObjectId, Department)
    on $left.AccountObjectId == $right.AccountObjectId
| project Department, Emoji
| evaluate pivot(Department) // If you want to have the Departments on the y axis use | evaluate pivot(Emoji)

// Title: MicrosoftGraphActivityLogs App Enrichment AADNonInteractiveUserSignInLogs Based
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Graph%20API/AppEnrichmentAADNonInteractiveUserSignInLogs.md
// Section: Sentinel
// Author: Bert-JanP
// Description:
// This query enriches the *MicrosoftGraphActivityLogs* with Application information from the *AADNonInteractiveUserSignInLogs* table to get more context in the results.
//
// This query does have a limitation, a user must have signed in to the application to show up in the logs. An alternative KQL query is available that leverages the externaldata operator to solve this issue: [App Enrichment ExternalData](./AppEnrichmentExternalData.md)

let ApplicationName = AADNonInteractiveUserSignInLogs
| where TimeGenerated > ago(30d)
| summarize arg_max(TimeGenerated, *) by ResourceIdentity
| project-rename ApplicationName = ResourceDisplayName
| distinct ApplicationName, ResourceIdentity;
MicrosoftGraphActivityLogs
// Your filter here
| lookup kind=leftouter ApplicationName on $left.AppId == $right.ResourceIdentity
| project-reorder AppId, ApplicationName

// Title: MicrosoftGraphActivityLogs App Enrichment ExternalData Based
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Graph%20API/AppEnrichmentExternalData.md
// Section: Sentinel
// Author: Bert-JanP
// Description:
// This query enriches the *MicrosoftGraphActivityLogs* with Application information Using the Azure_Application_ID list developed by [@Beercow](https://github.com/Beercow) 1000+ AppIds can be enriched with the [externaldata operator](https://learn.microsoft.com/en-us/azure/data-explorer/kusto/query/externaldata-operator?pivots=azuredataexplorer) resulting in the query below.

let ApplicationInformation = externaldata (ApplicationName: string, AppId: string, Reference: string ) [h"https://raw.githubusercontent.com/Beercow/Azure-App-IDs/master/Azure_Application_IDs.csv"] with (ignoreFirstRecord=true, format="csv");
MicrosoftGraphActivityLogs
// Your filter here
| take 1000
| lookup kind=leftouter ApplicationInformation on $left.AppId == $right.AppId
| project-reorder AppId, ApplicationName

// Title: MicrosoftGraphActivityLogs IP Enrichment
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Graph%20API/IPEnrichment.md
// Section: Sentinel
// Author: Bert-JanP
// Description:
// The IP information can be enriched using the [geo_info_from_ip_address()](https://learn.microsoft.com/en-us/azure/data-explorer/kusto/query/geo-info-from-ip-address-function) function, which returns the country, state, city, latitude and longitude of each IPv4 and IPv6 address.

MicrosoftGraphActivityLogs
| extend GeoIPInfo = geo_info_from_ip_address(IPAddress)
| extend country = tostring(parse_json(GeoIPInfo).country), state = tostring(parse_json(GeoIPInfo).state), city = tostring(parse_json(GeoIPInfo).city), latitude = tostring(parse_json(GeoIPInfo).latitude), longitude = tostring(parse_json(GeoIPInfo).longitude)
| project-reorder IPAddress, country, state, RequestUri

// Title: MicrosoftGraphActivityLogs User Enrichment
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Graph%20API/UserEnrichment.md
// Section: Sentinel
// Author: Bert-JanP
// Description:
// This query enriches the *MicrosoftGraphActivityLogs* with userinformation from the *IdentityInfo* table to get more context in the results.

MicrosoftGraphActivityLogs
| where isnotempty(UserId)
| lookup kind=leftouter (IdentityInfo
    | where TimeGenerated > ago(30d)
    | summarize arg_max(TimeGenerated, *) by AccountObjectId
    | project AccountObjectId, AccountDisplayName, AccountUpn)
    on $left.UserId == $right.AccountObjectId
| project-reorder AccountDisplayName, AccountUpn, RequestMethod, RequestUri

// Title: Monitor ransomwarelive for companies of interest on ransowmare data leak sites (DLS)
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Threat%20Hunting/Ransomware%20-%20LeaksiteMontitoring.md
// Section: Defender XDR & Sentinel
// Author: Bert-JanP
// Description:
// This allows you to monitor the ransomware.live dataset for possible companies of interest being breached and posted by ransomware groups on data leak sites (DLS).

// Query group information
let groups = externaldata(
    name: string,
    captcha: bool,
    javascript_render: string,
    parser: bool,
    profile: dynamic,
    locations: dynamic,
    meta: string,)
    [h@"https://api.ransomware.live/groups"]
    with(format="multijson", ignoreFirstRecord=false);
groups
| where name contains "abyss"
| mv-expand locations
| project name, locations.["title"], locations.available, locations.fqdn, ["url"]=locations.slug, locations.updated, locations.version, profile

// Title: Monitor ransomwarelive for companies of interest on ransowmare data leak sites (DLS)
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Threat%20Hunting/Ransomware%20-%20LeaksiteMontitoring.md
// Section: Defender XDR & Sentinel
// Author: Bert-JanP
// Description:
// This allows you to monitor the ransomware.live dataset for possible companies of interest being breached and posted by ransomware groups on data leak sites (DLS).

//query to detect possible third party compromise via leak site data
let clientkeyword = datatable(name:string)["client1","client2","client3","axip","elutia"]; //add clients
let supplierkeyword = datatable(supplier:string)["supplier1","supplier2","supplier3","merchant.id"]; //add suppliers
let thirdpartykeyword = datatable(supplier:string)["thirdparty1","thunderbirdcc"]; //add third parties
let victims = externaldata(country:string,
        description:string,
        Country:string,
        discovered:string,
        discovered:datetime,
        group_name:string,
        post_title:string,
        post_url:string,
        published:string,
        published:datetime,
        screenshot:string,
        website:string)
        website:string,
        infostealer:dynamic)
[h@"https://api.ransomware.live/recentvictims"]
with(format="multijson",ignoreFirstRecord=false);
victims
| where post_title has_any (clientkeyword) or post_title has_any (supplierkeyword) or post_title has_any (thirdpartykeyword)

// Title: MontySecurity C2 Tracker All IPs
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Threat%20Hunting/TI%20Feed%20-%20MontySecurity%20C2%20Tracker%20All%20IPs.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// let ThreatIntelFeed = externaldata(DestIP: string)[@"https://raw.githubusercontent.com/montysecurity/C2-Tracker/main/data/all.txt"] with (format="txt", ignoreFirstRecord=True); let IPRegex = '[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}'; let MaliciousIP = materialize ( ThreatIntelFeed

