// Title: Most Permissive Entities
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Exposure%20Management/MostPermissiveEntities.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// This query lists the top 100 entities that have the most permissions to perform a certain action on a resource. The query extracts the type of permissions, such as reader, contributor, owner and other (custom) roles. It is good practice to review the users with the most permissions, or put additional monitoring on their accounts. Because they are highly priviliged threat actors can perform a lot of actions once the account has been taken over.

// Permission Statistics
ExposureGraphEdges
| where EdgeLabel == "has permissions to"
| extend Type = extract(@'"name":"(.*?)"', 1, tostring(EdgeProperties))
| where isnotempty(Type)
| summarize TotalPermissions = dcount(TargetNodeName), ResourceList = make_set(TargetNodeName, 100), PermissionTypeCount = dcount(Type), PermissionTypes = make_set(Type) by SourceNodeName
| sort by TotalPermissions, SourceNodeName
| project SourceNodeName, TotalPermissions, PermissionTypeCount, ResourceList, PermissionTypes
| top 100 by TotalPermissions

// Title: Most Triggered Incidents
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Security%20Operations/Statistics%20-%20MostTriggeredIncidents.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// The results of this query provide insight in the top 10 incidents that have triggered in your selected *timeframe*, this can give indications on which incidents should be addressed to limit potential false positives.

// Timeframe to collect incident statistics
let timeframe = 7d;
AlertInfo
| where Timestamp > ago(timeframe)
// Collect the first entry of each alert
| summarize arg_min(Timestamp, *) by AlertId
// Get the alert statistics
| summarize Triggers = count(), AlertIds = make_set(AlertId) by Title
| top 10 by Triggers

// Title: Most Triggered Incidents
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Security%20Operations/Statistics%20-%20MostTriggeredIncidents.md
// Section: Sentinel
// Author: Bert-JanP
// Description:
// The results of this query provide insight in the top 10 incidents that have triggered in your selected *timeframe*, this can give indications on which incidents should be addressed to limit potential false positives.

let timeframe = 7d;
SecurityIncident
| where TimeGenerated > ago(timeframe)
// Collect the first entry of each alert
| summarize arg_min(TimeGenerated, *) by IncidentNumber
// Get the alert statistics
| summarize Triggers = count(), AlertIds = make_set(IncidentNumber) by Title
| top 10 by Triggers

// Title: Most Triggered Mitre Techniques
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Security%20Operations/Statistics%20-%20MostTriggeredMitreTechniques.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// The results of this query provide insight in the top 10 MITRE ATT&CK Techniques that have been triggered in the past 10 days. This can indicate that adversaries use specific techniques to gain access to your environment. On the otherhand if this information is combined with FP/BP statistics it can give insight into the detections that need to be improved.

let timeframe = 7d;
AlertInfo
| where Timestamp > ago(timeframe)
// Collect the last entry of each alert
| summarize arg_max(Timestamp, *) by AlertId
// Ensure that events with multiple techniques can be counted
| extend MitreTechnique = todynamic(AttackTechniques)
| mv-expand MitreTechnique
| summarize TriggerCount = count() by tostring(MitreTechnique)
| top 10 by TriggerCount

// Title: Most Triggered Mitre Techniques
