let ThreatIntelFeed = externaldata(DestIP: string)[@"https://threatview.io/Downloads/IP-High-Confidence-Feed.txt"] with (format="txt", ignoreFirstRecord=True);
let IPRegex = '[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}';
let MaliciousIP = materialize (
       ThreatIntelFeed
       | where DestIP matches regex IPRegex
       | distinct DestIP
        );
DeviceNetworkEvents
| where RemoteIP in (MaliciousIP)
| extend GeoIPInfo = geo_info_from_ip_address(RemoteIP)
| extend country = tostring(parse_json(GeoIPInfo).country), state = tostring(parse_json(GeoIPInfo).state), city = tostring(parse_json(GeoIPInfo).city), latitude = tostring(parse_json(GeoIPInfo).latitude), longitude = tostring(parse_json(GeoIPInfo).longitude)
| project-reorder TimeGenerated, DeviceName, RemoteIP, RemotePort, InitiatingProcessAccountName

// Title: Top 10 devices with the most Critical and High vulnerabilities
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Vulnerability%20Management/Top-Devices-Most-Vulnerabilities.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// DeviceTvmSoftwareVulnerabilities

DeviceTvmSoftwareVulnerabilities
| where VulnerabilitySeverityLevel has_any ('critical', 'High')
| summarize count(), VulnerableCVE = make_set(CveId) by DeviceName
| top 10 by count_

// Title: Top 10 devices with the most exploitable vulnerabilities
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Vulnerability%20Management/Top-Devices-Most-Exploitable-Vulnerabilities.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// This query lists the 10 devices in your tenant with the most exploitable vulnerabilities.

let ExploitableVulnerabilities = DeviceTvmSoftwareVulnerabilitiesKB
     | where IsExploitAvailable == 1
     | project CveId;
DeviceTvmSoftwareVulnerabilities
| where CveId in (ExploitableVulnerabilities)
| summarize TotalExploitableVulns = dcount(CveId), ExploitableCVE = make_set(CveId) by DeviceId
| top 10 by TotalExploitableVulns

// Title: Top 10 users with the most ips used to succesfully sign in
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Azure%20Active%20Directory/Top10UsersWithTheMostSignInIPsUsed.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// Collect the top 10 user with the most IP used to succefully sign in to a tenant. This query displays the 10 users that have used the most IP addresses so sign in.
//
// False positives can be a VPN that changes IP addresses, which results in a high number of IPs used to sign in.

AADSignInEventsBeta
| summarize IPsUsed = make_set(IPAddress), locations = make_set(Country) by AccountObjectId
| extend CountIP = array_length(IPsUsed)
| project-reorder CountIP
| top 10 by CountIP

// Title: Top 10 users with the most ips used to succesfully sign in
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Azure%20Active%20Directory/Top10UsersWithTheMostSignInIPsUsed.md
// Section: Sentinel
// Author: Bert-JanP
// Description:
// Collect the top 10 user with the most IP used to succefully sign in to a tenant. This query displays the 10 users that have used the most IP addresses so sign in.
//
// False positives can be a VPN that changes IP addresses, which results in a high number of IPs used to sign in.

SigninLogs
| summarize IPsUsed = make_set(IPAddress), locations = make_set(LocationDetails) by Identity
| extend CountIP = array_length(IPsUsed)
| project-reorder CountIP
| top 10 by CountIP

// Title: Top 100 critical browser extensions with the most permissions required
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Vulnerability%20Management/BrowserExtension%20-%20Top100MostPermissiveExtensionsInstalled.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// DeviceTvmBrowserExtensions

DeviceTvmBrowserExtensions
| where ExtensionRisk == "Critical"
| summarize TotalExtentions = count(), ExtentionNames = make_set(ExtensionName) by DeviceId
| join kind=leftouter DeviceInfo on DeviceId
| project DeviceName, TotalExtentions, ExtentionNames
| top 100 by TotalExtentions

// Title: Top 100 devices with the most browser extensions installed
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Vulnerability%20Management/BrowserExtension%20-%20Top100DevicesWithTheMostBrowserExtensions.md
