// Title: WMIC Antivirus Discovery
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Defender%20For%20Endpoint/WMICAntivirusDiscovery.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// Adversaries can use WMIC to run queries to detect which antivirus solution has been installed on the device. This is usefull for an adversary, because they know what the maturity of the solution is. More advanced groups might even test there malware samples in a contained environment, before running it on the infrected system. There are some common tools that also use WMIC to list the antivirus solutions, in this query they have been filtered. More applications can be added to the list, it is reccommended to use hashes instead of filenames. Because of the various verions of the tools, it is in this case choosen to only list filenames. The common command the is used for this is:
//
// ```
// cmd.exe WMIC /Node:localhost /Namespace:\\root\SecurityCenter2 Path AntiVirusProduct Get displayName /Format:List
// ```

DeviceProcessEvents
// Filter only on WMIC executions
| where FileName =~ "WMIC.exe"
// Only serach for AntiVirusProduct lists in the commandline, actual malicious activity could look like cmd.exe WMIC /Node:localhost /Namespace:\\root\SecurityCenter2 Path AntiVirusProduct Get displayName /Format:List
| where ProcessCommandLine contains "AntiVirusProduct"
| project Timestamp, DeviceName, ActionType, FolderPath, ProcessCommandLine, InitiatingProcessCommandLine, AccountUpn, InitiatingProcessFileName
// Known Applications to trigger antiviruscheck, would be better to filter on hash but that needs to be done for your environment.
| where not(InitiatingProcessFileName in~('pycharm64.exe', 'pycharm.exe', 'idea64.exe', 'rider64.exe'))

// Title: WMIC Antivirus Discovery
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Defender%20For%20Endpoint/WMICAntivirusDiscovery.md
// Section: Sentinel
// Author: Bert-JanP
// Description:
// Adversaries can use WMIC to run queries to detect which antivirus solution has been installed on the device. This is usefull for an adversary, because they know what the maturity of the solution is. More advanced groups might even test there malware samples in a contained environment, before running it on the infrected system. There are some common tools that also use WMIC to list the antivirus solutions, in this query they have been filtered. More applications can be added to the list, it is reccommended to use hashes instead of filenames. Because of the various verions of the tools, it is in this case choosen to only list filenames. The common command the is used for this is:
//
// ```
// cmd.exe WMIC /Node:localhost /Namespace:\\root\SecurityCenter2 Path AntiVirusProduct Get displayName /Format:List
// ```

DeviceProcessEvents
// Filter only on WMIC executions
| where FileName =~ "WMIC.exe"
// Only serach for AntiVirusProduct lists in the commandline, actual malicious activity could look like cmd.exe WMIC /Node:localhost /Namespace:\\root\SecurityCenter2 Path AntiVirusProduct Get displayName /Format:List
| where ProcessCommandLine contains "AntiVirusProduct"
| project TimeGenerated, DeviceName, ActionType, FolderPath, ProcessCommandLine, InitiatingProcessCommandLine, AccountUpn, InitiatingProcessFileName
// Known Applications to trigger antiviruscheck, would be better to filter on hash but that needs to be done for your environment.
| where not(InitiatingProcessFileName in~('pycharm64.exe', 'pycharm.exe', 'idea64.exe', 'rider64.exe'))

// Title: WMIC Remote Command Execution
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Defender%20For%20Endpoint/Living%20Off%20The%20Land/WMICRemoteCommand.md
// Section: Defender XDR
// Author: Bert-JanP
// Description:
// Adversaries can use WMIC to remotely execute commands, WMIC has been used various times in the wild by different adversaries. WMI is an administration feature that provides a uniform environment to access Windows system components. The WMI service enables both local and remote access. WMIC has been used to call remote processes to perform lateral movement. This query detects all WMIC queries that contain a IP address, which in most cases would be a remote IP address. WMIC can perform various tasks, such as creating processes, executing remote calls and executing (remote) scripts.

let IPRegex = '[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}';
DeviceProcessEvents
| where FileName =~ "WMIC.exe"
// Extract IP Addresses from the commandline
| extend RemoteIP = extract(IPRegex, 0, ProcessCommandLine)
// Only select commandlines that have a remote IP
| where isnotempty(RemoteIP)
// Filter Localhost, more IPs can be added to this list if they generate false postives.
| where not( RemoteIP in ('127.0.0.1'))
| project Timestamp, DeviceName, ProcessCommandLine, RemoteIP

// Title: WMIC Remote Command Execution
// Source: https://github.com/Bert-JanP/Hunting-Queries-Detection-Rules/blob/main/Defender%20For%20Endpoint/Living%20Off%20The%20Land/WMICRemoteCommand.md
// Section: Sentinel
// Author: Bert-JanP
// Description:
// Adversaries can use WMIC to remotely execute commands, WMIC has been used various times in the wild by different adversaries. WMI is an administration feature that provides a uniform environment to access Windows system components. The WMI service enables both local and remote access. WMIC has been used to call remote processes to perform lateral movement. This query detects all WMIC queries that contain a IP address, which in most cases would be a remote IP address. WMIC can perform various tasks, such as creating processes, executing remote calls and executing (remote) scripts.

let IPRegex = '[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}';
DeviceProcessEvents
| where FileName =~ "WMIC.exe"
// Extract IP Addresses from the commandline
| extend RemoteIP = extract(IPRegex, 0, ProcessCommandLine)
// Only select commandlines that have a remote IP
| where isnotempty(RemoteIP)
// Filter Localhost, more IPs can be added to this list if they generate false postives.
| where not( RemoteIP in ('127.0.0.1'))
| project TimeGenerated, DeviceName, ProcessCommandLine, RemoteIP

// Title: Alerts related to Deception in Microsoft Defender XDR
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/03.SecOps/alerts-related-to-deception-in-microsoft-defender-xdr.md
// Section: Microsoft Sentinel
// Author: cyb3rmik3
// Description:
// The following query will identify alerts in Microsoft Sentinel, related to the Deception capability of Microsoft Defender XDR.

let Timeframe = 7d; // Choose proper timeframe
AlertEvidence
| where TimeGenerated > ago(Timeframe)
| mv-expand AdditionalFields
| extend AlertTags = parse_json(AdditionalFields.Tags)
| mv-expand AlertTags
| extend DeceptionTags = parse_json(AlertTags.TagName)
| where DeceptionTags == "Deception"
| project TimeGenerated, DeceptionTags, AlertId, Title, Categories, AttackTechniques, ServiceSource, DetectionSource, EntityType, EvidenceRole, DeviceId, DeviceName, LocalIP
| sort by TimeGenerated desc

// Title: Average Daily Ingestion per Table and Plan
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/Sentinel/average-daily-ingestion-per-table-and-plan.md
// Section: Microsoft Sentinel
// Author: cyb3rmik3
// Description:
// The following query calculates the average daily ingestion for each table and plan over the last Timeframe of days as defined in the let statement. It also allows you to define the size of fractional part to fit your need and attention to detail. This query help baseline normal usage and identify outliers.

let Timeframe = 30d; // Define the required Timeframe
let decfra = 2; // Determine the size of fractional part to fit your need
Usage
| where TimeGenerated >= startofday(ago(Timeframe))
| where IsBillable == true
| summarize DailyGB = sum(Quantity) / 1000.0 by bin(TimeGenerated, 1d), DataType, Plan
| summarize AvgDailyGB = round(avg(DailyGB), decfra) by DataType, Plan
| order by AvgDailyGB desc

// Title: Binaries using AnyDesk Compromised Certificate
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/01.ThreatHunting/binaries-using-anydesk-compromised-certificate.md
// Section: Microsoft Defender XDR
// Author: cyb3rmik3
// Description:
// The following query will hunt for binaries not related to AnyDesk, signed with a potentially compromised signing certificate of AnyDesk.

let Timeframe = 7d; // Choose the best timeframe for your investigation
let SuspiciousAnydeskFileCertificate = DeviceFileCertificateInfo
    | where Timestamp > ago(Timeframe)
    | where CertificateSerialNumber =~ "0dbf152deaf0b981a8a938d53f769db8" // Compromised Certificate Serial Number
    | where Issuer == "DigiCert Trusted G4 Code Signing RSA4096 SHA384 2021 CA1"
    | project Timestamp, DeviceName, SHA1;
SuspiciousAnydeskFileCertificate
    | join (DeviceProcessEvents
    | where Timestamp > ago(Timeframe)
    | where ProcessVersionInfoCompanyName !contains @"AnyDesk"
    | project SHA1, ActionType, FileName, FolderPath, ProcessVersionInfoCompanyName, ProcessVersionInfoProductName, ProcessCommandLine, AccountName, InitiatingProcessAccountName, InitiatingProcessFileName, InitiatingProcessCommandLine
    )on SHA1
    | sort by Timestamp desc

// Title: Changing PowerShell execution policy to insecure level
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/01.ThreatHunting/changing-powershell-execution-policy-to-insecure-level.md
// Section: Microsoft XDR
// Author: cyb3rmik3
// Description:
// PowerShell's execution policy is a safety feature that controls the conditions under which PowerShell loads configuration files and runs scripts. This query will help you identify execution policy changes. Also, you may fine tune the query by excluding InitiatingProcessFileName and InitiatingProcessParentFileName from your environment's applications.

let Timeframe = 7d; // Choose the best timeframe for your investigation
let cmdlet = dynamic([@'-executionpolicy ', @' -ep ', @' -exec ']); 
let parameters = dynamic([@'Bypass ', @'Unrestricted']); 
let exinitapps = datatable(excludedinitapps :string)  // Add as many initiating process filenames you would like to exclude
 ["applicationfilename1.exe",
  "applicationfilename2.exe",
  "applicationfilename3.exe"];
  let exparinitapps = datatable(excludedparinitapps :string)  // Add as many initiating parent process filenames you would like to exclude
 ["applicationfilename1.exe",
  "applicationfilename2.exe",
  "applicationfilename3.exe"];
DeviceProcessEvents
    | where Timestamp > ago(Timeframe)
    | where ProcessCommandLine has_any(cmdlet) and ProcessCommandLine has_any(parameters)
    | where not(InitiatingProcessFileName in (['exinitapps']))
    | where not(InitiatingProcessParentFileName in (['exparinitapps']))
    | sort by Timestamp desc

// Title: Check if Defender EASM IPs or Hosts are mentioned in DDosia Project current configuration
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/EASM/check-if-defender-easm-ips-or-hosts-are-mentioned-in-ddosia-project-current-configuration.md
// Section: Microsoft Sentinel
// Author: cyb3rmik3
// Description:
// The following query will check the DDoSia latest configuration to match IPs and Domains that are part of organization's Defender EASM. As a prerequisite, Defender EASM connector should be enabled in Microsoft Sentinel.

let DDosiaIntelligence = externaldata(host: string, ip: string)[@"https://witha.name/data/last.csv"] 
    with (format="csv", ignoreFirstRecord=True);
let ddosia_data = DDosiaIntelligence
    | summarize by host, ip
    | extend ddosia_clean_host = replace(@"^www\.", "", host) // Remove www. to match EASM Domain_s
    | project-rename ddosia_host=ddosia_clean_host, ddosia_ip=ip;
// Check if there is an IP match
let ip_query = ddosia_data
| join kind=inner (
    EasmHostAsset_CL 
    | extend individual_ip = parse_json(IpAddresses_s)
    | mv-expand individual_ip // Expand all available IPs related to a Domain in EASM
    | extend IpAddresses_s_ = tostring(individual_ip)
    | project TimeGenerated, IpAddresses_s_
) 
on $left.ddosia_ip == $right.IpAddresses_s_;
// Check if there is a Host/Domain match
let host_query = ddosia_data
| join kind=inner (
    EasmHostAsset_CL 
    | extend asset_host = tostring(parse_json(Domain_s))
    | project TimeGenerated, asset_host
)
on $left.ddosia_host == $right.asset_host;
// Combine all results using the union operator
ip_query
| union host_query

