// Title: CVE-2023-36884 Dropped file hunting
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/01.ThreatHunting/CVE-2023-36884-dropped-file.md
// Section: Microsoft 365 Defender & Microsoft Sentinel
// Author: cyb3rmik3
// Description:
// Following relevant puplic reports of analysis with regards to CVE-2023-36884 exploitation, the following query can help hunt for the second stage dropped file.

DeviceFileEvents
| where ActionType == "FileCreated"
| where FolderPath startswith @"C:\Users\"
| where FolderPath contains @"\AppData\Roaming\Microsoft\Office\Recent\"
| where FolderPath endswith @"\file001.url"

// Title: CVE-2023-36884 URL marker
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/01.ThreatHunting/CVE-2023-36884-url-marker.md
// Section: Microsoft 365 Defender & Microsoft Sentinel
// Author: cyb3rmik3
// Description:
// Following relevant puplic reports of analysis with regards to CVE-2023-36884 exploitation, the following query can help hunt a unique URL marker identified.

DeviceNetworkEvents 
| where ActionType == "HttpConnectionInspected"
| extend json = todynamic(AdditionalFields)
| extend method = tostring(json.method), uri = tostring(json.uri), direction = tostring(json.direction)
| where method == "GET"
| where uri contains "/MSHTML_C7/"
| where direction == 'Out'

// Title: CVE-2023-36884 WinRAR spawning CMD
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/01.ThreatHunting/CVE-2023-38831-winrar-spawning-cmd.md
// Section: Microsoft 365 Defender & Microsoft Sentinel
// Author: cyb3rmik3
// Description:
// If you are using a RARLabs WinRAR version prior to 6.23, you are vulnerable to CVE-2023-36884 which allows RCE. A benign file like PDF or JPG could facilitate the execution of arbitrary code.

DeviceProcessEvents
| where InitiatingProcessParentFileName has @"winrar.exe"
| where InitiatingProcessFileName has @"cmd.exe"
| project Timestamp, DeviceName, FileName, FolderPath, ProcessCommandLine, AccountName
| sort by Timestamp desc

// Title: CVE-2024-3094 Internet Facing Devices
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/01.ThreatHunting/CVE-2024-3094-internet-facing-devices.md
// Section: Microsoft Defender XDR & Microsoft Sentinel
// Author: cyb3rmik3
// Description:
// Following recently surfaced news about CVE-2024-3094 vulnerability, the following query can help hunt devices identified with the relevant CVE and are internet facing.

// Define CVE-2024-3094 as CVEID
let xzcvedevices = DeviceTvmSoftwareVulnerabilities
| where CveId == "CVE-2024-3094"
| project DeviceId;
xzcvedevices
| join (DeviceInfo
| where IsInternetFacing == "1" // 1 for internet facing devices, 0 for non-internet facing devices
