// Title: Estimate Potential Savings by Moving Tables to Data Lake
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/Sentinel/estimate-potential-savings-by-moving-tables-to-data-lake.md
// Section: Microsoft Sentinel
// Author: cyb3rmik3
// Description:
// The following query simulates cost savings if high-volume tables currently on Analytics were moved to Data Lake, using hypothetical prices. While this query could help support cost optimization decisions, don't forget to take into account processing and retention costs.

let AnalyticsPricePerGB = 2.48; // Example price per GB for Analytics
let DataLakePricePerGB = 0.05; // Example price per GB for Data Lake
Usage
| where TimeGenerated >= startofday(ago(30d))
| where IsBillable == true
| summarize IngestedGB = round(sum(Quantity) / 1000.0, 2) by DataType, Plan
| where Plan == "Analytics"
| extend CurrentCost = round(IngestedGB * AnalyticsPricePerGB, 2)
| extend IfDataLakeCost = round(IngestedGB * DataLakePricePerGB, 2)
| extend PotentialSavings = round(CurrentCost - IfDataLakeCost, 2)
| where PotentialSavings > 0
| project DataType, IngestedGB, CurrentCost, IfDataLakeCost, PotentialSavings
| order by PotentialSavings desc

// Title: Exposure management browser cookies with credentials of privileged users
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/01.ThreatHunting/exposure-management-browser-cookies-with-credentials-of-privileged-users.md
// Section: Microsoft Defender XDR
// Author: cyb3rmik3
// Description:
// This hunting query will look in ExposureGraphEdges table for stored credentials, that match users that are privileged.

let PriveledgedRoles = dynamic(['Global Administrator', 'User Administrator']); // Add Entra ID roles you would like to monitor
ExposureGraphEdges
    | where EdgeLabel has "has credentials of"
    | extend parsedData = parse_json(EdgeProperties)
    | extend browserCookies = parsedData.rawData.browserCookies.browserCookies
    | where browserCookies == "true"
    | project SourceNodeName, SourceNodeLabel, TargetNodeName
| join (IdentityInfo
    | mv-expand AssignedRoles
    | where AssignedRoles has_any(PriveledgedRoles)
    | project AccountName
    )
on $left.TargetNodeName == $right.AccountName

// Title: Fetch dynamic and manual tags for active devices
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/Defender%20For%20Endpoint/fetch-dynamic-and-manual-tags-for-active-devices.md
// Section: Microsoft Defender XDR
// Author: cyb3rmik3
// Description:
// This query takes into account the DeviceInfo table and will provide the devices based on OSPlatform value (Windows10, Windows11 etc) and what you consider as an inactive device (last seen 7 days for example) and will identify for each device its tags, whether dynamic or manual.

// Define which devices are of interest based on OSPlatform value
let OS = dynamic(["Windows10","Windows11"]);
// Set the threshold for what counts as an active device
// Devices not seen in the last 7 days (or choose otherwise) will be excluded
let ActiveThresholdDays = 7;
DeviceInfo
| where OSPlatform has_any (OS)
| extend LastSeen = Timestamp
// Normalize the dynamic and manual tags columns
| extend DynamicTagsArray = iif(isnull(DeviceDynamicTags), 
    dynamic([]), todynamic(DeviceDynamicTags))
| extend ManualTagsArray  = iif(isnull(DeviceManualTags),  
    dynamic([]), todynamic(DeviceManualTags))
// Combine both manual and dynamic tags into a single array per device
| extend AllTags = array_concat(DynamicTagsArray, ManualTagsArray)
// Exclude devices with no tags
| where array_length(AllTags) > 0  
| mv-expand Tag=AllTags
| extend Tag = tostring(Tag)
| extend DaysSinceLastSeen = datetime_diff("day", now(), LastSeen)
| where DaysSinceLastSeen <= ActiveThresholdDays
| summarize HasTag=any(true) by DeviceName, Tag
// Replace the boolean flag (1) with an emoji for readability in the results
// If the device has tag, mark with ✅, otherwise leave blank
| extend HasTagMark = iif(HasTag == true, "✅", "")
| evaluate pivot(Tag, any(HasTagMark), DeviceName)

// Title: Get to know your MISP threat intelligence feed
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/03.SecOps/get-to-know-your-misp-threat-intelligence-feed.md
// Section: Microsoft Sentinel
// Author: cyb3rmik3
// Description:
// If you are aggregating a MISP instance for your threat intelligence feed in Microsoft Sentinel (or Unified SecOps, then your ThreatIntelligenceIndicator table will be able to provide some fruitful numbers on how your MISP is overall contributing. The following queries are some ideas that will allow you an overall better understanding of your MISP feed.

// Piechart of MISP IoCs by Threat Type
ThreatIntelligenceIndicator
| where isnotempty(TimeGenerated) and SourceSystem == 'MISP'
| summarize count() by ThreatType
| render piechart with(title="MISP IoCs by Threat Type")

// Piechart of MISP IoCs by TLP
ThreatIntelligenceIndicator
| where isnotempty(TimeGenerated) and SourceSystem == 'MISP'
| summarize count() by TrafficLightProtocolLevel
| render piechart with(title="MISP IoCs by Traffic Light Protocol Level")

// Count of ingested IoCs over a period of time
ThreatIntelligenceIndicator
| where isnotempty(TimeGenerated) and SourceSystem == 'MISP'
| where TimeGenerated between (datetime(2024-01-01) .. datetime(2024-11-30)) 
| summarize IoCsCount=count_distinct(IndicatorId) by bin(TimeGenerated, 7d)
| render timechart

// A barchart of count of Tags
ThreatIntelligenceIndicator
| where isnotempty(TimeGenerated) and SourceSystem == 'MISP'
| mv-expand todynamic(Tags)
| summarize count() by tostring(Tags)
| render barchart

// Title: Identification of risky users risk dismissal or account compromised confirmation
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/03.SecOps/identification-of-risky-users-risk-dismissal-or-account-compromised-confirmation.md
// Section: Microsoft Sentinel
// Author: cyb3rmik3
// Description:
// The following query will identify through Microsoft Entra ID Protection capacity, risky users operations that include risk dismissal or account compromised confirmation.

let Timeframe = 90d;
AuditLogs
    | where TimeGenerated > ago(Timeframe)
    // Choose whether you want to focus on DissmissUser or ConfirmAccountCompromised operations
    //| where OperationName == "DismissUser"
    //| where OperationName == "ConfirmAccountCompromised"
    | extend SuspUser = tostring(TargetResources[0].displayName)
    // Add here the name of the user you want to focus on
    //| where SuspUser contains @""
    | extend SecUser = InitiatedBy.user.userPrincipalName
    // Add here the name of the security operator that confirmed account compromized
    //| where SecUser contains @""
    | project TimeGenerated, SuspUser, SecUser
    | sort by TimeGenerated desc

// Title: Identify activities in log analytics workspace resource locks
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/Azure/identify-activities-in-log-analytics-workspace-resource-locks.md
// Section: Microsoft Sentinel
// Author: cyb3rmik3
// Description:
// The following query which would identify activities related to your log analytics workspace relevant resource group locks. That way if someone decides to either edit or delete your lock, you would be able to detect it.

let LAWResourceGroup = @"<your log analytics workspace resource group here>"; // Define Resource Group containing Sentinel's LAW
AzureActivity
| where ResourceGroup == LAWResourceGroup
| where OperationNameValue startswith "MICROSOFT.AUTHORIZATION/LOCKS"
| where ActivityStatusValue == "Success"
| extend EventSubmissionTimeStamp = tostring(parse_json(Properties).eventSubmissionTimestamp)
| extend EventCaller = tostring(parse_json(Properties).caller)
| extend EventCallerIPAddress = tostring(parse_json(tostring(parse_json(Properties).httpRequest)).clientIpAddress)
| extend EventMessage = tostring(parse_json(Properties).message)
| extend LocksAction = extract(@"Microsoft\.Authorization\/locks\/(\w+)", 1, EventMessage)
| extend EventRoleDefinitionId = tostring(parse_json(tostring(parse_json(tostring(parse_json(Properties).requestbody)).Properties)).RoleDefinitionId)
| project EventSubmissionTimeStamp, EventCaller, EventCallerIPAddress, LocksAction

// Title: Identify and summarize processor families in your environment
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/MDVM/identify-and-summarize-processor-families-in-your-environment.md
// Section: Microsoft Defender XDR
// Author: cyb3rmik3
// Description:
// The following query leverages DeviceTvmHardwareFirmware and will help you build an estate of your environment’s processors which will allow you to identify possibly old and non-reliable devices in your organization.

DeviceTvmHardwareFirmware 
| where ComponentType == @"Processor"
| project ProcFamily = parse_json(AdditionalFields)["Family"]
| summarize count() by tostring(ProcFamily)
| sort by ProcFamily asc

// Title: Identify assets from MDEASM in Exposure Management
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/XSPM/identify-assets-from-mdeasm-in-exposure-management.md
// Section: Microsoft Defender XDR
// Author: cyb3rmik3
// Description:
// The following query will help identify which assets are available from Microsoft Defender External Attack Surface Management in the Advanced Hunting tables from Exposure Management.

ExposureGraphNodes
| extend deepLinkInfo = parse_json(NodeProperties)["rawData"]["deepLink"]
| where deepLinkInfo startswith "https://portal.azure.com/#view/Microsoft_Azure_EASM/"

// Title: Identify browser extensions with “Can turnoff malware protections” permissions in endpoints with no tamper protection
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/MDVM/identify-browser-extensions-with-can-turnoff-malware-protections-permissions-in-endpoints-with-no-tamper-protection.md
// Section: Microsoft Defender XDR
// Author: cyb3rmik3
// Description:
// The following query leverages DeviceTvmBrowserExtensionsKB and DeviceTvmBrowserExtensions tables which are available at the Microsoft Defender Vulnerability Management (MDVM) add-on license. Results provided include browser extensions with “Can turnoff malware protections” permissions in endpoints with no tamper protection.

let BrowserExtMalwareProtectionKB = DeviceTvmBrowserExtensionsKB
    | where PermissionName contains "Can turn off malware protections"
    | project ExtensionId, ExtensionName, ExtensionRisk, PermissionName;
let BrowserExtMalwareProtection = DeviceTvmBrowserExtensions
    | project ExtensionId, DeviceId;
let DeviceWoTamperProtection = DeviceTvmSecureConfigurationAssessment
    | where ConfigurationId has "scid-2003"
    | where IsCompliant == "0"
    | where IsApplicable == "1"
    | project DeviceId, DeviceName, OSPlatform, Timestamp;
union BrowserExtMalwareProtection, BrowserExtMalwareProtectionKB,
        DeviceWoTamperProtection
    | summarize by ExtensionId, DeviceId
    | join ( BrowserExtMalwareProtectionKB ) on ExtensionId
    | join kind=rightouter ( BrowserExtMalwareProtection ) on ExtensionId
    | join ( DeviceWoTamperProtection ) on DeviceId
    | summarize DeviceCount=dcount(DeviceName), arg_max(Timestamp, *) by ExtensionName, ExtensionRisk
    | sort by DeviceCount asc, ExtensionRisk

// Title: Identify CVEs in MDEASM web pages through Exposure Management
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/XSPM/identify-cves-in-mdeasm-web-pages-through-exposure-management.md
// Section: Microsoft Defender XDR
// Author: cyb3rmik3
// Description:
// The following query will help identify CVEs associated with web pages from MDEASM in the Advanced Hunting tables from Exposure Management.

let WebPages = ExposureGraphNodes
| where NodeLabel == "web-page"
| project NodeId, NodeName;
WebPages
| join kind=inner (
    ExposureGraphEdges
    | where EdgeLabel == "affecting"
    | where SourceNodeLabel == "Cve"
    | project SourceNodeId, TargetNodeId, SourceNodeName
) on $left.NodeId == $right.TargetNodeId
| project Node=TargetNodeId, NodeName, VulnerabilityCVE=SourceNodeName
| order by NodeName

// Title: Identify endpoint browser extensions with “Can turnoff malware protections” permissions
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/MDVM/identify-endpoint-browser-extensions-with-can-turnoff-malware-protections-permissions.md
// Section: Microsoft Defender XDR
// Author: cyb3rmik3
// Description:
// The following query leverages DeviceTvmBrowserExtensions and DeviceTvmBrowserExtensionsKB tables wich are available at the Microsoft Defender Vulnerability Management (MDVM) add-on license. Results provided include endpoints which have browser extensions installed with “Can turnoff malware protections” permissions.

let BrowserExtMalwareProtectionKB = DeviceTvmBrowserExtensionsKB 
    | where PermissionName contains "Can turn off malware protections"
    | project ExtensionId, ExtensionName, ExtensionRisk, PermissionName;
let BrowserExtMalwareProtection = DeviceTvmBrowserExtensions
    | project ExtensionId, DeviceId;
let DeviceInformation = DeviceInfo
    | project DeviceId, DeviceName, Timestamp;
union BrowserExtMalwareProtection, BrowserExtMalwareProtectionKB,
        DeviceInformation
    | summarize by ExtensionId, DeviceId
    | join ( BrowserExtMalwareProtectionKB ) on ExtensionId
    | join kind=rightouter ( BrowserExtMalwareProtection ) on ExtensionId
    | join ( DeviceInformation ) on DeviceId
    | summarize DeviceCount=dcount(DeviceName), arg_max(Timestamp, *) by ExtensionName, ExtensionRisk
    | sort by DeviceCount asc, ExtensionRisk

// Title: Identify endpoints associated with multiple DeviceIds
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/03.SecOps/endpoints-associated-with-multiple-deviceids.md
// Section: Microsoft 365 Defender
// Author: cyb3rmik3
// Description:
// There are cases where devices might be formatted and get the same hostname as before, MDE will keep both devices in Security Center, however the depreciated machine's logs will be kept for 6 months. This query will help identify endpoint hostnames associated with multiple DeviceIds.

DeviceInfo
// Definde timeframe below
| where TimeGenerated > ago(90d)
| where isnotempty(DeviceId)
| summarize DeviceCount = dcount(DeviceId) by DeviceName
| where DeviceCount > 1
| project DeviceName, DeviceCount

// Title: Identify endpoints associated with multiple DeviceIds
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/03.SecOps/endpoints-associated-with-multiple-deviceids.md
// Section: Microsoft 365 Defender
// Author: cyb3rmik3
// Description:
// There are cases where devices might be formatted and get the same hostname as before, MDE will keep both devices in Security Center, however the depreciated machine's logs will be kept for 6 months. This query will help identify endpoint hostnames associated with multiple DeviceIds.

DeviceInfo
// Definde timeframe below
| where Timestamp > ago(90d)
| where isnotempty(DeviceId)
| summarize DeviceCount = dcount(DeviceId) by DeviceName
| where DeviceCount > 1
| project DeviceName, DeviceCount

// Title: Identify endpoints removed from isolation
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/03.SecOps/identify-endpoints-removed-from-isolation.md
// Section: Microsoft Defender XDR
// Author: cyb3rmik3
// Description:
// The following query will return endpoints which have been removed from isolation by looking into relevant registry modifications.

DeviceRegistryEvents
| where ActionType == "RegistryValueDeleted"
| where PreviousRegistryKey == @"HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows Advanced Threat Protection"
| where RegistryValueType == "None"
| where PreviousRegistryValueData == "1"
| where PreviousRegistryValueName == "DisableEnterpriseAuthProxyValueToRestoreAfterIsolation"
| project Timestamp, DeviceId, DeviceName

// Title: Identify endpoints running WSL without MDE plug-in
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/03.SecOps/identify-endpoints-running-wsl-without-mde-plug-in.md
// Section: Microsoft Sentinel & Defender XDR
// Author: cyb3rmik3
// Description:
// The following query will identify endpoints running Windows Subsystem for Linux (WSL) without the WSL Microsoft Defender for Endpoint plug-in.

let WSLDevices = DeviceProcessEvents
| where ActionType has "ProcessCreated"
| where ProcessVersionInfoOriginalFileName has "wsl.exe"
| where ProcessVersionInfoFileDescription has "Windows Subsystem for Linux"
| project DeviceName;
WSLDevices
    | join kind=leftanti (DeviceTvmSoftwareInventory
    | where SoftwareName has "microsoft_defender_for_endpoint_plug-in_for_wsl"
    | project DeviceName
) on DeviceName
| distinct DeviceName

// Title: Identify endpoints that run WSL
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/03.SecOps/identify-endpoints-running-wsl.md
// Section: Microsoft Sentinel & Defender XDR
// Author: cyb3rmik3
// Description:
// The following query will identify endpoints running Windows Subsystem for Linux (WSL).

DeviceProcessEvents
| where ActionType has "ProcessCreated"
| where ProcessVersionInfoOriginalFileName has "wsl.exe"
| where ProcessVersionInfoFileDescription has "Windows Subsystem for Linux"
| summarize by DeviceName

// Title: Identify endpoints where MitigationStatus is Isolated
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/03.SecOps/identify-endpoints-where-mitigationstatus-is-isolated.md
// Section: Microsoft Defender XDR
// Author: cyb3rmik3
// Description:
// The following query will leverage the DeviceInfo table and identify endpoints where MitigationStatus Isolation equals true. It will also the logged on UserName and Domain.

let Timeframe = 4h; // Choose the best timeframe for your investigation
DeviceInfo
| where Timestamp > ago(Timeframe)
| summarize arg_max(Timestamp, *) by DeviceId //only look at the most recent entry
| extend DeviceUser = parse_json(LoggedOnUsers)
| mv-expand DeviceUser
| extend LoggedOnUsername = tostring(DeviceUser.UserName)
| extend LoggedOnDomainName = tostring(DeviceUser.DomainName)
| extend MitigationStatusObject = parse_json(MitigationStatus)
| mv-expand MitigationStatusObject
| extend IsolationStatus = tostring(MitigationStatusObject.Isolated)
| where IsolationStatus == "true"
| project Timestamp, DeviceId, DeviceName, OSPlatform, LoggedOnUsername, LoggedOnDomainName, IsolationStatus

// Title: Identify hosts with High or Critical vulnerabilities and a CVSS score over 8
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/XSPM/identify-mdeasm-hosts-with-high-or-critical-vulnerabilities-and-a-cvss-score-over-8.md
// Section: Microsoft Defender XDR
// Author: cyb3rmik3
// Description:
// The following query will uncover hosts that are available from Microsoft Defender External Attack Surface Management with High or Critical vulnerabilities and a CVSS score over 8 in the Advanced Hunting tables from Exposure Management.

ExposureGraphNodes
| where NodeLabel == @"dns-host"
| extend GraphNodeProperties = parse_json(NodeProperties)
| where GraphNodeProperties["rawData"]["highRiskVulnerabilityInsights"]["hasHighOrCritical"] == "true"
| where toreal(GraphNodeProperties["rawData"]["highRiskVulnerabilityInsights"]["maxCvssScore"]) > 8
| extend CVSSScore = parse_json(NodeProperties)["rawData"]["highRiskVulnerabilityInsights"]["vulnerableToRemoteCodeExecution"]["maxCvssScore"]
| project NodeId, Host=NodeName, CVSSScore

// Title: Identify how quick a confirmed compromised account changed password
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/03.SecOps/identify-how-quick-a-confirmed-compromised-account-changed-password.md
// Section: Microsoft Sentinel
// Author: cyb3rmik3
// Description:
// The following query will identify how much time has occurred since a confirmed compromised account, changed password.

// Define the timeframe you would like to look into
let timeframe = 90d;
AuditLogs
    | where TimeGenerated > ago(timeframe)
    | where OperationName == "ConfirmAccountCompromised"
    | extend SuspUser = tostring(TargetResources[0].userPrincipalName)
    | project SuspUser, ConfirmTime=TimeGenerated
| join kind=inner (
    AuditLogs
    | where TimeGenerated > ago(timeframe)
    | where OperationName == "Reset user password" or OperationName == "Reset password (self-service)" or OperationName == "Change user password"
    | where Result == "success"
    | extend SuspUserPw = tostring(TargetResources[0].userPrincipalName)
    | project SuspUserPw, PwChangeTime = TimeGenerated, OperationName
    )
on $left.SuspUser == $right.SuspUserPw
| project SuspUser, ConfirmTime, SuspUserPw, PwChangeTime, OperationName, PwChangeTimeframe = (PwChangeTime - ConfirmTime)
| sort by ConfirmTime desc

// Title: Identify IP assets from MDEASM in Exposure Management that match TI
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/XSPM/identify-ip-assets-from-mdeasm-in-exposure-management-that-match-ti.md
// Section: Microsoft Defender XDR
// Author: cyb3rmik3
// Description:
// The following query will help identify which IPs from Microsoft Defender External Attack Surface Management in the Advanced Hunting tables from Exposure Management match Threat Intelligence indicators and the ThreatIntelIndicators table.

let TIIPs = 
    ThreatIntelligenceIndicator
    | extend TIIPAddress = tostring(NetworkIP)
    | where isnotempty(TIIPAddress)
    | project TIIPAddress, ThreatType, Description, ConfidenceScore;
let EASMIPs = 
    ExposureGraphNodes
    | where NodeLabel == "IP address"
    | project EASPIPAdress = tostring(NodeName);
TIIPs
| join kind=inner (
    EASMIPs
) on $left.TIIPAddress == $right.EASPIPAdress

// Title: Identify isolated endpoints
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/03.SecOps/identify-isolated-endpoints.md
// Section: Microsoft Defender XDR
// Author: cyb3rmik3
// Description:
// The following query will return endpoints which have been isolated by looking into relevant registry modifications.

DeviceRegistryEvents
| where ActionType == "RegistryValueSet"
| where RegistryKey == @"HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows Advanced Threat Protection"
| where RegistryValueType == "Dword"
| where RegistryValueName == "DisableEnterpriseAuthProxyValueToRestoreAfterIsolation"
| where RegistryValueData == "1"
| where PreviousRegistryValueName == "DisableEnterpriseAuthProxyValueToRestoreAfterIsolation"
| project Timestamp, DeviceId, DeviceName

// Title: Identify Microsoft Sentinel changes from users not defined within approved user groups
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/Sentinel/identify-microsoft-sentinel-changes-from-users-not-defined-within-approved-user-groups.md
// Section: Microsoft Sentinel & Defender XDR
// Author: cyb3rmik3
// Description:
// The following query takes into account ExposureGraphEdges, IdentityInfo and SentinelAudit and will allow you to identify if a user outside of the user groups defined to have access to Microsoft Sentinel, made any changes.

let EntraGroups = dynamic(["SentinelAdmins", "XDRAdmins"]); // Define your user groups of interest here
let Timeframe = ago(7d); // Define the required Timeframe
let UserInformation = 
ExposureGraphEdges
| where EdgeLabel == "member of"
| where SourceNodeLabel == "user"
| where not(TargetNodeName has_any (EntraGroups))
| extend EntraGroup = tostring(EntraGroups)
| project SourceNodeName, EntraGroup
| join kind=leftouter IdentityInfo on $left.SourceNodeName == $right.AccountDisplayName  
| summarize by SourceNodeName, EntraGroup, EmailAddress
| project SourceNodeName, EntraGroup, EmailAddress;
SentinelAudit
| where Status == @"Success"
| where TimeGenerated > Timeframe
| extend CallerEmailName = tostring(parse_json(ExtendedProperties)["CallerName"])
| project TimeGenerated, CallerEmailName, OperationName, SentinelResourceName, Description, SentinelResourceType
| join kind=inner UserInformation on $left.CallerEmailName == $right.EmailAddress
| sort by TimeGenerated desc

// Title: Identify MITRE ATT&CK Techniques
