// Title: WScript to VBS file invoking PowerShell
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/01.ThreatHunting/wscript-vbs-spawning-suspicious-processes.md
// Section: Microsoft 365 Defender
// Author: cyb3rmik3
// Description:
// This hunting query is based on a GULOADER payload delivered through a .vbs file which invoked PowerShell to gain foothold on the device.

DeviceProcessEvents
// Define the time you are interested to look into
| where Timestamp > ago(1d)
| where InitiatingProcessParentFileName contains @"wscript.exe"
// Command line includes VBS file execution
| where InitiatingProcessCommandLine contains ".vbs"
// Invoking PowerShell or Command Line
| where InitiatingProcessFileName has_any (@"powershell.exe", @"pwsh.exe", @"powershell_ise.exe", @"cmd.exe")
// Define elements that should be available in the results
| project Timestamp, DeviceName, AccountName, InitiatingProcessFileName, InitiatingProcessCommandLine, InitiatingProcessParentFileName

// Title: WScript to VBS file invoking PowerShell
// Source: https://github.com/cyb3rmik3/KQL-threat-hunting-queries/blob/main/01.ThreatHunting/wscript-vbs-spawning-suspicious-processes.md
// Section: Microsoft Sentinel
// Author: cyb3rmik3
// Description:
// This hunting query is based on a GULOADER payload delivered through a .vbs file which invoked PowerShell to gain foothold on the device.

DeviceProcessEvents
// Define the time you are interested to look into
| where TimeGenerated > ago(1d)
| where InitiatingProcessParentFileName contains @"wscript.exe"
// Command line includes VBS file execution
| where InitiatingProcessCommandLine contains ".vbs"
// Invoking PowerShell or Command Line
| where InitiatingProcessFileName has_any (@"powershell.exe", @"pwsh.exe", @"powershell_ise.exe", @"cmd.exe")
// Define elements that should be available in the results
| project Timestamp, DeviceName, AccountName, InitiatingProcessFileName, InitiatingProcessCommandLine, InitiatingProcessParentFileName

// Title: GitHubAppAddedToOrg.yaml
// Source: https://www.kqlsearch.com/query/GitHubAppAddedToOrg&cln4h9cc000135i0ol6nmcssc
// Section: KQL
// Author: Thomas Naunheim
// Description:
// 'GitHub Apps will be added to extend your workflos and integration in GitHub Enterprise. An attacker could use a malicious extension to conduct malicious activity. This query looks for new GitHub Apps that are not from a configurable list of approved apps.'

let allowed_apps = dynamic(["Dependabot"]);
GitHubAuditLogPolling_CL
| where action_s =~ "integration_installation.repositories_added"
| extend appName = tostring(name_s)
| where appName !in (allowed_apps)
| extend organization = tostring(org_s)
| project-reorder TimeGenerated, actor_s, org_s, organization
| extend date_time = unixtime_milliseconds_todatetime(_timestamp_d)
| project TimeGenerated = date_time, AccountCustomEntity = actor_s, organization = org_s, appName , action = action_s

// Title: Golden Chickens TerraStealerV2 Malware Detection.kql
// Source: https://www.kqlsearch.com/query/Golden%20Chickens%20TerraStealerV2%20Malware%20Detection&cmabeznve02h1p10f2jdv8h1g
// Section: KQL
// Author: Steven Lim
// Description:
// https://www.recordedfuture.com/research/terrastealerv2-and-terralogger
// 🤣 Golden Chickens 🤣
// TerraStealerV2 Malware Detection

let QueryPeriod = 1d;
let MonitorExtension = dynamic([".lnk", ".exe", ".dll", ".msi"]);
let EPwithLowFP =
DeviceFileEvents
| where Timestamp > ago(QueryPeriod)
| where ActionType == @"FileCreated"
| where FileName has_any (MonitorExtension)
| invoke FileProfile("SHA1", 500) 
| where GlobalPrevalence < 5
| distinct DeviceName;
DeviceNetworkEvents
| where Timestamp > ago(QueryPeriod)
| where ActionType == "ConnectionSuccess" and RemoteUrl == "wetransfers.io"
| where DeviceName has_any (EPwithLowFP)

// Title: gpresult.kql
