// Title: GuestAccountAdds.txt
// Source: https://www.kqlsearch.com/query/GuestAccountAdds&clmp0toh200kzmc0krfy0vb1h
// Section: KQL
// Author: Rod Trent
// Description:
// Users who added guest accounts to the tenants

CloudAppEvents
| where Timestamp > ago(7d)
| where ActionType == "Add user."
| where RawEventData.ResultStatus == "Success"
| where RawEventData has "guest" and RawEventData.ObjectId has "#EXT#"
| mv-expand Property = RawEventData.ModifiedProperties
| where Property.Name == "AccountEnabled" and Property.NewValue has "true"
| project Timestamp, AccountObjectId, AccountDisplayName, newGuestAccount = RawEventData.ObjectId, UserAgent

// Title: GWSAlerts SuspiciousProgrammaticLogin.yaml
// Source: https://www.kqlsearch.com/query/GWSAlerts_SuspiciousProgrammaticLogin&cmqtv6s24005qbljhll0qxiqc
// Section: KQL
// Author: David Alonso
// Description:
// Hunt for "Suspicious programmatic login" alerts. These typically indicate token
// theft, OAuth grant abuse, or service-account misuse - patterns documented in
// the GCP Pentest Checklist (OAuth/IAM persistence section). Pivot on user and
// source IP to find the abused identity / token.

GWSAlerts_CL
| where TimeGenerated > ago(14d)
| where AlertType has_any ("Suspicious programmatic login",
                           "Suspicious login from a less secure app")
| extend User = tostring(AlertData.email),
         ClientIp = tostring(AlertData.loginDetails.ipAddress),
         AppName = tostring(coalesce(AlertData.appName, AlertData.applicationName))
| summarize Alerts = count(),
            IPs = make_set(ClientIp, 50),
            Apps = make_set(AppName, 50),
            FirstSeen = min(TimeGenerated),
            LastSeen = max(TimeGenerated)
            by User, AlertType
| order by Alerts desc

// Title: Hanada Group Crowdstrike Impersonation Detection.kql
