// Title: HQ-002-NewApp-ImmediateCredentialAdd.kql
// Source: https://www.kqlsearch.com/query/HQ-002-NewApp-ImmediateCredentialAdd&cmqstqdbl002pjqzcrxuv3jsv
// Section: KQL
// Author: David Alonso
// Description:
// =========================================================================
// HQ-002: New Application Registration with Immediate Credential Addition
// =========================================================================
// Description : Joins app creation events with credential-add events within
// a 5-minute window. Legitimate DevOps pipelines register apps
// and add secrets, but so do ROADtools and MicroBurst when
// setting up OAuth infrastructure for token abuse or persistence.
// Review the actor and app display name for anomalies.
// MITRE ATT&CK: TA0003 Persistence
// T1098.001 – Additional Cloud Credentials
// Tools       : ROADtools, MicroBurst, AADInternals, CloudKatana
// Severity    : Medium-High
// Data Source : AuditLogs (Azure Active Directory)
// =========================================================================

let Lookback       = 1d;
let CredWindow     = 5m;

let AppCreations = AuditLogs
| where TimeGenerated > ago(Lookback)
| where ActivityDisplayName in (
    "Add application",
    "Create application \u2013 Certificates and secrets management ")
| extend AppObjectId   = tostring(TargetResources[0].id)
| extend AppName       = tostring(TargetResources[0].displayName)
| extend CreatorUPN    = tostring(InitiatedBy.user.userPrincipalName)
| extend CreatorApp    = tostring(InitiatedBy.app.displayName)
| extend CreatorActor  = iff(isnotempty(CreatorUPN), CreatorUPN, CreatorApp)
| project CreatedAt = TimeGenerated, AppObjectId, AppName, CreatorActor, CreatorUPN, CreatorApp, CorrelationId;

let CredAdds = AuditLogs
| where TimeGenerated > ago(Lookback)
| where ActivityDisplayName in (
    "Update application \u2013 Certificates and secrets management ",
    "Create application \u2013 Certificates and secrets management ",
    "Add service principal credentials",
    "Update service principal")
| mv-expand Prop = TargetResources[0].modifiedProperties
| where tostring(Prop.displayName) has_any ("KeyCredentials","PasswordCredentials","Credential","Secret","Certificate")
| extend AppObjectId    = tostring(TargetResources[0].id)
| extend AppName        = tostring(TargetResources[0].displayName)
| extend CredActorUPN   = tostring(InitiatedBy.user.userPrincipalName)
| extend CredActorApp   = tostring(InitiatedBy.app.displayName)
| extend CredActor      = iff(isnotempty(CredActorUPN), CredActorUPN, CredActorApp)
| extend CredType       = tostring(Prop.displayName)
| project CredAddedAt = TimeGenerated, AppObjectId, AppName, CredActor, CredActorUPN, CredType;

AppCreations
| join kind=inner CredAdds on AppObjectId
| where CredAddedAt > CreatedAt
| where CredAddedAt <= CreatedAt + CredWindow
| extend MinutesBetween = datetime_diff('minute', CredAddedAt, CreatedAt)
| project
    AppName,
    AppObjectId,
    CreatedAt,
    CredAddedAt,
    MinutesBetween,
    CreatorActor,
    CredActor,
    CredType
| order by CreatedAt desc

// Title: HQ-004-BulkServicePrincipalCreation.kql
// Source: https://www.kqlsearch.com/query/HQ-004-BulkServicePrincipalCreation&cmqstqk7i002rjqzc8jmp33ys
// Section: KQL
// Author: David Alonso
// Description:
// =========================================================================
// HQ-004: Burst Service Principal Creations in 1-Hour Window
// =========================================================================
// Description : Detects three or more service principals created by the
// same actor within a one-hour bucket. MicroBurst, ROADtools
// and CloudKatana register SPs in bulk when setting up attack
// infrastructure. Legitimate admins rarely create more than
// one or two SPs in rapid succession.
// MITRE ATT&CK: TA0003 Persistence
// T1136.003 – Create Cloud Account
// Tools       : ROADtools, MicroBurst, CloudKatana, AADInternals
// Severity    : Medium
// Data Source : AuditLogs (Azure Active Directory)
// =========================================================================

AuditLogs
| where TimeGenerated > ago(1d)
| where ActivityDisplayName == "Add service principal"
| extend InitiatedByUPN = tostring(InitiatedBy.user.userPrincipalName)
| extend InitiatedByApp = tostring(InitiatedBy.app.displayName)
| extend Actor          = iff(isnotempty(InitiatedByUPN), InitiatedByUPN, InitiatedByApp)
| extend NewSPName      = tostring(TargetResources[0].displayName)
| extend NewSPId        = tostring(TargetResources[0].id)
| summarize
    SPCreatedCount = count(),
    SPNames        = make_set(NewSPName, 20),
    SPIds          = make_set(NewSPId, 20),
    FirstCreation  = min(TimeGenerated),
    LastCreation   = max(TimeGenerated)
    by Actor, bin(TimeGenerated, 1h)
| where SPCreatedCount >= 3
| extend DurationMinutes = datetime_diff('minute', LastCreation, FirstCreation)
| extend RatePerMinute   = round(toreal(SPCreatedCount) / iff(DurationMinutes == 0, 1.0, toreal(DurationMinutes)), 2)
| order by SPCreatedCount desc

// Title: HQ-006-GuestUser-PrivilegeEscalation.kql
// Source: https://www.kqlsearch.com/query/HQ-006-GuestUser-PrivilegeEscalation&cmqstqt1u002tjqzcsi8hu9gp
// Section: KQL
// Author: David Alonso
// Description:
// =========================================================================
// HQ-006: External / Guest User Receiving Group or Role Membership
// =========================================================================
// Description : Entra ID guests (UPN contains #EXT#) should rarely receive
// sensitive group or role memberships. Post-compromise actors
// and insider threats escalate privileges by adding external
// accounts to high-privilege groups. This query hunts for
// such assignments to facilitate triage.
// MITRE ATT&CK: TA0004 Privilege Escalation
// T1078.004 – Valid Accounts: Cloud Accounts
// Tools       : Manual attacker action, AADInternals, MicroBurst
// Severity    : High
// Data Source : AuditLogs (Azure Active Directory)
// =========================================================================

AuditLogs
| where TimeGenerated > ago(7d)
| where ActivityDisplayName in (
    "Add member to group",
    "Add member to role",
    "Add eligible member to role",
    "Add app role assignment grant to user")
| extend TargetUserDisplayName = tostring(TargetResources[0].displayName)
| extend TargetUserUPN         = tostring(TargetResources[0].userPrincipalName)
| extend TargetUserId          = tostring(TargetResources[0].id)
| extend GroupOrRole           = tostring(TargetResources[1].displayName)
| extend InitiatedByUPN        = tostring(InitiatedBy.user.userPrincipalName)
| extend InitiatedByApp        = tostring(InitiatedBy.app.displayName)
| extend Actor                 = iff(isnotempty(InitiatedByUPN), InitiatedByUPN, InitiatedByApp)
// Guest accounts use the #EXT# convention in their UPN
| where TargetUserUPN has "#EXT#"
    or TargetUserDisplayName has "(Guest)"
| where Result == "success"
| project
    TimeGenerated,
    Actor,
    TargetUserDisplayName,
    TargetUserUPN,
    GroupOrRole,
    ActivityDisplayName,
    LoggedByService,
    CorrelationId
| order by TimeGenerated desc

// Title: HUNT-02 AD-ASREP-Roastable-Accounts-Audit-90d.kql
// Source: https://www.kqlsearch.com/query/HUNT-02_AD-ASREP-Roastable-Accounts-Audit-90d&cmqstjfco001vjqzce38u42gg
// Section: KQL
// Author: David Alonso
// Description:
// =========================================================
// HUNT-02 | AD-ASREP-Roastable-Accounts-Audit-90d
// Description : Full audit of all accounts with
// DONT_REQ_PREAUTH (AS-REP Roastable) and
// historical AS-REP request patterns. Surfaces
// accounts that have never required pre-auth,
// and correlates with actual roasting attempts.
// Period      : 90 days
// Use Case    : Attack surface exposure assessment,
// DONT_REQ_PREAUTH hygiene review
// Tables      : SecurityEvent
// =========================================================

let Period = 90d;

// All 4768 events with tostring(column_ifexists("PreAuthType", "")) = 0 (no pre-auth required)
let ASREPRequests = SecurityEvent
    | where TimeGenerated > ago(Period)
    | where EventID == 4768
    | where tostring(column_ifexists("PreAuthType", "")) == "0"
    | where TargetUserName !endswith "$"
    | extend
        IsOffHours = hourofday(TimeGenerated) < 8 or hourofday(TimeGenerated) >= 19
    | summarize
        TotalASREP          = count(),
        UniqueRequesters    = dcount(IpAddress),
        RequestingIPs       = make_set(IpAddress, 20),
        OffHoursRequests    = countif(IsOffHours),
        FirstSeen           = min(TimeGenerated),
        LastSeen            = max(TimeGenerated),
        RecentRequests      = countif(TimeGenerated > ago(7d))
        by RoastableAccount = TargetUserName,
           AccountDomain    = TargetDomainName;

// Normal 4768 events (with pre-auth, for baseline comparison)
let NormalTGTs = SecurityEvent
    | where TimeGenerated > ago(Period)
    | where EventID == 4768
    | where tostring(column_ifexists("PreAuthType", "")) != "0"
    | where TargetUserName !endswith "$"
    | summarize NormalTGTCount = count()
        by TargetUserName, TargetDomainName;

ASREPRequests
| join kind=leftouter (NormalTGTs) on
    $left.RoastableAccount == $right.TargetUserName,
    $left.AccountDomain    == $right.TargetDomainName
| extend
    OffHoursRatio    = round(todouble(OffHoursRequests) / todouble(TotalASREP), 2),
    // If this account ONLY appears with tostring(column_ifexists("PreAuthType", ""))=0 it's permanently set DONT_REQ_PREAUTH
    OnlySeenASREP    = isnull(NormalTGTCount) or NormalTGTCount == 0,
    RiskScore        = (TotalASREP * 3)
                     + (UniqueRequesters * 5)
                     + iff(OffHoursRequests > 0, 10, 0)
                     + iff(RecentRequests > 0, 20, 0)
| extend
    RiskLevel = case(
        RiskScore >= 60,  "Critical",
        RiskScore >= 25,  "High",
        "Medium"
    ),
    Recommendation = case(
        OnlySeenASREP,  "Set PreAuthentication required, rotate password immediately",
        TotalASREP > 5, "Review why account lacks pre-authentication requirement",
        "Monitor for further requests"
    )
| project
    RoastableAccount,
    AccountDomain,
    RiskLevel,
    RiskScore,
    TotalASREP,
    UniqueRequesters,
    OffHoursRatio,
    OnlySeenASREP,
    RecentRequests,
    FirstSeen,
    LastSeen,
    Recommendation,
    RequestingIPs
| order by RiskScore desc

// Title: HUNT-05 MI-OutOfHours-Timeline-90d.kql
// Source: https://www.kqlsearch.com/query/HUNT-05_MI-OutOfHours-Timeline-90d&cmqsuhiz9006ijqzcnmetfkjk
// Section: KQL
// Author: David Alonso
// Description:
// Hunt     : Workload Identity - Managed Identity Out-of-Hours Full Timeline (90d)
// Tactics  : Persistence, LateralMovement
// MITRE    : T1078.004, T1550
// Purpose  : Full 90-day history of Managed Identities authenticating outside business hours
// (Mon–Fri 06:00–22:00). Baseline normal patterns, identify persistent anomalies,
// and surface MIs accessing sensitive resources at unexpected times.
// ==========================================================================================

let SensitiveResources = dynamic([
    "Key Vault", "Storage", "SQL", "Cognitive", "OpenAI",
    "Synapse", "Service Bus", "Event Hub", "Container Registry"
]);
// isfuzzy=true: AADManagedIdentitySignInLogs only exists when the Managed Identity diagnostic connector is enabled
union isfuzzy=true
    (AADManagedIdentitySignInLogs | invoke ExcludeAllowlistedIPs()),
    (datatable(TimeGenerated:datetime, ResultType:string, ServicePrincipalName:string,
               ServicePrincipalId:string, ResourceDisplayName:string, SourceAppClientId:string)[])
| where TimeGenerated > ago(90d)
| where ResultType == "0"
| extend Hour        = hourofday(TimeGenerated)
| extend DayOfWeek   = dayofweek(TimeGenerated)
| extend IsWeekend   = DayOfWeek in (0d, 6d)
| extend IsOOH       = Hour < 6 or Hour > 22 or IsWeekend
| extend IsSensitive = ResourceDisplayName has_any (SensitiveResources)
| summarize
    TotalAuths        = count(),
    OOHAuths          = countif(IsOOH),
    BizHoursAuths     = countif(not(IsOOH)),
    SensitiveOOH      = countif(IsOOH and IsSensitive),
    UniqueResources   = dcount(ResourceDisplayName),
    OOHResources      = make_set_if(ResourceDisplayName, IsOOH, 15),
    SensitiveResources_List = make_set_if(ResourceDisplayName, IsOOH and IsSensitive, 10),
    UniqueSourceApps  = dcount(SourceAppClientId),
    SourceApps        = make_set(SourceAppClientId, 10),
    OOHDays           = dcountif(bin(TimeGenerated, 1d), IsOOH),
    FirstOOH          = minif(TimeGenerated, IsOOH),
    LastOOH           = maxif(TimeGenerated, IsOOH)
    by ServicePrincipalName, ServicePrincipalId
| where OOHAuths > 0
| extend OOHRatio = round(todouble(OOHAuths) / todouble(TotalAuths) * 100, 1)
| order by SensitiveOOH desc, OOHAuths desc

// Title: HUNT-07 ADFS-NewCountry-PerUser-30v90d.yaml
// Source: https://www.kqlsearch.com/query/HUNT-07_ADFS-NewCountry-PerUser-30v90d&cmqtub8730010bljhjpfcm9li
// Section: KQL
// Author: David Alonso
// Description:
// Detects users whose 30-day country footprint includes a country never seen
// in the prior 60 days of ADFS sign-ins. Complements RULE-08 by surfacing
// every first-seen country shift, not only ones with anomaly scoring.

let now      = ADFSSignInLogs
  | invoke ExcludeAllowlistedIPs()
  | where TimeGenerated between (ago(30d) .. now())
  | where ResultType == 0
  | summarize NowCountries = make_set(Location, 25) by UserPrincipalName;
let baseline = ADFSSignInLogs
  | invoke ExcludeAllowlistedIPs()
  | where TimeGenerated between (ago(90d) .. ago(30d))
  | where ResultType == 0
  | summarize BaselineCountries = make_set(Location, 25) by UserPrincipalName;
now
| join kind=leftouter (baseline) on UserPrincipalName
| extend NewCountries = set_difference(NowCountries, coalesce(BaselineCountries, dynamic([])))
| where array_length(NewCountries) > 0
| project UserPrincipalName, NewCountries, NowCountries, BaselineCountries
| order by array_length(NewCountries) desc

// Title: HUNT-10 AADProv-RareOperations-30d.yaml
// Source: https://www.kqlsearch.com/query/HUNT-10_AADProv-RareOperations-30d&cmqtv2v8q0052bljhhb4yneas
// Section: KQL
// Author: David Alonso
// Description:
// Surfaces rare values across `ProvisioningAction`, `TargetSystem`,
// `ResultSignature`, and `OperationName` over 30 days - useful for ad-hoc
// discovery of unusual telemetry patterns that no static rule would catch.
// Stack-counting style: anything with a tiny share is shown for triage.

let TotalEvents = toscalar(
    AADProvisioningLogs
    | where TimeGenerated > ago(30d)
    | count
);
AADProvisioningLogs
| where TimeGenerated > ago(30d)
| extend TgtSystem = tostring(parse_json(TargetSystem).DisplayName),
         SPName    = tostring(parse_json(ServicePrincipal).Name)
| summarize Events = count() by ProvisioningAction, TgtSystem, ResultSignature, OperationName, SPName
| extend Share = round(100.0 * Events / TotalEvents, 4)
| where Share <= 0.05  // <= 0.05% of telemetry
| order by Events asc

// Title: HUNT-10 SP-NotUsed-90d-Stale.kql
// Source: https://www.kqlsearch.com/query/HUNT-10_SP-NotUsed-90d-Stale&cmqsui7eq006njqzcic42g48n
// Section: KQL
// Author: David Alonso
// Description:
// Hunt     : Workload Identity - Service Principals Not Used in 90 Days (Stale/Abandoned SPs)
// Tactics  : Persistence
// MITRE    : T1098.001 (Account Manipulation: Additional Cloud Credentials), T1078.004
// Purpose  : A stale SP with active credentials is a standing attack surface — attackers
// target them because they have no active owners, rarely rotate credentials,
// and generate no alerts when used after a long gap. This query surfaces SPs
// whose last successful sign-in was more than 90 days ago but are still present
// in the directory. Correlates with AuditLogs to show if credentials were
// added recently (reactivation attempt), and AzureActivity to check for any
// recent management plane calls that may not appear in sign-in logs.
// ==========================================================================================
// --- SPs that have signed in at any point (to know their last activity) ---

let AllSPActivity = (AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs())
    | where TimeGenerated > ago(180d)
    | where ResultType == "0"
    | summarize
        TotalSignins     = count(),
        LastSignin       = max(TimeGenerated),
        UniqueResources  = dcount(ResourceDisplayName),
        LastResources    = make_set(ResourceDisplayName, 5)
        by ServicePrincipalId, ServicePrincipalName, AppId;

// --- Inactive SPs: last sign-in was >90 days ago ---
let InactiveSPs = AllSPActivity
    | where LastSignin < ago(90d);

// --- Check for recent credential additions to inactive SPs (reactivation signal) ---
let RecentCredChanges = AuditLogs
    | where TimeGenerated > ago(90d)
    | where OperationName has_any (
        "Add service principal credentials",
        "Update application – Certificates and secrets management",
        "Update service principal")
    | where Result =~ "success"
    | extend SPId      = tostring(TargetResources[0].id)
    | extend Initiator = coalesce(
        tostring(InitiatedBy.user.userPrincipalName),
        tostring(InitiatedBy.app.displayName))
    | summarize
        RecentChanges    = count(),
        ChangeTypes      = make_set(OperationName, 5),
        Initiators       = make_set(Initiator, 5),
        LastChange       = max(TimeGenerated)
        by SPId;

// --- Check for recent AzureActivity calls from inactive SPs (headless management access) ---
// isfuzzy=true: AzureActivity may not be connected in all environments
let RecentMgmtActivity = union isfuzzy=true
    AzureActivity,
    (datatable(TimeGenerated:datetime, ActivityStatusValue:string, OperationNameValue:string, Caller:string)[])
    | where TimeGenerated > ago(90d)
    | where ActivityStatusValue =~ "Success"
    | summarize
        MgmtOps          = count(),
        LastMgmtOp       = max(TimeGenerated),
        Operations        = make_set(OperationNameValue, 5)
        by Caller;

InactiveSPs
| join kind=leftouter RecentCredChanges on $left.ServicePrincipalId == $right.SPId
| join kind=leftouter RecentMgmtActivity on $left.ServicePrincipalId == $right.Caller
| extend DaysInactive         = datetime_diff("day", now(), LastSignin)
| extend HasRecentCredChange  = RecentChanges > 0
| extend HasMgmtActivity      = MgmtOps > 0
| extend RiskAssessment = case(
    HasRecentCredChange == true and HasMgmtActivity == true,
        "Critical — Stale SP Reactivated with New Creds + Mgmt Activity",
    HasRecentCredChange == true,
        "High — Stale SP Had Credential Change (Possible Reactivation)",
    HasMgmtActivity == true,
        "High — Stale SP Has Recent Management Plane Activity",
    DaysInactive > 180,
        "Medium — Very Long Dormancy (>180 days), Cleanup Recommended",
        "Low — Stale SP, No Recent Activity or Changes")
| project
    ServicePrincipalName, ServicePrincipalId, AppId,
    LastSignin, DaysInactive, TotalSignins,
    UniqueResources, LastResources,
    HasRecentCredChange, RecentChanges, ChangeTypes, Initiators, LastChange,
    HasMgmtActivity, MgmtOps, LastMgmtOp, Operations,
    RiskAssessment
| order by RiskAssessment asc, DaysInactive desc

// Title: HUNT-14 AADProv-SelfProvisioningLoop-30d.yaml
// Source: https://www.kqlsearch.com/query/HUNT-14_AADProv-SelfProvisioningLoop-30d&cmqtv3l080056bljhyqsb0aj3
// Section: KQL
// Author: David Alonso
// Description:
// Surfaces provisioning events where the initiating identity and the target
// identity are the same principal - an actor provisioning, enabling,
// re-enabling, or rewriting attributes on their own object through the
// provisioning channel. Self-modification through provisioning is a stealthy
// privilege-persistence path: the change rarely raises a console alert and
// bypasses the usual two-person separation that direct admin portal edits
// attract. Benign in some HR-driven self-service scenarios, so treat as a
// hunt rather than an alert and triage on the PropName / AssignedRoles
// custom output.
// MITRE ATT&CK: T1098 (Account Manipulation),
// T1078.004 (Valid Accounts: Cloud Accounts).

let PrivilegedUsers =
    IdentityInfo
    | where TimeGenerated > ago(14d)
    | summarize arg_max(TimeGenerated, *) by AccountUPN
    | where isnotempty(AssignedRoles) and AssignedRoles != "[]"
    | project AccountUPN, AssignedRoles;
AADProvisioningLogs
| where TimeGenerated > ago(30d)
| where ResultType =~ "Success"
| extend InitiatorUpn = tolower(tostring(parse_json(InitiatedBy).userPrincipalName)),
         TargetUpn    = tolower(tostring(parse_json(TargetIdentity).userPrincipalName)),
         SPName       = tostring(parse_json(ServicePrincipal).Name)
| where isnotempty(InitiatorUpn) and InitiatorUpn == TargetUpn
| mv-expand Mod = todynamic(ModifiedProperties)
| extend PropName = tostring(Mod.displayName),
         OldValue = tostring(Mod.oldValue),
         NewValue = tostring(Mod.newValue)
| summarize
    EventCount    = count(),
    Actions       = make_set(ProvisioningAction, 10),
    ChangedProps  = make_set(PropName, 25),
    Jobs          = make_set(JobId, 10),
    FirstSeen     = min(TimeGenerated),
    LastSeen      = max(TimeGenerated)
  by InitiatorUpn, SPName
| join kind=leftouter (PrivilegedUsers) on $left.InitiatorUpn == $right.AccountUPN
| extend IsPrivileged = isnotempty(AssignedRoles)
| project InitiatorUpn, IsPrivileged, AssignedRoles, SPName, EventCount,
          Actions, ChangedProps, Jobs, FirstSeen, LastSeen
| order by IsPrivileged desc, EventCount desc

// Title: HUNT-16 FirstSeen-ResourceProvider-Per-Identity.kql
// Source: https://www.kqlsearch.com/query/HUNT-16_FirstSeen-ResourceProvider-Per-Identity&cms3l14g00003qu8ktk13zy6g
// Section: KQL
// Author: David Alonso
// Description:
// Hunt     : Hunt - First-Seen Azure Resource Provider per Identity (30d)
// Tactics  : Discovery, Persistence
// MITRE    : T1078, T1580
// Purpose  : Flags identities invoking an Azure Resource Provider (e.g. Microsoft.Compute,
// Microsoft.KeyVault) for the FIRST time in 30 days. A compromised identity that
// suddenly touches a provider it has never used is a strong lateral-movement /
// discovery signal. Pairs with RULE-09 (new IP) and RULE-12 (mass creation).
// ==========================================================================================

let Window = 30d;
let Recent = 1d;
let Baseline = AzureActivity
    | where TimeGenerated between (ago(Window) .. ago(Recent))
    | where isnotempty(Caller) and isnotempty(OperationNameValue)
    | extend ResourceProvider = tostring(split(OperationNameValue, '/')[0])
    | summarize PriorProviders = make_set(ResourceProvider, 1000) by Caller;
AzureActivity
| where TimeGenerated > ago(Recent)
| where isnotempty(Caller) and isnotempty(OperationNameValue)
| extend ResourceProvider = tostring(split(OperationNameValue, '/')[0])
| join kind=leftouter Baseline on Caller
| where isempty(PriorProviders) or not(set_has_element(PriorProviders, ResourceProvider))
| summarize FirstSeen = min(TimeGenerated), Ops = count(),
    Providers = make_set(ResourceProvider, 10), IPs = make_set(CallerIpAddress, 10)
    by Caller
| order by FirstSeen desc

// Title: HUNT-17 KeyVault-Bulk-Read.kql
// Source: https://www.kqlsearch.com/query/HUNT-17_KeyVault-Bulk-Read&cms3l18oh0004qu8k97ynofwa
// Section: KQL
// Author: David Alonso
// Description:
// Hunt     : Hunt - KeyVault Secret or Key Bulk Read (potential dump)
// Tactics  : CredentialAccess, Collection
// MITRE    : T1552.001, T1555
// Purpose  : Surfaces identities reading/listing 25+ Key Vault secrets, keys, or certificates
// within a single hour — the signature of a credential-dump sweep after a vault is
// compromised. Tune the ReadThreshold to your busiest legitimate consumer.
// ==========================================================================================

let Window = 7d;
let ReadThreshold = 25;
AzureActivity
| where TimeGenerated > ago(Window)
| where OperationNameValue has_any (
    "VAULTS/SECRETS/READ", "VAULTS/KEYS/READ", "VAULTS/CERTIFICATES/READ",
    "VAULTS/SECRETS/GETSECRET/ACTION", "VAULTS/SECRETS/LIST")
| where ActivityStatusValue =~ "Success"
| summarize
    ReadCount = count(),
    DistinctObjects = dcount(_ResourceId),
    Vaults = make_set(tostring(split(_ResourceId, "/")[8]), 20),
    Operations = make_set(OperationNameValue, 5)
    by Caller, CallerIpAddress, bin(TimeGenerated, 1h)
| where ReadCount >= ReadThreshold
| order by ReadCount desc

// Title: HUNT-18 SP-Signin-New-Country.kql
// Source: https://www.kqlsearch.com/query/HUNT-18_SP-Signin-New-Country&cms3l1cxc0005qu8k6kwlewex
// Section: KQL
// Author: David Alonso
// Description:
// Hunt     : Hunt - Service Principal Sign-in from New Country (30d baseline)
// Tactics  : InitialAccess
// MITRE    : T1078.004
// Purpose  : Per-SP geo baseline. Flags a successful workload-identity sign-in from a country
// the SP has never authenticated from in the prior 30 days. Workload identities are
// typically pinned to a small set of regions; a new country implies token theft or
// credential abuse. Pairs with RULE-10 (SP CA bypass) and RULE-19 (anonymizer).
// ==========================================================================================

let Window = 30d;
let Recent = 1d;
let Baseline = AADServicePrincipalSignInLogs
    | where TimeGenerated between (ago(Window) .. ago(Recent))
    | where ResultType == 0
    | summarize KnownCountries = make_set(tostring(LocationDetails.countryOrRegion), 50) by ServicePrincipalId;
AADServicePrincipalSignInLogs
| where TimeGenerated > ago(Recent)
| where ResultType == 0
| extend Country = tostring(LocationDetails.countryOrRegion)
| where isnotempty(Country)
| join kind=leftouter Baseline on ServicePrincipalId
| where isempty(KnownCountries) or not(set_has_element(KnownCountries, Country))
| project TimeGenerated, ServicePrincipalName, ServicePrincipalId, Country, IPAddress, AppId, ResultType
| order by TimeGenerated desc

// Title: HUNT-19 Consent-Grant-Burst.kql
// Source: https://www.kqlsearch.com/query/HUNT-19_Consent-Grant-Burst&cms3l1i190006qu8kl4n45g3k
// Section: KQL
// Author: David Alonso
// Description:
// Hunt     : Hunt - AAD App Consent Grant Burst (potential illicit consent attack)
// Tactics  : Persistence, InitialAccess
// MITRE    : T1528
// Purpose  : Broad companion to RULE-18. Surfaces any initiator granting 5+ OAuth consents /
// permission grants within a single hour (any scope, not just high-impact). Use to
// baseline consent behaviour and to catch phishing waves where a single user is
// tricked into consenting to a cluster of malicious apps.
// ==========================================================================================

let Window = 7d;
let GrantThreshold = 5;
AuditLogs
| where TimeGenerated > ago(Window)
| where OperationName has_any ("Consent to application", "Add delegated permission grant",
    "Add app role assignment grant to user")
| where Result =~ "success"
| extend Initiator = coalesce(tostring(InitiatedBy.user.userPrincipalName), tostring(InitiatedBy.app.displayName))
| extend AppName = tostring(TargetResources[0].displayName)
| where isnotempty(Initiator)
| summarize Grants = count(), Apps = make_set(AppName, 25), Operations = make_set(OperationName, 5)
    by Initiator, bin(TimeGenerated, 1h)
| where Grants >= GrantThreshold
| order by Grants desc

// Title: HUNT-20 Signin-Anomalous-ASN.kql
// Source: https://www.kqlsearch.com/query/HUNT-20_Signin-Anomalous-ASN&cms3l1mea0007qu8kh5g6qvay
// Section: KQL
// Author: David Alonso
// Description:
// Hunt     : Hunt - Sign-in from Anomalous Network Location (ASN) per Identity (30d)
// Tactics  : InitialAccess
// MITRE    : T1078.004
// Purpose  : Per-user ASN baseline. Flags a successful interactive sign-in from an autonomous
// system (network operator) the user has never authenticated from in the prior 30
// days. Complements geo/impossible-travel by catching hosting/VPS ASNs that share a
// country with the user's normal ISP.
// ==========================================================================================

let Window = 30d;
let Recent = 1d;
let Baseline = SigninLogs
    | where TimeGenerated between (ago(Window) .. ago(Recent))
    | where ResultType == 0
    | extend ASN = tostring(AutonomousSystemNumber)
    | where isnotempty(ASN)
    | summarize KnownASNs = make_set(ASN, 200) by UserPrincipalName;
SigninLogs
| where TimeGenerated > ago(Recent)
| where ResultType == 0
| extend ASN = tostring(AutonomousSystemNumber)
| where isnotempty(ASN)
| join kind=leftouter Baseline on UserPrincipalName
| where isempty(KnownASNs) or not(set_has_element(KnownASNs, ASN))
| project TimeGenerated, UserPrincipalName, ASN, IPAddress, AppDisplayName,
    Location, ConditionalAccessStatus, RiskLevelAggregated
| order by TimeGenerated desc

// Title: HUNT-21 Caller-IP-Concentration.kql
// Source: https://www.kqlsearch.com/query/HUNT-21_Caller-IP-Concentration&cms3l1qaq0008qu8k0tfmupnx
// Section: KQL
// Author: David Alonso
// Description:
// Hunt     : Hunt - Caller IP Concentration Across Many Identities (7d)
// Tactics  : LateralMovement, CredentialAccess
// MITRE    : T1550
// Purpose  : Surfaces a single source IP driving management-plane operations for 5+ distinct
// identities in 7 days. Beyond shared corporate egress (allowlist those), this is a
// classic token-theft / credential-replay signature where one attacker host wields
// many stolen identities. Add trusted egress IPs to the NetworkAllowlist watchlist.
// ==========================================================================================

let Window = 7d;
let IdentityThreshold = 5;
AzureActivity
| where TimeGenerated > ago(Window)
| where isnotempty(CallerIpAddress) and isnotempty(Caller)
| where CallerIpAddress !startswith "168.63." and CallerIpAddress !startswith "169.254."
| summarize
    Identities = dcount(Caller),
    Callers = make_set(Caller, 25),
    Ops = count(),
    Operations = make_set(OperationNameValue, 10)
    by CallerIpAddress
| where Identities >= IdentityThreshold
| order by Identities desc, Ops desc

// Title: HUNT-22 Federation-Domain-Trust-Changes.kql
// Source: https://www.kqlsearch.com/query/HUNT-22_Federation-Domain-Trust-Changes&cms3l1uw70009qu8k8ymmhhhp
// Section: KQL
// Author: David Alonso
// Description:
// Hunt     : Hunt - Federation & Domain Trust Changes (Golden SAML / Persistence) (30d)
// Tactics  : Persistence, PrivilegeEscalation, DefenseEvasion
// MITRE    : T1484.002 (Domain Trust Modification), T1556
// Purpose  : Detects changes to Entra ID federation / domain authentication settings. Adding
// or modifying a federated domain (or issuer/token-signing config) lets an attacker
// forge SAML tokens for ANY user ("Golden SAML" — Midnight Blizzard / NOBELIUM).
// These events are rare and almost always high-signal. Review EVERY hit against a
// known change ticket. No threshold — this is a review-all timeline.
// ==========================================================================================

let FederationOps = dynamic([
    "Set federation settings on domain",
    "Set domain authentication",
    "Update domain",
    "Add unverified domain",
    "Add verified domain",
    "Verify domain",
    "Verify email verified domain",
    "Add partner to cross-tenant access setting",
    "Update a partner cross-tenant access setting",
    "Update federation settings"
]);
AuditLogs
| where TimeGenerated > ago(30d)
| where LoggedByService in~ ("Core Directory", "AAD Cloud Sync", "Authentication Methods")
| where OperationName in~ (FederationOps)
| where Result =~ "success"
| extend Initiator = coalesce(tostring(InitiatedBy.user.userPrincipalName), tostring(InitiatedBy.app.displayName))
| extend InitiatorIP = tostring(InitiatedBy.user.ipAddress)
| extend TargetDomain = tostring(TargetResources[0].displayName)
| extend ModifiedProps = tostring(TargetResources[0].modifiedProperties)
| project TimeGenerated, OperationName, Initiator, InitiatorIP, TargetDomain, ModifiedProps, Result, CorrelationId
| order by TimeGenerated desc

// Title: HUNT-23 MFA-Auth-Method-Changes.kql
// Source: https://www.kqlsearch.com/query/HUNT-23_MFA-Auth-Method-Changes&cms3l26kq000aqu8kqjcgi0sm
// Section: KQL
// Author: David Alonso
// Description:
// Hunt     : Hunt - MFA / Authentication Method Registration Changes (30d)
// Tactics  : Persistence, CredentialAccess
// MITRE    : T1098.005 (Device Registration), T1556.006 (MFA)
// Purpose  : Surfaces registration/removal of authentication methods (phone, authenticator,
// FIDO2, TAP, email). Attackers who phish a session frequently register their OWN
// MFA method to establish durable access, or remove the victim's methods. Focus on
// events where the initiator differs from the target (admin-on-behalf-of), or a
// burst of self-service changes shortly after a risky sign-in.
// ==========================================================================================

let Window = 30d;
let MethodOps = dynamic([
    "User registered security info",
    "User changed default security info",
    "User deleted security info",
    "Admin registered security info",
    "Admin updated security info",
    "Admin deleted security info",
    "User registered all required security info",
    "Register security information",
    "Reset security information"
]);
AuditLogs
| where TimeGenerated > ago(Window)
| where LoggedByService in~ ("Authentication Methods", "Self-service Password Management", "Core Directory")
| where OperationName has_any (MethodOps)
| extend Initiator = coalesce(tostring(InitiatedBy.user.userPrincipalName), tostring(InitiatedBy.app.displayName))
| extend InitiatorId = tostring(InitiatedBy.user.id)
| extend InitiatorIP = tostring(InitiatedBy.user.ipAddress)
| extend TargetUPN = tostring(TargetResources[0].userPrincipalName)
| extend TargetId = tostring(TargetResources[0].id)
| extend MethodDetail = tostring(TargetResources[0].modifiedProperties)
| extend ActorIsNotTarget = isnotempty(InitiatorId) and isnotempty(TargetId) and InitiatorId != TargetId
| project TimeGenerated, OperationName, Result, Initiator, InitiatorIP, TargetUPN,
    ActorIsNotTarget, MethodDetail, CorrelationId
| order by ActorIsNotTarget desc, TimeGenerated desc

// Title: HUNT-24 Guest-Invite-Privileged-Role.kql
// Source: https://www.kqlsearch.com/query/HUNT-24_Guest-Invite-Privileged-Role&cms3l2b4y000bqu8kxmkqe2uo
// Section: KQL
// Author: David Alonso
// Description:
// Hunt     : Hunt - Guest (B2B) Invitation Followed by Privileged Role (30d)
// Tactics  : Persistence, PrivilegeEscalation
// MITRE    : T1078.004, T1098.003
// Purpose  : Correlates external guest (B2B) invitations/redemptions with a subsequent
// privileged role assignment to that same guest within 7 days. Attackers who gain
// admin rights invite an attacker-controlled external identity and grant it standing
// access that survives the victim's password resets. Investigate every hit.
// ==========================================================================================

let Window = 30d;
let CorrelationWindow = 7d;
let GuestInvites = AuditLogs
    | where TimeGenerated > ago(Window)
    | where OperationName has_any ("Invite external user", "Redeem external user invite", "Add external user")
    | where Result =~ "success"
    | extend GuestUPN = tostring(TargetResources[0].userPrincipalName)
    | extend GuestId = tostring(TargetResources[0].id)
    | extend Inviter = coalesce(tostring(InitiatedBy.user.userPrincipalName), tostring(InitiatedBy.app.displayName))
    | where isnotempty(GuestId)
    | project InviteTime = TimeGenerated, GuestUPN, GuestId, Inviter;
let PrivRoleGrants = AuditLogs
    | where TimeGenerated > ago(Window)
    | where OperationName has_any ("Add member to role", "Add eligible member to role",
        "Add app role assignment to service principal")
    | where Result =~ "success"
    | extend RoleName = tostring(TargetResources[0].displayName)
    | mv-expand TR = TargetResources
    | extend GranteeId = tostring(TR.id), GranteeUPN = tostring(TR.userPrincipalName)
    | where isnotempty(GranteeId)
    | project RoleTime = TimeGenerated, RoleName, GranteeId, GranteeUPN,
        Grantor = coalesce(tostring(InitiatedBy.user.userPrincipalName), tostring(InitiatedBy.app.displayName));
GuestInvites
| join kind=inner PrivRoleGrants on $left.GuestId == $right.GranteeId
| where RoleTime between (InviteTime .. (InviteTime + CorrelationWindow))
| project InviteTime, RoleTime, GuestUPN, Inviter, RoleName, Grantor, GuestId
| order by RoleTime desc

// Title: HUNT-25 M365-Copilot-SensitiveContent-BulkAccess-30d.kql
// Source: https://www.kqlsearch.com/query/HUNT-25_M365-Copilot-SensitiveContent-BulkAccess-30d&cmqsu7lh4005ljqzc60vipw2j
// Section: KQL
// Author: David Alonso
// Description:
// Hunt    : M365 Copilot - Bulk or Sensitive Data Access via Copilot Interactions (30d)
// Purpose : Every CopilotInteraction event carries a "Contexts" array in AuditData that
// lists the files, emails, calendar items, and web pages that Copilot read to
// compose its response. This hunt expands those arrays and profiles each user
// on two risk axes:
//
// Bulk access — interactions where Copilot ingested an unusually high number
// of documents in a single prompt (≥5 contexts = bulk threshold). This can
// indicate a user harvesting document contents at scale via Copilot rather
// than downloading individual files — a pattern that bypasses DLP file-
// transfer controls entirely.
//
// Sensitive-label access — any resource whose SensitivityLabel field maps to
// Confidential, Highly Confidential, Secret, Restricted, or equivalent.
// Copilot happily surfaces labelled content to any user who has access;
// volume and breadth of sensitive-label usage is a key indicator of
// misuse or insider data staging.
//
// Results are grouped by user and include: total interactions, total resources
// accessed, sensitive-resource count, the specific labels encountered, sample
// resource IDs/URLs for the sensitive hits, apps used, and a WhySuspicious
// plain-English summary. Pair with HUNT-24 (volume/timing) and HUNT-26
// (XPIA/jailbreak) for a full Copilot threat picture.
// Tables  : OfficeActivity
// Period  : P30D
// Tactics : Collection, Exfiltration, Discovery
// MITRE   : T1119 (Automated Collection), T1530 (Cloud Storage Object Access),
// T1213.003 (Information Repositories), T1074.001 (Local Data Staging)
// Scope   : All users; Contexts array mv-expand produces one row per resource accessed
// ==========================================================================================

let LookbackDays      = 30d;
let BulkContextThresh = 5;    // single interaction accessing ≥5 resources = bulk
let SensitiveLabels   = dynamic([
    "Confidential", "Highly Confidential", "Secret", "Restricted",
    "Internal Only", "Sensitive", "Protected", "Classification: Confidential",
    "Classification: Highly Confidential"]);

// ── Step 1: All Copilot events — retain interaction-level metadata ───────────────────────
let CopilotInteractions = OfficeActivity
    | where TimeGenerated > ago(LookbackDays)
    | where RecordType == "CopilotInteraction"
    | extend AppHost       = tostring(OperationProperties.AppHost)
    | extend Contexts      = OperationProperties.Contexts
    | extend ContextCount  = array_length(Contexts)
    | extend IsBulkContext = ContextCount >= BulkContextThresh
    // Drop interactions where Copilot accessed nothing (e.g., pure text prompts)
    | where ContextCount > 0;

// ── Step 2: Expand to one row per resource accessed ──────────────────────────────────────
let ContextExpanded = CopilotInteractions
    | mv-expand Context = Contexts
    | extend ContextId    = tostring(Context.Id)           // URL or document ID
    | extend ContextType  = tostring(Context.Type)         // file, email, page, etc.
    | extend ContextLabel = tostring(Context.SensitivityLabel)
    | extend IsSensitive  = isnotempty(ContextLabel)
                         and ContextLabel has_any (SensitiveLabels);

// ── Step 3: Per-user aggregate across all interactions ───────────────────────────────────
ContextExpanded
| summarize
    TotalInteractions          = dcount(TimeGenerated),
    TotalResourcesAccessed     = count(),
    SensitiveResourceCount     = countif(IsSensitive),
    BulkInteractionCount       = dcountif(TimeGenerated, IsBulkContext),
    DistinctAppHosts           = dcount(AppHost),
    AppHostsUsed               = make_set(AppHost, 8),
    // All unique label strings seen, including benign ones  
    LabelsEncountered          = make_set(ContextLabel, 20),
    // Only the sensitive-tier labels
    SensitiveLabelsFound       = make_set_if(ContextLabel, IsSensitive, 10),
    // Up to 20 sample resource IDs/URLs for sensitive hits — use in investigation
    SampleSensitiveResources   = make_set_if(ContextId, IsSensitive, 20),
    // Up to 10 sample resource IDs for non-sensitive hits (for completeness)
    SampleOtherResources       = make_set_if(ContextId, not(IsSensitive), 10),
    FirstSeen                  = min(TimeGenerated),
    LastSeen                   = max(TimeGenerated)
    by UserId
| extend
    SensitiveRatio             = round(todouble(SensitiveResourceCount) / todouble(TotalResourcesAccessed), 2),
    AvgResourcesPerInteraction = round(todouble(TotalResourcesAccessed) / todouble(TotalInteractions), 1)
| extend RiskScore = toint(
    // Absolute sensitive-resource volume
      iif(SensitiveResourceCount  >= 50, 4,
      iif(SensitiveResourceCount  >= 10, 3,
      iif(SensitiveResourceCount  >= 3,  2,
      iif(SensitiveResourceCount  >= 1,  1, 0))))
    // Proportion of interactions touching sensitive files
    + iif(SensitiveRatio          >= 0.5, 2,
      iif(SensitiveRatio          >= 0.2, 1, 0))
    // Many interactions each pulling many documents (batch harvesting pattern)
    + iif(BulkInteractionCount    >= 10,  2,
      iif(BulkInteractionCount    >= 1,   1, 0))
    // Total resource volume: high absolute number even without labels is notable
    + iif(TotalResourcesAccessed  >= 200, 2,
      iif(TotalResourcesAccessed  >= 50,  1, 0))
    // High average: each prompt pulls many docs → harvesting via summarise/compare
    + iif(AvgResourcesPerInteraction >= 8, 2,
      iif(AvgResourcesPerInteraction >= 5, 1, 0)))
| extend AnomalyFlags = strcat_array(pack_array(
    iif(SensitiveResourceCount >= 1,
        strcat("SensitiveFiles(", tostring(SensitiveResourceCount), ")"),           ""),
    iif(SensitiveRatio >= 0.3,            "HighSensitiveRatio",                     ""),
    iif(BulkInteractionCount >= 1,
        strcat("BulkContextPrompts(", tostring(BulkInteractionCount), ")"),         ""),
    iif(TotalResourcesAccessed >= 50,
        strcat("HighResourceVolume(", tostring(TotalResourcesAccessed), ")"),       ""),
    iif(AvgResourcesPerInteraction >= 5,
        strcat("HighAvgPerPrompt(", tostring(AvgResourcesPerInteraction), ")"),     "")),
    ",")
| extend WhySuspicious = strcat(
    "User '", UserId, "' had Copilot access ", tostring(TotalResourcesAccessed),
    " resource(s) across ", tostring(TotalInteractions), " interaction(s) in 30d ",
    "(avg ", tostring(AvgResourcesPerInteraction), " resources/prompt). ",
    tostring(SensitiveResourceCount), " resource(s) carried a sensitivity label: [",
    strcat_array(SensitiveLabelsFound, " | "), "]. ",
    tostring(BulkInteractionCount), " prompt(s) accessed ≥", tostring(BulkContextThresh),
    " files in a single call (bulk harvesting pattern). ",
    "Apps used: [", strcat_array(AppHostsUsed, ", "), "]. ",
    "Sample sensitive resource IDs/URLs: [",
    strcat_array(SampleSensitiveResources, " | "), "].")
| where RiskScore >= 1
| project
    UserId,
    TotalInteractions,
    TotalResourcesAccessed,
    AvgResourcesPerInteraction,
    SensitiveResourceCount,
    SensitiveRatio,
    SensitiveLabelsFound,
    BulkInteractionCount,
    AppHostsUsed,
    SampleSensitiveResources,
    SampleOtherResources,
    LabelsEncountered,
    FirstSeen,
    LastSeen,
    RiskScore,
    AnomalyFlags,
    WhySuspicious
| sort by RiskScore desc, SensitiveResourceCount desc

// Title: HUNT-25 Storage-DataProtection-Changes.kql
// Source: https://www.kqlsearch.com/query/HUNT-25_Storage-DataProtection-Changes&cms3l2fmz000cqu8kq5nzx5tj
// Section: KQL
// Author: David Alonso
// Description:
// Hunt     : Hunt - Storage Data-Protection Config Changes: Immutability / Legal Hold / Soft-Delete (30d)
// Tactics  : Impact, DefenseEvasion
// MITRE    : T1490 (Inhibit System Recovery), T1562
// Purpose  : Broad companion to RULE-20. Timeline of every change that weakens Azure Storage
// recovery guardrails — immutability policies, legal holds, blob/container soft-delete,
// versioning, and account deletion. Use to confirm RULE-20 alerts and to spot slow,
// piecemeal guardrail erosion that stays under the alert rule's window.
// ==========================================================================================

let Window = 30d;
let ProtectionOps = dynamic([
    "IMMUTABILITYPOLICIES/DELETE",
    "IMMUTABILITYPOLICIES/EXTEND/ACTION",
    "IMMUTABILITYPOLICIES/LOCK/ACTION",
    "LEGALHOLDS/CLEAR/ACTION",
    "LEGALHOLDS/SETLEGALHOLD/ACTION",
    "BLOBSERVICES/DEFAULT/DELETE",
    "BLOBSERVICES/DEFAULT/WRITE",
    "STORAGEACCOUNTS/DELETE"
]);
AzureActivity
| where TimeGenerated > ago(Window)
| where ActivityStatusValue =~ "Success"
| where OperationNameValue has_any (ProtectionOps)
| extend StorageAccount = tostring(split(ResourceId, "/")[8])
| extend ChangeKind = case(
    OperationNameValue has "IMMUTABILITYPOLICIES/DELETE",        "Immutability Policy Deleted",
    OperationNameValue has "IMMUTABILITYPOLICIES/EXTEND",        "Immutability Policy Extended/Changed",
    OperationNameValue has "IMMUTABILITYPOLICIES/LOCK",          "Immutability Policy Locked",
    OperationNameValue has "LEGALHOLDS/CLEAR",                   "Legal Hold Cleared",
    OperationNameValue has "LEGALHOLDS/SETLEGALHOLD",            "Legal Hold Set",
    OperationNameValue has "BLOBSERVICES/DEFAULT/DELETE",        "Blob Service Settings Deleted",
    OperationNameValue has "BLOBSERVICES/DEFAULT/WRITE",         "Blob Service Settings Changed (soft-delete/versioning)",
    OperationNameValue has "STORAGEACCOUNTS/DELETE",             "Storage Account Deleted",
    "Other")
| extend WeakensRecovery = ChangeKind in (
    "Immutability Policy Deleted", "Immutability Policy Extended/Changed",
    "Legal Hold Cleared", "Blob Service Settings Deleted",
    "Blob Service Settings Changed (soft-delete/versioning)", "Storage Account Deleted")
| project TimeGenerated, Caller, CallerIpAddress, ChangeKind, WeakensRecovery,
    StorageAccount, ResourceId, ResourceGroup, SubscriptionId
| order by WeakensRecovery desc, TimeGenerated desc

// Title: HUNT-26 Risky-Anonymizer-Signin-Timeline.kql
// Source: https://www.kqlsearch.com/query/HUNT-26_Risky-Anonymizer-Signin-Timeline&cms3l2lae000dqu8kg9eb751n
// Section: KQL
// Author: David Alonso
// Description:
// Hunt     : Hunt - Risky & Anonymizer Sign-in Timeline (30d)
// Tactics  : InitialAccess, DefenseEvasion
// MITRE    : T1078.004, T1090.003
// Purpose  : Broad companion to RULE-19. Timeline of successful sign-ins that AAD Identity
// Protection flagged as risky or anonymizer-sourced (Tor/anonymous VPN), across both
// users and workload identities. Use to baseline anonymizer usage, hunt for
// low-and-slow access under the alert-rule window, and pivot on repeat IPs/ASNs.
// ==========================================================================================

let Window = 30d;
let AnonRiskTypes = dynamic(["anonymizedIPAddress", "anonymousIPAddress"]);
let UserRisky = SigninLogs
    | where TimeGenerated > ago(Window)
    | where ResultType == 0
    | where isnotempty(IPAddress)
    | extend RiskTypes = tostring(column_ifexists("RiskEventTypes_V2", dynamic([])))
    | where RiskTypes has_any (AnonRiskTypes)
        or RiskLevelAggregated in~ ("medium", "high")
        or RiskState =~ "atRisk"
    | project TimeGenerated, IdentityKind = "User", Identity = UserPrincipalName,
        IPAddress, Location = tostring(Location), AppDisplayName,
        RiskLevel = tostring(RiskLevelAggregated), RiskTypes,
        ConditionalAccessStatus;
let SPRisky = AADServicePrincipalSignInLogs
    | where TimeGenerated > ago(Window)
    | where ResultType == 0
    | where isnotempty(IPAddress)
    | extend RiskTypes = tostring(column_ifexists("RiskEventTypes_V2", dynamic([])))
    | where RiskTypes has_any (AnonRiskTypes)
    | project TimeGenerated, IdentityKind = "ServicePrincipal", Identity = ServicePrincipalName,
        IPAddress, Location = tostring(LocationDetails.countryOrRegion), AppDisplayName = AppId,
        RiskLevel = "n/a", RiskTypes, ConditionalAccessStatus;
union UserRisky, SPRisky
| order by TimeGenerated desc

// Title: Hunt for High Volume Phish ISP.kql
// Source: https://www.kqlsearch.com/query/Hunt%20for%20High%20Volume%20Phish%20ISP&cm5xj73zs00005idw4wmusi4f
// Section: KQL
// Author: Steven Lim
// Description:
// During my routine threat hunting, I observed that the ISP "kuroit limited," which operates in the USA, London, and Amsterdam, is sending a significant number of malicious emails from gmail.com domains. This is something defenders should monitor and filter as necessary.🤝

CloudAppEvents
| where Application == "Microsoft Exchange Online"
| where ActionType == "TIMailData-Inline"
| where ActivityType == "Securityevent"
| where ISP == "kuroit limited"
| extend CAInternetMessageId = tostring(parse_json(RawEventData)["InternetMessageId"])
| join EmailEvents on $left.CAInternetMessageId == $right.InternetMessageId
| where EmailDirection == "Inbound"

// Title: HuntAccountsWithLeakedCredentials
// Source: https://www.kqlsearch.com/query/HuntAccountsWithLeakedCredentials&cmkv4vrrt0000dzc47xk8mw10
// Section: Defender XDR
// Author: Robbe Van den Daele
// Description:
// This query searches for accounts where Exposure Management detected leaked credentials. This query is correlated with the `IdentityInfo` table, mainly because you can easily create a detection of this rule if you would like to.

IdentityInfo
| summarize arg_max(TimeGenerated, AccountUpn, AccountDisplayName, AccountDomain, CriticalityLevel, DistinguishedName) by AccountObjectId
| join kind=inner (
    ExposureGraphNodes
    // Get accounts with Leaked Credentials
    | where NodeProperties.rawData.hasAdLeakedCredentials == "true" or NodeProperties.rawData.hasLeakedCredentials == "true"
    // Get the AAD Object ID
    | mv-expand EntityIds
    | where EntityIds.type == "AadObjectId"
    | extend AccountObjectId = extract('objectid=(.*)', 1, tostring(EntityIds.id))
    | extend HasAdLeakedCredentials = tostring(NodeProperties.rawData.hasAdLeakedCredentials),
        HasLeakedCredentials = tostring(NodeProperties.rawData.hasLeakedCredentials)
    | distinct NodeLabel, AccountObjectId, HasAdLeakedCredentials, HasLeakedCredentials
) on AccountObjectId

// Title: HuntADWSRequestsFromUnknownDevice
// Source: https://www.kqlsearch.com/query/HuntADWSRequestsFromUnknownDevice&cm7wx70s000w7p10fosdk1sjr
// Section: Defender XDR
// Author: Robbe Van den Daele
// Description:
// This hunting rule searches for incomming ADWS connections on Domain Controllers (DC's need to be onboarded in Defender for Endpoint) from IP Addresses that cannot be linked to MDE onboarded devices.

let device_info = (
    // Get device network info from last 7 days
    DeviceNetworkInfo
    | where Timestamp > ago(7d)
    // Expand the IP Addresses of the devices
    | mv-expand todynamic(IPAddresses)
    | extend IPAddress = tostring(IPAddresses.IPAddress)
    // Distinct IP address for each device
    | distinct DeviceName, DeviceId, IPAddress
    // Search for each device if it is onboarded or not
    | join kind=inner (
        DeviceInfo 
        | where Timestamp > ago(7d)
        | distinct DeviceName, DeviceId, OnboardingStatus
        // Get the first timestamp the device was seen
        | join kind=inner (
            DeviceInfo
            | where Timestamp > ago(30d)
            | summarize FirstSeen = arg_min(Timestamp, DeviceId) by DeviceId
        ) on DeviceId
        | project-away DeviceId1, DeviceId2
    ) on DeviceId, DeviceName
    | project-away DeviceName1, DeviceId1
);
// Get incomming traffic on ADWS port and save unique remote IP addresses
DeviceNetworkEvents
| where Timestamp > ago(30d)
| where ActionType != "ListeningConnectionCreated"
| where InitiatingProcessFolderPath == @"c:\windows\adws\microsoft.activedirectory.webservices.exe"
| where LocalPort == "9389"
| summarize ConnectionTimes=make_list(Timestamp) by RemoteIP, DeviceName
// Get device information of remote IP addresses, results for IP we do not find information for are allowed
| join kind=leftouter device_info on $left.RemoteIP == $right.IPAddress
| project-away IPAddress
// Check if the remote IPs are onboarded devices or not
| where OnboardingStatus != "Onboarded"
// Make output better
| project DeviceName, ConnectionTimes, RemoteIP, RemoteDeviceName = DeviceName1, RemoteDeviceId = DeviceId, RemoteOnboardingStatus = OnboardingStatus, RemoteDeviceFirstSeen = FirstSeen

