// Title: identify-how-quick-a-confirmed-compromised-account-changed-password
// Source: https://www.kqlsearch.com/query/identify-how-quick-a-confirmed-compromised-account-changed-password&clq6ommko01wrmc0odc27mq47
// Section: Microsoft Sentinel
// Author: Michalis Michalos
// Description:
// The following query will identify how much time has occurred since a confirmed compromised account, changed password.

// Define the timeframe you would like to look into
let timeframe = 90d;
AuditLogs
    | where TimeGenerated > ago(timeframe)
    | where OperationName == "ConfirmAccountCompromised"
    | extend SuspUser = tostring(TargetResources[0].userPrincipalName)
    | project SuspUser, ConfirmTime=TimeGenerated
| join kind=inner (
    AuditLogs
    | where TimeGenerated > ago(timeframe)
    | where OperationName == "Reset user password" or OperationName == "Reset password (self-service)" or OperationName == "Change user password"
    | where Result == "success"
    | extend SuspUserPw = tostring(TargetResources[0].userPrincipalName)
    | project SuspUserPw, PwChangeTime = TimeGenerated, OperationName
    )
on $left.SuspUser == $right.SuspUserPw
| project SuspUser, ConfirmTime, SuspUserPw, PwChangeTime, OperationName, PwChangeTimeframe = (PwChangeTime - ConfirmTime)
| sort by ConfirmTime desc

// Title: identify-isolated-endpoints
// Source: https://www.kqlsearch.com/query/identify-isolated-endpoints&clt7ah1gs00n9mc0po580bcdg
// Section: Microsoft Defender XDR
// Author: Michalis Michalos
// Description:
// The following query will return endpoints which have been isolated by looking into relevant registry modifications.

DeviceRegistryEvents
| where ActionType == "RegistryValueSet"
| where RegistryKey == @"HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows Advanced Threat Protection"
| where RegistryValueType == "Dword"
| where RegistryValueName == "DisableEnterpriseAuthProxyValueToRestoreAfterIsolation"
| where RegistryValueData == "1"
| where PreviousRegistryValueName == "DisableEnterpriseAuthProxyValueToRestoreAfterIsolation"
| project Timestamp, DeviceId, DeviceName

// Title: identify mail items accessed by a specific IP address (CISA).kql
// Source: https://www.kqlsearch.com/query/identify%20mail%20items%20accessed%20by%20a%20specific%20IP%20address%20(CISA)&cm652s7lm005anw0fnefkb6cy
// Section: KQL
// Author: Jay Kerai
// Description:
// Query is from CISA Playbook https://www.cisa.gov/sites/default/files/2025-01/microsoft-expanded-cloud-logs-implementation-playbook-508c.pdf
// Get sessions associated with suspicious IP address

let bad_sessions = materialize (
AADSignInEventsBeta
| where IPAddress == 'x.x.x.x’ //Replace with IP of interest
| where isempty(SessionId) == false
| distinct SessionId
);
//Get any mail accessed during suspicious sessions
CloudAppEvents
| where ActionType == 'MailItemsAccessed'
| where RawEventData.SessionId has_any (bad_sessions)

// Title: identify-mdeasm-hosts-with-high-or-critical-vulnerabilities-and-a-cvss-score-over-8
// Source: https://www.kqlsearch.com/query/identify-mdeasm-hosts-with-high-or-critical-vulnerabilities-and-a-cvss-score-over-8&cmdrdgr070003uoadyo0r1qds
// Section: Microsoft Defender XDR
// Author: Michalis Michalos
// Description:
// The following query will uncover hosts that are available from Microsoft Defender External Attack Surface Management with High or Critical vulnerabilities and a CVSS score over 8 in the Advanced Hunting tables from Exposure Management.

ExposureGraphNodes
| where NodeLabel == @"dns-host"
| extend GraphNodeProperties = parse_json(NodeProperties)
| where GraphNodeProperties["rawData"]["highRiskVulnerabilityInsights"]["hasHighOrCritical"] == "true"
| where toreal(GraphNodeProperties["rawData"]["highRiskVulnerabilityInsights"]["maxCvssScore"]) > 8
| extend CVSSScore = parse_json(NodeProperties)["rawData"]["highRiskVulnerabilityInsights"]["vulnerableToRemoteCodeExecution"]["maxCvssScore"]
| project NodeId, Host=NodeName, CVSSScore

// Title: Identify Processes That Are Heavily Using Disk Space.kql
// Source: https://www.kqlsearch.com/query/Identify%20Processes%20That%20Are%20Heavily%20Using%20Disk%20Space&cls8yzeli000e5iv8vx3w1yud
// Section: KQL
// Author: Ugur Koc
// Description:
// Use Case: Identifying and prioritizing processes with high on-disk working set size for system resource optimization.

Process
| where OnDisk == true
| project ProcessName, Path, WorkingSetSizeMB = WorkingSetSizeBytes / (1024 * 1024), OnDisk
| order by WorkingSetSizeMB desc

// Title: Identify Top Disk IO Processes.kql
// Source: https://www.kqlsearch.com/query/Identify%20Top%20Disk%20IO%20Processes&cm4n2cf8z00hpmc0lb6ndeay7
// Section: KQL
// Author: Ugur Koc
// Description:
// Use Case: Identifying and prioritizing processes with high on-disk working set size for system resource optimization.

Process
| where DiskBytesRead > 50000000 or DiskBytesWritten > 50000000
| project ProcessName, ProcessId, DiskBytesRead, DiskBytesWritten
| order by DiskBytesRead desc, DiskBytesWritten desc
| take 5

