// Title: ImpossibleTravelDeviceRegistration.yaml
// Source: https://www.kqlsearch.com/query/ImpossibleTravelDeviceRegistration&cmqtv7o5b005ubljhlezrccvd
// Section: KQL
// Author: David Alonso
// Description:
// Correlates a new Intune/Azure AD device registration with a sign-in from a geographic
// location inconsistent with the user's recent sign-ins (impossible travel). Common in
// token-theft scenarios where an adversary registers their own device using a stolen PRT
// or refresh token (AADInternals `Join-AADIntDeviceToAzureAD -PRTToken`).

let lookback = 1d;
let NetworkAllowlist = _GetWatchlist('NetworkAllowlist') | project IPRange = tostring(SearchKey);
let AllowedRanges = toscalar(NetworkAllowlist | summarize make_list(IPRange));
let registrations =
    IntuneAuditLogs
    | where TimeGenerated > ago(lookback)
    | where OperationName has_any ("enroll","register","Create Device")
    | extend DeviceName = tostring(parse_json(tostring(Properties)).TargetObjectName)
    | project RegTime=TimeGenerated, UserPrincipalName=tolower(tostring(Identity)), DeviceName, OperationName;
let signins =
    SigninLogs
    | where TimeGenerated > ago(lookback)
    | where ResultType == 0
    | project SignInTime=TimeGenerated, UserPrincipalName=tolower(UserPrincipalName),
              IPAddress, Location=tostring(LocationDetails.countryOrRegion),
              City=tostring(LocationDetails.city), AppDisplayName, DeviceDetail=tostring(DeviceDetail);
registrations
| join kind=inner signins on UserPrincipalName
| where not(ipv4_is_in_any_range(tostring(IPAddress), AllowedRanges))
| where abs(datetime_diff('minute', RegTime, SignInTime)) <= 60
| summarize Locations = make_set(Location, 10),
            Cities = make_set(City, 10),
            IPs = make_set(IPAddress, 10),
            Apps = make_set(AppDisplayName, 10),
            FirstSignIn = min(SignInTime), LastSignIn = max(SignInTime)
          by UserPrincipalName, DeviceName, RegTime, OperationName
| where array_length(Locations) > 1
| extend AccountCustomEntity = UserPrincipalName, HostCustomEntity = DeviceName

// Title: ImpossibleTravelKQL.txt
// Source: https://www.kqlsearch.com/query/ImpossibleTravelKQL&clmp0vbeu00ljmc0kac3kui02
// Section: KQL
// Author: Rod Trent
// Description:
// SecurityAlert

SecurityAlert
| where AlertName == "Impossible travel activity"
| project (parse_json(Entities)[1].Name), Entities
| extend Name_ = tostring(parse_json(Entities)[3].Name)

// Title: InboundAuthenticationFromPublicIP
// Source: https://www.kqlsearch.com/query/InboundAuthenticationFromPublicIP&cm45l9gvi006hmc0les58lh4v
// Section: Sentinel
// Author: Bert-Jan Pals
// Description:
// This query can be used to identify devices that are publicly disclosed to the internet by monitoring for inbound authentication attempts.

let AllowedEntpoints = pack_array('devicename');
SecurityEvent
| where EventID in ('4625', '4624')
| where Computer !in(AllowedEntpoints)
| where not(ipv4_is_private(IpAddress))
| summarize arg_min(TimeGenerated, *) by Computer
| lookup kind=leftouter (DeviceInfo
    | summarize arg_max(TimeGenerated, *) by DeviceId
    | project DeviceName = toupper(DeviceName), DeviceType, PublicIP, ExposureLevel, MachineGroup) on $left.Computer == $right.DeviceName

// Title: Incidents by severity - last 24 hours.kql
// Source: https://www.kqlsearch.com/query/Incidents%20by%20severity%20-%20last%2024%20hours&clmp1cb6100pamc0ktaku4bgq
// Section: KQL
// Author: Rod Trent
// Description:
// SecurityIncident

SecurityIncident
| summarize arg_max(LastModifiedTime,Severity) by IncidentName
| summarize Count = count() by Severity

// Title: Incidents status by creation time - last 24 hours.kql
// Source: https://www.kqlsearch.com/query/Incidents%20status%20by%20creation%20time%20-%20last%2024%20hours&clmp1cl2w00pcmc0k8cde3ykf
// Section: KQL
// Author: Rod Trent
// Description:
// SecurityIncident

SecurityIncident
| where CreatedTime > ago(1d)
| summarize arg_max(LastModifiedTime, Status, CreatedTime) by IncidentName
| summarize Count = count() by Status, bin(CreatedTime, 4h)
| extend StatusCount = pack(Status, Count) 
| summarize StatusCountArray = make_bag(StatusCount) by CreatedTime 
| evaluate bag_unpack(StatusCountArray)
| project Result = pack_all()

// Title: Infrastructure Vulnerability Exposure to Volt Typhoon.kql
// Source: https://www.kqlsearch.com/query/Infrastructure%20Vulnerability%20Exposure%20to%20Volt%20Typhoon&cm051ioqw00g2mc0p2dnftvw9
// Section: KQL
// Author: Steven Lim
// Description:
// Infrastructure Vulnerability Exposure to Volt Typhoon
// Expert analysis from last year revealed that PRC APT groups, such as Volt Typhoon, frequently exploit known vulnerabilities in TP-Link routers during their malicious campaigns. These campaigns have included targeting government officials in European countries. In these attacks, modified firmware images have so far been found exclusively on TP-Link routers.
// Given the portability of user laptops, there is a risk that a laptop used for work might connect to a TP-Link wireless router at home, in a café, or at another mobile working location. This connection increases the security risk for both the endpoint and the TP-Link router, potentially making them vulnerable to exploitation.
// By leveraging Microsoft’s endpoint discovery capabilities, you can identify if any of your endpoints have connected to or detected a TP-Link router. Additionally, correlating the vulnerabilities present on these endpoints can help estimate the exposure risk to APT groups exploiting TP-Link routers.
// The below KQL query will provide you a summary of your total endpoints vulnerabilities count (High, Medium & Low) that are exposed to a TP-Link router environment.

let DeviceExposedToTPLinkRouter =
DeviceInfo
| summarize arg_max(Timestamp, *) by DeviceId
| where isempty(MergedToDeviceId)
| where OnboardingStatus != "Onboarded"
| where Vendor contains "TP-LINK"
| invoke SeenBy()
| extend parsedJson = parse_json(SeenBy)
| extend SeenByDeviceID = tostring(parsedJson[0].DeviceId)
| project SeenByDeviceID;
DeviceTvmSoftwareVulnerabilities
| where DeviceId has_any(DeviceExposedToTPLinkRouter)
| summarize VulnerabilityCount=count() by VulnerabilitySeverityLevel

