// Section: Microsoft Defender XDR
// Author: Alex Verboon
// Description:
// Use the below query to retrieve Active Directory Service Accounts from the Defender for Identity Service Accounts inventory.
//
// Service Account Types
//
// - ***gMSA (Group Managed Service Accounts)*** gMSAs provide a single identity solution for multiple services that require mutual authentication
// across multiple servers, as they allow Windows to handle password management, reducing administrative overhead.
// - ***sMSA (Managed Service Accounts)*** Like gMSA but are designed for individual services on a single server rather than groups.
// - ***User Account*** These standard user accounts are typically used for interactive logins but can also be configured to run services.
//
// Regular User Accounts are classified as 'Service Accounts' when the account is configured to "Password never expires" AND has a SPN (Service Principal Name)

IdentityInfo
| where Timestamp > ago(30d)
| where Type == @"ServiceAccount"
| where SourceProvider == @"ActiveDirectory"
| summarize arg_max(Timestamp,*) by OnPremSid

// Title: MDI-ServiceAccounts
// Source: https://www.kqlsearch.com/query/MDI-ServiceAccounts&cm94j3f1b01oqp10f2fymxpqx
// Section: Microsoft Defender XDR
// Author: Alex Verboon
// Description:
// Use the below query to retrieve Active Directory Service Accounts from the Defender for Identity Service Accounts inventory.
//
// Service Account Types
//
// - ***gMSA (Group Managed Service Accounts)*** gMSAs provide a single identity solution for multiple services that require mutual authentication
// across multiple servers, as they allow Windows to handle password management, reducing administrative overhead.
// - ***sMSA (Managed Service Accounts)*** Like gMSA but are designed for individual services on a single server rather than groups.
// - ***User Account*** These standard user accounts are typically used for interactive logins but can also be configured to run services.
//
// Regular User Accounts are classified as 'Service Accounts' when the account is configured to "Password never expires" AND has a SPN (Service Principal Name)

IdentityInfo
| summarize arg_max(Timestamp,*) by AccountName
| project AccountName, DistinguishedName
| extend OUPath = extract(@"CN=[^,]+,(.*)", 1, DistinguishedName)
| where OUPath contains "OU=ServiceAccounts"
| distinct OUPath

// Title: MDO-01-Malicious-Email-Delivered-to-Inbox.yaml
// Source: https://www.kqlsearch.com/query/MDO-01-Malicious-Email-Delivered-to-Inbox&cmroxhvv50005l1s169ytn717
// Section: KQL
// Author: David Alonso
// Description:
// Surfaces emails that carried a Phish/Malware verdict yet were still delivered to the
// user's Inbox - the highest residual-risk point in Defender for Office 365. Each row is a
// malicious message sitting in a mailbox.
//
// Value: demonstrates MDO effectiveness and prioritises manual purge / ZAP verification.
// Triage: check for a click (UrlClickEvents) and whether ZAP later removed it
// (EmailPostDeliveryEvents); manually purge if still present.

EmailEvents
| where Timestamp > ago(7d)
| where ThreatTypes has_any ("Phish", "Malware")
| where DeliveryAction == "Delivered"
| where DeliveryLocation in ("Inbox/folder", "Inbox")
| project Timestamp, NetworkMessageId, SenderFromAddress, RecipientEmailAddress,
          Subject, ThreatTypes, ThreatNames, DetectionMethods,
          DeliveryLocation, LatestDeliveryLocation
| sort by Timestamp desc

// Title: MDO-02-Phishing-Campaign-Clustering.yaml
// Source: https://www.kqlsearch.com/query/MDO-02-Phishing-Campaign-Clustering&cmroxi0k20006l1s17clvzj4r
// Section: KQL
// Author: David Alonso
// Description:
// Groups similar phishing messages (subject + sender domain) to move from "one email" to
// "a campaign" and size the blast radius. Prioritise clusters where Delivered > 0.
//
// Value: turns isolated detections into campaign-level situational awareness.
// Triage: a single subject hitting dozens of recipients is a targeted campaign that may
// warrant an org-wide advisory. Pivot delivered clusters to UrlClickEvents for exposure.

EmailEvents
| where Timestamp > ago(7d)
| where ThreatTypes has "Phish"
| summarize
    Recipients = dcount(RecipientEmailAddress),
    Messages   = count(),
    Senders    = make_set(SenderFromAddress, 15),
    Delivered  = countif(DeliveryAction == "Delivered"),
    FirstSeen  = min(Timestamp),
    LastSeen   = max(Timestamp)
    by Subject, SenderFromDomain
| where Recipients >= 5
| sort by Recipients desc

// Title: MDO-03-Confirmed-Malware-Attachments.yaml
// Source: https://www.kqlsearch.com/query/MDO-03-Confirmed-Malware-Attachments&cmroxia920007l1s1pbh3bn2r
// Section: KQL
// Author: David Alonso
// Description:
// Lists email attachments with a confirmed Malware verdict. Each SHA256 is a pivot point
// into endpoint telemetry to confirm whether the file executed.
//
// Value: bridges MDO (mail) to MDE (endpoint).
// Triage: pivot each SHA256 to DeviceFileEvents / DeviceProcessEvents to check whether the
// attachment landed and ran on a device (MDO <-> MDE correlation).

EmailAttachmentInfo
| where Timestamp > ago(7d)
| where ThreatTypes has "Malware"
| project Timestamp, NetworkMessageId, SenderFromAddress, RecipientEmailAddress,
          FileName, FileType, SHA256, ThreatNames, DetectionMethods, FileSize
| sort by Timestamp desc

// Title: MDO-04-Dangerous-File-Types-Delivered.yaml
// Source: https://www.kqlsearch.com/query/MDO-04-Dangerous-File-Types-Delivered&cmroxierf0008l1s1uat0x1pa
// Section: KQL
// Author: David Alonso
// Description:
// Detects high-risk attachment extensions that reached the mailbox even without a threat
// verdict (evasion / zero-day). Container formats (iso, img, lnk, one) are common evasion
// vectors.
//
// Value: catches malicious delivery that slipped past verdict-based blocking.
// Triage: watch for double extensions and lure names ("invoice", "CV", "payment"). Pivot
// SHA256 to endpoint tables.

let RiskyTypes = dynamic(["exe","scr","js","vbs","ps1","lnk","iso","img","hta","cmd","bat","wsf","jar","one"]);
EmailAttachmentInfo
| where Timestamp > ago(7d)
| where FileType in~ (RiskyTypes)
    or FileName has_any (".exe",".scr",".js",".lnk",".iso",".img",".hta",".one",".vbs")
| join kind=inner (
    EmailEvents
    | where DeliveryAction == "Delivered"
    | project NetworkMessageId, DeliveryLocation, Subject, EmailDirection
) on NetworkMessageId
| project Timestamp, SenderFromAddress, RecipientEmailAddress, FileName, FileType,
          Subject, DeliveryLocation, EmailDirection, SHA256
| sort by Timestamp desc

// Title: MDO-05-SafeLinks-ClickThrough-To-Blocked-URL.yaml
// Source: https://www.kqlsearch.com/query/MDO-05-SafeLinks-ClickThrough-To-Blocked-URL&cmroxik350009l1s176we1j4i
// Section: KQL
// Author: David Alonso
// Description:
// High-value MDO use case: users who, despite the Safe Links warning page, chose to
// continue to a malicious link. Each click-through user is a compromise candidate.
//
// Value: identifies real user exposure that survived a protective control.
// Triage: review each user's subsequent sign-ins (AADSignInEventsBeta / SigninLogs) for
// credential-theft signals; consider forced password reset and session revocation.

UrlClickEvents
| where Timestamp > ago(7d)
| where ActionType == "ClickAllowed" or IsClickedThrough != ""
| where ThreatTypes has_any ("Phish", "Malware")
| project Timestamp, AccountUpn, Url, ThreatTypes, DetectionMethods,
          IPAddress, IsClickedThrough, Workload, NetworkMessageId
| sort by Timestamp desc

// Title: MDO-06-Users-Clicked-Confirmed-Malicious.yaml
// Source: https://www.kqlsearch.com/query/MDO-06-Users-Clicked-Confirmed-Malicious&cmroxip19000al1s18vkcufss
// Section: KQL
// Author: David Alonso
// Description:
// Correlates EmailEvents (verdict) with UrlClickEvents (click) to find real exposure: users
// who clicked a link in a message that was (or later became) Phish/Malware.
//
// Value: turns a campaign into a concrete victim list.
// Triage: prioritise credential reset and targeted awareness for the returned users; cross
// AccountUpn with anomalous sign-in signals.

let MaliciousMail =
    EmailEvents
    | where Timestamp > ago(14d)
    | where ThreatTypes has_any ("Phish", "Malware")
    | project NetworkMessageId, RecipientEmailAddress, Subject, ThreatTypes;
UrlClickEvents
| where Timestamp > ago(14d)
| join kind=inner MaliciousMail on NetworkMessageId
| project Timestamp, AccountUpn, Url, Subject, ThreatTypes, IsClickedThrough,
          IPAddress, Workload
| sort by Timestamp desc

// Title: MDO-07-Email-Auth-Failures-Spoofing.yaml
// Source: https://www.kqlsearch.com/query/MDO-07-Email-Auth-Failures-Spoofing&cmroxit87000bl1s1n75r00s4
// Section: KQL
// Author: David Alonso
// Description:
// Detects impersonation of trusted domains via inbound email authentication results.
// DMARC failures on delivered mail claiming to be from your own or partner domains are
// strong spoofing / BEC indicators.
//
// Value: exposes domain spoofing that reached mailboxes.
// Triage: focus on Delivered > 0 for sender domains you own or trust; consider tightening
// the anti-spoofing / DMARC enforcement policy.

EmailEvents
| where Timestamp > ago(7d)
| where EmailDirection == "Inbound"
| extend Auth = parse_json(AuthenticationDetails)
| extend SPF = tostring(Auth.SPF), DKIM = tostring(Auth.DKIM),
         DMARC = tostring(Auth.DMARC), CompAuth = tostring(Auth.CompAuth)
| where DMARC == "fail" or (SPF == "fail" and DKIM == "fail")
| summarize Messages = count(),
            Recipients = dcount(RecipientEmailAddress),
            Delivered = countif(DeliveryAction == "Delivered")
    by SenderFromDomain, SPF, DKIM, DMARC, CompAuth
| where Delivered > 0
| sort by Messages desc

// Title: MDO-08-BEC-DisplayName-Impersonation.yaml
// Source: https://www.kqlsearch.com/query/MDO-08-BEC-DisplayName-Impersonation&cmroxiz12000cl1s1vp2m2u8s
// Section: KQL
// Author: David Alonso
// Description:
// Detects inbound emails whose display name imitates an executive but whose sender domain
// is NOT corporate - the classic CEO-fraud / BEC pattern.
//
// Customise the Execs and CorpDomains lists before operationalising.
// Triage: an exec display name from gmail / lookalike domains is a high-confidence fraud
// lead; verify out-of-band before any financial action.

let Execs = dynamic(["CEO Name","CFO Name","Managing Director"]);
let CorpDomains = dynamic(["contoso.com","contoso.es"]);
EmailEvents
| where Timestamp > ago(14d)
| where EmailDirection == "Inbound"
| where SenderDisplayName has_any (Execs)
| where not(SenderFromDomain in~ (CorpDomains))
| project Timestamp, SenderDisplayName, SenderFromAddress, SenderFromDomain,
          RecipientEmailAddress, Subject, DeliveryAction, DeliveryLocation
| sort by Timestamp desc

// Title: MDO-09-Lookalike-Typosquat-Domains.yaml
// Source: https://www.kqlsearch.com/query/MDO-09-Lookalike-Typosquat-Domains&cmroxj4ib000dl1s1yht811r5
// Section: KQL
// Author: David Alonso
// Description:
// Attackers register domains that resemble your brand. This query surfaces typosquatting /
// lookalike domains embedded in email URLs (e.g. contoso-support.com, cont0so.com,
// contoso.secure-login.net).
//
// Customise Brand and the legitimate-domain suffix.
// Triage: consider blocking the domains and adding them to brand-abuse monitoring.

let Brand = "contoso";
let LegitSuffix = "contoso.com";
EmailUrlInfo
| where Timestamp > ago(7d)
| where UrlDomain has Brand and UrlDomain !endswith LegitSuffix
| summarize Messages = dcount(NetworkMessageId), Urls = make_set(Url, 10),
            FirstSeen = min(Timestamp), LastSeen = max(Timestamp)
    by UrlDomain
| sort by Messages desc

// Title: MDO-10-ZAP-Gaps-Post-Delivery-Threats.yaml
// Source: https://www.kqlsearch.com/query/MDO-10-ZAP-Gaps-Post-Delivery-Threats&cmroxja7l000el1s1swtdegp5
// Section: KQL
// Author: David Alonso
// Description:
// EmailPostDeliveryEvents shows which already-delivered emails were pulled by Zero-hour
// Auto Purge (ZAP) - and, crucially, which ones could NOT be removed.
//
// Value: exposes residual risk where ZAP failed.
// Triage: focus on ActionResult != "Success" - malicious mail ZAP could not remove
// (e.g. moved/deleted by the user) that remains an active risk.

EmailPostDeliveryEvents
| where Timestamp > ago(7d)
| where Action has "ZAP" or ActionType has "ZAP"
| project Timestamp, NetworkMessageId, RecipientEmailAddress, Action, ActionType,
          ActionTrigger, ActionResult, DeliveryLocation, ThreatTypes
| sort by Timestamp desc

// Title: MDO-11-Exposure-Window-Delivery-To-Remediation.yaml
// Source: https://www.kqlsearch.com/query/MDO-11-Exposure-Window-Delivery-To-Remediation&cmroxjfef000fl1s1mft5qscw
// Section: KQL
// Author: David Alonso
// Description:
// Computes how long a malicious email sat in the mailbox before it was removed - a direct
// KPI for MDO effectiveness and SOC response time.
//
// Value: quantifies dwell time of malicious mail; great leadership metric.
// Triage: long exposure windows (hours/days) indicate late detection - use to justify
// policy tuning and demonstrate containment times.

let Delivered =
    EmailEvents
    | where Timestamp > ago(14d) and ThreatTypes != ""
    | project NetworkMessageId, DeliveredTime = Timestamp, RecipientEmailAddress,
              Subject, ThreatTypes;
EmailPostDeliveryEvents
| where Timestamp > ago(14d)
| join kind=inner Delivered on NetworkMessageId
| extend ExposureMinutes = datetime_diff('minute', Timestamp, DeliveredTime)
| where ExposureMinutes >= 0
| project DeliveredTime, RemediatedTime = Timestamp, ExposureMinutes,
          RecipientEmailAddress, Subject, ThreatTypes, Action, ActionResult
| sort by ExposureMinutes desc

// Title: MDO-12-Quishing-QR-Phishing-Images.yaml
// Source: https://www.kqlsearch.com/query/MDO-12-Quishing-QR-Phishing-Images&cmroxjlpu000gl1s1cygim0gi
// Section: KQL
// Author: David Alonso
// Description:
// QR-code phishing evades URL analysis by embedding the link inside an image attachment.
// This query finds inbound mail carrying an image with few/no analysable URLs and phishing
// / impersonation signals.
//
// Triage: an image-only email with a credential/MFA theme is a classic quishing pattern.
// Pair with targeted awareness. Consider adding QR-aware detonation policies.

EmailAttachmentInfo
| where Timestamp > ago(7d)
| where FileType in~ ("png","jpg","jpeg","gif","bmp","svg")
| join kind=inner (
    EmailEvents
    | where EmailDirection == "Inbound"
    | where UrlCount <= 1
    | where ThreatTypes has "Phish" or DetectionMethods has_any ("Spoof","Impersonation")
    | project NetworkMessageId, Subject, SenderFromAddress, RecipientEmailAddress, DeliveryAction
) on NetworkMessageId
| project Timestamp, SenderFromAddress, RecipientEmailAddress, FileName, FileType,
          Subject, DeliveryAction
| sort by Timestamp desc

// Title: MDO-13-Compromised-Internal-Sender.yaml
// Source: https://www.kqlsearch.com/query/MDO-13-Compromised-Internal-Sender&cmroxjsks000hl1s1k8w8mtb9
// Section: KQL
// Author: David Alonso
// Description:
// A malicious email sent from INSIDE the org usually means a compromised account used for
// lateral phishing. Flags internal senders pushing Phish/Malware to several colleagues.
//
// Value: early signal of account takeover being weaponised for internal spread.
// Triage: escalate to identity response (password reset, session revocation) and review the
// sender's recent sign-ins and inbox rules.

EmailEvents
| where Timestamp > ago(7d)
| where EmailDirection == "Intra-org"
| where ThreatTypes has_any ("Phish", "Malware")
| summarize Recipients = dcount(RecipientEmailAddress),
            Messages   = count(),
            Subjects   = make_set(Subject, 10),
            FirstSeen  = min(Timestamp),
            LastSeen   = max(Timestamp)
    by SenderFromAddress
| where Recipients >= 3
| sort by Recipients desc

// Title: MDO-14-Malicious-Campaign-Overview-EmailClusterId.yaml
// Source: https://www.kqlsearch.com/query/MDO-14-Malicious-Campaign-Overview-EmailClusterId&cmroxjvxl000il1s1f207ux7g
// Section: KQL
// Author: David Alonso
// Description:
// Reconstructs malicious mail campaigns directly from EmailEvents using Defender's own
// EmailClusterId, so it works regardless of CampaignInfo availability. Aggregates each
// cluster's reach, delivery success and threat mix.
//
// Value: campaign-level view (who/what/how many) for the last 30 days.
// Triage: prioritise clusters with Delivered > 0 and many recipients; pivot to
// UrlClickEvents (MDO-16) for real click exposure.

EmailEvents
| where Timestamp > ago(30d)
| where isnotempty(EmailClusterId)
| where ThreatTypes has_any ("Phish", "Malware")
| summarize
    Messages    = count(),
    Recipients  = dcount(RecipientEmailAddress),
    Delivered   = countif(DeliveryAction == "Delivered"),
    Blocked     = countif(DeliveryAction == "Blocked"),
    Senders     = make_set(SenderFromAddress, 15),
    Subjects    = make_set(Subject, 10),
    ThreatMix   = make_set(ThreatTypes, 10),
    Detections  = make_set(DetectionMethods, 10),
    FirstSeen   = min(Timestamp),
    LastSeen    = max(Timestamp)
    by EmailClusterId
| where Recipients >= 5
| extend DeliveredRatio = round(todouble(Delivered) / Messages, 2)
| sort by Recipients desc

// Title: MDO-15-Campaign-View-CampaignInfo.yaml
// Source: https://www.kqlsearch.com/query/MDO-15-Campaign-View-CampaignInfo&cmroxjzwz000jl1s1ecq16ib6
// Section: KQL
// Author: David Alonso
// Description:
// Reads Defender for Office 365 curated Campaign Views from the CampaignInfo Advanced
// Hunting table to list active malicious campaigns targeting the tenant.
//
// IMPORTANT: CampaignInfo is a newer/evolving MDO table and its columns can vary by
// tenant/ring. Run `CampaignInfo | getschema` first and adjust the projected columns below
// to match your tenant. This query is intentionally conservative (filter + sort) so it does
// not fail on a column mismatch; extend the summarize once you confirm the schema.
//
// Triage: cross-reference the campaign to EmailEvents / UrlClickEvents (MDO-14, MDO-16) to
// size delivered volume and real click exposure.

// Validate columns first:  CampaignInfo | getschema
CampaignInfo
| where Timestamp > ago(30d)
// Common fields (adjust to your tenant schema after getschema):
//   CampaignId, ThreatType, MessageCount, RecipientCount, StartTime, EndTime
| sort by Timestamp desc

// Title: MDO-16-Campaign-Exposure-Delivered-Clicked.yaml
// Source: https://www.kqlsearch.com/query/MDO-16-Campaign-Exposure-Delivered-Clicked&cmroxk5c4000kl1s1gtj32qlz
// Section: KQL
// Author: David Alonso
// Description:
// Joins malicious campaign clusters (EmailClusterId) to Safe Links clicks to reveal the
// campaigns that not only landed but were actually clicked - the campaigns with real,
// human exposure.
//
// Triage: these clusters are the priority for user reset/awareness. The AccountUpn list is
// your victim shortlist.

let Campaigns =
    EmailEvents
    | where Timestamp > ago(14d)
    | where isnotempty(EmailClusterId)
    | where ThreatTypes has_any ("Phish", "Malware")
    | project NetworkMessageId, EmailClusterId, Subject, ThreatTypes, RecipientEmailAddress;
UrlClickEvents
| where Timestamp > ago(14d)
| join kind=inner Campaigns on NetworkMessageId
| summarize
    Clicks       = count(),
    ClickThrough = countif(IsClickedThrough != "" and IsClickedThrough != "0"),
    Victims      = dcount(AccountUpn),
    VictimList   = make_set(AccountUpn, 40),
    Urls         = make_set(Url, 10),
    LastClick    = max(Timestamp)
    by EmailClusterId, ThreatTypes
| sort by Victims desc

// Title: MDO-20-Teams-SafeLinks-ClickThrough.yaml
// Source: https://www.kqlsearch.com/query/MDO-20-Teams-SafeLinks-ClickThrough&cmroxk7xw000ll1s1zge60gbg
// Section: KQL
// Author: David Alonso
// Description:
// UrlClickEvents also records Safe Links clicks inside Microsoft Teams (Workload ==
// "Microsoft Teams"). This finds users who clicked - or clicked through a warning to - a
// malicious link in Teams.
//
// Value: Teams is increasingly abused for phishing that bypasses email controls.
// Triage: each click-through user is a compromise candidate; review subsequent sign-ins and
// cloud activity.

UrlClickEvents
| where Timestamp > ago(7d)
| where Workload == "Microsoft Teams" or Workload has "Teams"
| where ThreatTypes has_any ("Phish", "Malware") or IsClickedThrough != ""
| project Timestamp, AccountUpn, Url, ThreatTypes, DetectionMethods,
          IPAddress, IsClickedThrough, Workload
| sort by Timestamp desc

// Title: MDO-22-Malicious-Files-SharePoint-OneDrive.yaml
// Source: https://www.kqlsearch.com/query/MDO-22-Malicious-Files-SharePoint-OneDrive&cmroxke3m000ml1s14mlqkxnn
// Section: KQL
// Author: David Alonso
// Description:
// Defender for Office 365 (Safe Attachments for SharePoint, OneDrive and Teams) flags
// malicious files stored in collaboration. FileMaliciousContentInfo surfaces those
// detections.
//
// IMPORTANT: run `FileMaliciousContentInfo | getschema` to confirm columns (expected:
// Timestamp, FileName, SHA256, ThreatType/ThreatName, DetectionMethods, and a site/library
// or OneDrive location field). Query kept filter-only to avoid column mismatches.
//
// Triage: pivot each SHA256 to CloudAppEvents (FileDownloaded) to see who accessed the file
// before it was blocked, and to endpoint tables for execution.

// Validate columns first:  FileMaliciousContentInfo | getschema
FileMaliciousContentInfo
| where Timestamp > ago(14d)
| sort by Timestamp desc

// Title: MDO-23-Mass-Download-After-Phishing.yaml
// Source: https://www.kqlsearch.com/query/MDO-23-Mass-Download-After-Phishing&cmroxkj5d000nl1s1sp9px3m3
// Section: KQL
// Author: David Alonso
// Description:
// Correlates users who clicked a malicious link (UrlClickEvents) with a subsequent burst of
// SharePoint/OneDrive file downloads (CloudAppEvents) - a classic post-compromise
// collection/exfiltration pattern.
//
// Triage: a spike of FileDownloaded / FileSyncDownloadedFull within hours of a malicious
// click is high-signal data theft. Contain the identity and review the accessed files.

let Clickers =
    UrlClickEvents
    | where Timestamp > ago(3d)
    | where ThreatTypes has_any ("Phish", "Malware")
    | summarize ClickTime = min(Timestamp) by AccountUpn
    | where isnotempty(AccountUpn);
CloudAppEvents
| where Timestamp > ago(3d)
| where ActionType in ("FileDownloaded", "FileSyncDownloadedFull", "FileAccessed")
| where Application has_any ("SharePoint", "OneDrive")
| extend Upn = tolower(AccountDisplayName)
| join kind=inner (Clickers | extend Upn = tolower(AccountUpn)) on Upn
| where Timestamp between (ClickTime .. ClickTime + 6h)
| summarize Downloads = count(),
            Files = dcount(ObjectName),
            Apps = make_set(Application, 5),
            IPs = make_set(IPAddress, 10),
            FirstDownload = min(Timestamp),
            LastDownload = max(Timestamp)
    by AccountUpn, ClickTime
| where Downloads >= 50
| sort by Downloads desc

// Title: MDO-25-Suspicious-Inbox-Rule-After-Click.yaml
// Source: https://www.kqlsearch.com/query/MDO-25-Suspicious-Inbox-Rule-After-Click&cmroxkq11000ol1s1qxe5fqoa
// Section: KQL
// Author: David Alonso
// Description:
// A hallmark of Business Email Compromise: shortly after a user clicks a malicious link, an
// inbox rule is created that forwards, redirects, deletes or marks-as-read mail (to hide the
// attacker's activity). Correlates UrlClickEvents with CloudAppEvents inbox-rule operations.
//
// Triage: any forwarding/redirect rule created within hours of a malicious click is
// high-confidence account takeover. Remove the rule, reset credentials, revoke sessions.

let Clickers =
    UrlClickEvents
    | where Timestamp > ago(3d)
    | where ThreatTypes has_any ("Phish", "Malware") or IsClickedThrough != ""
    | summarize ClickTime = min(Timestamp) by AccountUpn
    | where isnotempty(AccountUpn);
CloudAppEvents
| where Timestamp > ago(3d)
| where ActionType in ("New-InboxRule", "Set-InboxRule", "UpdateInboxRules")
| extend Rule = tostring(RawEventData.Parameters)
| where Rule has_any ("ForwardTo", "RedirectTo", "ForwardAsAttachmentTo",
                      "DeleteMessage", "MarkAsRead", "MoveToFolder")
| extend Upn = tolower(AccountDisplayName)
| join kind=inner (Clickers | extend Upn = tolower(AccountUpn)) on Upn
| where Timestamp between (ClickTime .. ClickTime + 6h)
| project Timestamp, AccountUpn, ClickTime, ActionType, Rule, IPAddress, Application
| sort by Timestamp desc

// Title: MDO-29-KillChain-Email-Click-Identity-Cloud.yaml
// Source: https://www.kqlsearch.com/query/MDO-29-KillChain-Email-Click-Identity-Cloud&cmroxkvbe000pl1s17m7gruwa
// Section: KQL
// Author: David Alonso
// Description:
// Reconstructs the full phishing kill chain across products: a malicious email that was
// delivered (MDO) -> the user clicked (Safe Links) -> a risky/successful sign-in followed
// (Entra) -> post-compromise cloud activity (inbox rule, download, consent). One row per
// victim with the stages observed.
//
// Value: single pane connecting MDO <-> MDI/Entra <-> MDCA - the highest-value cross-product
// narrative for an investigation or exec briefing.
// Triage: any victim reaching the "cloud activity" stage is a confirmed hands-on-keyboard
// compromise - contain immediately.

let lookback = 7d;
let malicious =
    EmailEvents
    | where Timestamp > ago(lookback)
    | where ThreatTypes has_any ("Phish", "Malware") and DeliveryAction == "Delivered"
    | project NetworkMessageId, RecipientEmailAddress, Subject, ThreatTypes;
let clicks =
    UrlClickEvents
    | where Timestamp > ago(lookback)
    | join kind=inner malicious on NetworkMessageId
    | summarize ClickTime = min(Timestamp), Url = any(Url), Subject = any(Subject),
                ThreatTypes = any(ThreatTypes) by AccountUpn
    | where isnotempty(AccountUpn);
let cloud =
    CloudAppEvents
    | where Timestamp > ago(lookback)
    | where ActionType in ("New-InboxRule","Set-InboxRule","UpdateInboxRules",
                           "FileDownloaded","FileSyncDownloadedFull",
                           "Consent to application","Add-MailboxPermission")
    | summarize CloudActions = make_set(ActionType, 10), CloudActivityTime = min(Timestamp)
            by Upn = tolower(AccountDisplayName);
clicks
| extend Upn = tolower(AccountUpn)
| join kind=leftouter cloud on Upn
| extend Stage = case(
      isnotempty(CloudActivityTime), "4-CloudActivity (contain now)",
      "3-Clicked (identity-risk review)")
| project AccountUpn, ClickTime, Subject, ThreatTypes, Url,
          CloudActions, CloudActivityTime, Stage
| sort by Stage desc, ClickTime desc

// Title: MDO-AR-01-SafeLinks-ClickThrough.yaml
// Source: https://www.kqlsearch.com/query/MDO-AR-01-SafeLinks-ClickThrough&cmroxh3ki0000l1s14p9ktnx4
// Section: KQL
// Author: David Alonso
// Description:
// Fires when a user clicks (or clicks through the warning page to) a URL that Defender for
// Office 365 Safe Links classified as Phish or Malware. Each hit is a high-confidence
// compromise candidate. Low noise because the verdict is confirmed. Promoted from hunting
// query MDO-05. MITRE ATT&CK: T1566 (Phishing), T1204.001 (Malicious Link).

UrlClickEvents
| where Timestamp > ago(1h)
| where ActionType == "ClickAllowed" or (isnotempty(IsClickedThrough) and IsClickedThrough != "0")
| where ThreatTypes has_any ("Phish", "Malware")
| where isnotempty(AccountUpn)
| project Timestamp, ReportId, AccountUpn, Url, ThreatTypes, DetectionMethods,
          IPAddress, IsClickedThrough, Workload, NetworkMessageId

// Title: MDO-AR-02-BEC-DisplayName-Impersonation.yaml
// Source: https://www.kqlsearch.com/query/MDO-AR-02-BEC-DisplayName-Impersonation&cmroxh9mq0001l1s1b17r0qvy
// Section: KQL
// Author: David Alonso
// Description:
// Fires when an inbound email uses an executive's display name but originates from a
// non-corporate sender domain - the classic CEO-fraud / BEC pattern. Customise the Execs and
// CorpDomains lists before enabling. Promoted from hunting query MDO-08.
// MITRE ATT&CK: T1566 (Phishing).

let Execs = dynamic(["CEO Name","CFO Name","Managing Director"]);
let CorpDomains = dynamic(["contoso.com","contoso.es"]);
EmailEvents
| where Timestamp > ago(1h)
| where EmailDirection == "Inbound"
| where SenderDisplayName has_any (Execs)
| where not(SenderFromDomain in~ (CorpDomains))
| project Timestamp, ReportId, SenderDisplayName, SenderFromAddress, SenderFromDomain,
          RecipientEmailAddress, Subject, DeliveryAction, NetworkMessageId

// Title: MDO-AR-03-Compromised-Internal-Sender.yaml
// Source: https://www.kqlsearch.com/query/MDO-AR-03-Compromised-Internal-Sender&cmroxhfxg0002l1s17osm1ay7
// Section: KQL
// Author: David Alonso
// Description:
// Fires when an internal mailbox sends Phish/Malware to 3 or more colleagues within the
// window - a strong account-takeover signal being weaponised for lateral phishing. Promoted
// from hunting query MDO-13. MITRE ATT&CK: T1534 (Internal Spearphishing), T1566 (Phishing).

EmailEvents
| where Timestamp > ago(3h)
| where EmailDirection == "Intra-org"
| where ThreatTypes has_any ("Phish", "Malware")
| summarize
    Recipients = dcount(RecipientEmailAddress),
    Messages   = count(),
    Subjects   = make_set(Subject, 8),
    ThreatMix  = make_set(ThreatTypes, 5),
    ReportId   = take_any(ReportId),
    Timestamp  = min(Timestamp)
    by SenderFromAddress
| where Recipients >= 3

// Title: MDO-AR-04-Inbox-Rule-After-Click.yaml
// Source: https://www.kqlsearch.com/query/MDO-AR-04-Inbox-Rule-After-Click&cmroxhkls0003l1s1r3oixdvq
// Section: KQL
// Author: David Alonso
// Description:
// Fires when a user who recently clicked a malicious link then creates an inbox rule that
// forwards, redirects, deletes or hides mail - a hallmark of Business Email Compromise.
// Correlates UrlClickEvents with CloudAppEvents inbox-rule operations. Promoted from hunting
// query MDO-25. MITRE ATT&CK: T1114 (Email Collection), T1564 (Hide Artifacts).

let Clickers =
    UrlClickEvents
    | where Timestamp > ago(3h)
    | where ThreatTypes has_any ("Phish", "Malware") or (isnotempty(IsClickedThrough) and IsClickedThrough != "0")
    | summarize ClickTime = min(Timestamp) by AccountUpn
    | where isnotempty(AccountUpn);
CloudAppEvents
| where Timestamp > ago(3h)
| where ActionType in ("New-InboxRule", "Set-InboxRule", "UpdateInboxRules")
| extend Rule = tostring(RawEventData.Parameters)
| where Rule has_any ("ForwardTo", "RedirectTo", "ForwardAsAttachmentTo", "DeleteMessage", "MarkAsRead", "MoveToFolder")
| extend Upn = tolower(AccountDisplayName)
| join kind=inner (Clickers | extend Upn = tolower(AccountUpn)) on Upn
| where Timestamp between (ClickTime .. ClickTime + 6h)
| project Timestamp, ReportId, AccountUpn, ClickTime, ActionType, Rule, IPAddress

// Title: MDO-AR-05-Illicit-OAuth-Consent.yaml
// Source: https://www.kqlsearch.com/query/MDO-AR-05-Illicit-OAuth-Consent&cmroxhsv10004l1s1b3hr7ye5
// Section: KQL
// Author: David Alonso
// Description:
// Fires when a user grants delegated consent to an OAuth application - the key event in
// consent-phishing / illicit-grant attacks that give an attacker persistent access to mail
// and files. Review the app, publisher and scopes. Promoted from hunting query MDO-26.
// MITRE ATT&CK: T1528 (Steal Application Access Token), T1566 (Phishing).

CloudAppEvents
| where Timestamp > ago(1h)
| where ActionType in ("Consent to application", "Add delegated permission grant")
| extend AppName = tostring(RawEventData.ObjectName)
| project Timestamp, ReportId, AccountObjectId, AccountDisplayName, ActionType, AppName,
          IPAddress, IsAdminOperation, UserAgent

// Title: MDO-BlockedURLs
// Source: https://www.kqlsearch.com/query/MDO-BlockedURLs&cm94j3kq001orp10fgyt2z8vo
// Section: Defender XDR
// Author: Alex Verboon
// Description:
// Use the below querys to find the domains of URLs that were blocked

UrlClickEvents
| where TimeGenerated > ago(90d)
| where ActionType == "ClickBlocked"
| where DetectionMethods has_any ("URL")
| extend Domain = extract(@"[^.]+\.[^.]+$",0, extract(@"^(?:https?://)?([^/]+)",1,Url))
| extend TLD = tostring(split(extract(@"\.([a-zA-Z]{2,}|[a-zA-Z]{2}\.[a-zA-Z]{2})$",0,Domain,typeof(string)),".")[1])
| project TimeGenerated, TLD, Domain,IPAddress, ThreatTypes,DetectionMethods, IsClickedThrough,Url

// Title: MDO-BlockedURLs
// Source: https://www.kqlsearch.com/query/MDO-BlockedURLs&cm94j3kq001orp10fgyt2z8vo
// Section: Defender XDR
// Author: Alex Verboon
// Description:
// Use the below querys to find the domains of URLs that were blocked

EmailEvents
| where DeliveryAction == "Blocked"
| where DetectionMethods has_any ("URL","domain")
| join EmailUrlInfo
on $left.NetworkMessageId == $right.NetworkMessageId
| extend Domain = extract(@"[^.]+\.[^.]+$",0, extract(@"^(?:https?://)?([^/]+)",1,Url))
| extend TLD = tostring(split(extract(@"\.([a-zA-Z]{2,}|[a-zA-Z]{2}\.[a-zA-Z]{2})$",0,Domain,typeof(string)),".")[1])
| project TimeGenerated,TLD, Domain, ThreatTypes, ThreatNames, DetectionMethods, SenderFromDomain, Url

// Title: MDO Email Threat Classification By Country.kql
// Source: https://www.kqlsearch.com/query/MDO%20Email%20Threat%20Classification%20By%20Country&cm5xj7pvf00035idwelf4dh04
// Section: KQL
// Author: Steven Lim
// Description:
// MDO Email Threat Classification By Country
// https://admin.microsoft.com/AdminPortal/Home?#/MessageCenter/:/messages/MC973503

EmailEvents 
| where isnotempty(ThreatClassification)
| extend IPInfo = iff(isnotempty(SenderIPv4),
geo_info_from_ip_address(SenderIPv4),
geo_info_from_ip_address(SenderIPv6))
| summarize Count=count() by ThreatClassification, tostring(IPInfo.country)
| sort by Count desc

// Title: MDO- FindRelatedMails
// Source: https://www.kqlsearch.com/query/MDO-%20FindRelatedMails&clohy9lwy00t8mc0obqh2ez5u
// Section: Defender XDR
// Author: Bert-Jan Pals
// Description:
// The EmailClusterId which can be assigned to a mail is the identifier for the group of similar emails clustered based on heuristic analysis of their contents. Therefore this identifier can be leveraged to find related mails. This is not a hash value of the mail. Once you have identified a suspicious mail, you can run the query below to determine if there are related mails send to your users. This can for example be from a different sender or the content of the mail has changed from *Hello Bob* to *Hello Alice* but the rest of the contents has stayed the same.

let MaliciousEmailCluseriId = "3163234347533"; // Input the EmailClusterId here
EmailEvents
| where EmailClusterId == MaliciousEmailCluseriId

// Title: MDO- FindRelatedMails
// Source: https://www.kqlsearch.com/query/MDO-%20FindRelatedMails&clohy9lwy00t8mc0obqh2ez5u
// Section: Sentinel
// Author: Bert-Jan Pals
// Description:
// The EmailClusterId which can be assigned to a mail is the identifier for the group of similar emails clustered based on heuristic analysis of their contents. Therefore this identifier can be leveraged to find related mails. This is not a hash value of the mail. Once you have identified a suspicious mail, you can run the query below to determine if there are related mails send to your users. This can for example be from a different sender or the content of the mail has changed from *Hello Bob* to *Hello Alice* but the rest of the contents has stayed the same.

