// Title: SecurityAlert-FindRecipientsofPotentialPhishing.kql
// Source: https://www.kqlsearch.com/query/SecurityAlert-FindRecipientsofPotentialPhishing&clmozy12q00emmc0ky7qz7uyj
// Section: KQL
// Author: Matt Zorich
// Description:
// When a user reports an email as potential phishing find all other users who received that email
// Data connector required for this query - Security Alert (free table that other Defender products send alert info to)
// Data connector required for this query - M365 Defender - Email* tables

SecurityAlert
| where TimeGenerated > ago(1d)
| where ProviderName == "OATP"
| where AlertName has "Email reported by user as malware or phish"
| mv-expand todynamic(Entities)
| project Entities
| extend SenderMailFromAddress = tostring(Entities.P1Sender)
| extend Subject = tostring(Entities.Subject)
| where isnotempty(SenderMailFromAddress) and isnotempty(Subject)
| distinct SenderMailFromAddress, Subject
| join kind=inner(
    EmailEvents
    | where TimeGenerated > ago(2d)
    | project RecipientEmailAddress, SenderMailFromAddress, Subject
    )
    on SenderMailFromAddress, Subject
| summarize Recipients=make_set(RecipientEmailAddress) by Subject, SenderMailFromAddress

// Title: SecurityAlert-FindUsersWhoSigninfromMaliciousIPs.kql
// Source: https://www.kqlsearch.com/query/SecurityAlert-FindUsersWhoSigninfromMaliciousIPs&clmozylls00epmc0knaa0ymol
// Section: KQL
// Author: Matt Zorich
// Description:
// Parse the IP information from Security Alerts and find other users who have successfully signed on from the same IP addresses
// Data connector required for this query - Security Alert (free table that other Defender products send alert info to)
// Data connector required for this query - Azure Active Directory - Signin Logs

SecurityAlert
| where ProviderName in ("MCAS", "IPC")
| extend x = todynamic(Entities)
| mv-expand x
| parse-where x with * '"Address":"' MaliciousIP '"' *
//Exclude any corporate or trusted IP addresses
| where MaliciousIP != "10.10.10.10"
| project AlertTime=TimeGenerated, MaliciousIP, CompromisedEntity
| join kind=inner
    (
    SigninLogs
    | where ResultType in ("0","53003","50158")
    )
    on $left.MaliciousIP == $right.IPAddress
| where CompromisedEntity != UserPrincipalName
| distinct UserPrincipalName, AppDisplayName, IPAddress, UserAgent, ResultType, ResultDescription

// Title: SecurityAlert-WhichTablesAreInUse.kql
// Source: https://www.kqlsearch.com/query/SecurityAlert-WhichTablesAreInUse&clmp01ufw00fpmc0k4j0rcdbh
// Section: KQL
// Author: Matt Zorich
// Description:
// Find which data sources are being used the most, by calculating which analytics rules are querying which tables when alerts are generated
// This will not account for the use of functions and may double handle table names occasionally, so it can be used as just a rough guide
// Data connector required for this query - Security Alert (free table that other Defender products send alert info to)

let tablenames = search *
   | summarize make_set($table);
SecurityAlert
| where TimeGenerated > ago (30d)
| where ProviderName == "ASI Scheduled Alerts"
| summarize arg_max(TimeGenerated, *) by SystemAlertId
| extend Query = tostring(parse_json(ExtendedProperties).Query)
| mv-apply table=toscalar(tablenames) to typeof(string) on (where Query contains ['table'])
| summarize QueryCount = count()by ['table'], AlertName
| order by QueryCount

// Title: SecurityEvent-AccountPreAuthChanges.kql
// Source: https://www.kqlsearch.com/query/SecurityEvent-AccountPreAuthChanges&clmowrjr300045i9sg26sjlhx
// Section: KQL
// Author: Matt Zorich
// Description:
// Detect when Kerberos preauthentication is enabled or disabled for a user
// Data connector required for this query - Windows Security Events via AMA or Security Events via Legacy Agent

SecurityEvent
| where EventID == 4738
| where AccountType == "User"
| where UserAccountControl has_any ("2064", "2096")
| extend Action = case(UserAccountControl has "2096", strcat("Kerberos preauthentication disabled"),
    UserAccountControl has "2064", strcat("Kerberos preauthentication enabled"),
    "unknown")
| project TimeGenerated, Actor=SubjectAccount, User=TargetAccount, Action

// Title: SecurityEvent-SummarizePrivilegesAssignedonLogon.kql
// Source: https://www.kqlsearch.com/query/SecurityEvent-SummarizePrivilegesAssignedonLogon&clmowsw5e000k5i9sw4wt7hdv
// Section: KQL
// Author: Matt Zorich
// Description:
// Create a summary of your computers and the accounts that have logged on with special privileges over the last 30 days
// Data connector required for this query - Windows Security Events via AMA or Security Events via Legacy Agent

SecurityEvent
| where TimeGenerated > ago (30d)
| project TimeGenerated, EventID, Account, AccountType, PrivilegeList, Computer
| where EventID == "4672"
| where Account != "NT AUTHORITY\\SYSTEM" and Account !has "Window Manager"
| where AccountType == "User"
//The privilege list is stored in a string of text that we need to split
| extend Privs=extract_all(@"Se(.*?)Privilege", PrivilegeList)
//Once we retrieve the privileges from the string of text we can recreate the proper naming
| mv-expand Privs
| extend Privilege=strcat('Se', Privs, 'Privilege')
| project TimeGenerated, Account, Computer, Privilege
| summarize ['List of Privileges']=make_set(Privilege) by Computer, Account
| sort by Computer asc

// Title: Sentinel Alerts & MITRE ATT&CK Analysis.kql
// Source: https://www.kqlsearch.com/query/Sentinel%20Alerts%20%26%20MITRE%20ATT%26CK%20Analysis&clzh2awm5002o5ivovi5i6z3z
// Section: KQL
// Author: Steven Lim
// Description:
// Sentinel Alerts & MITRE ATT&CK Analysis
// https://www.linkedin.com/posts/activity-7195301674301759488-rMQS/
// The Microsoft Sentinel MITRE ATT&CK (Preview) blade offers a comprehensive overview of all Sentinel detections aligned with the MITRE ATT&CK technique matrix. As a Security Operations Center (SOC) analyst overseeing analytic rules, are you aware of which MITRE Techniques are activated most frequently or infrequently? Running the subsequent KQL query will unveil the technique adversaries most commonly employ. Evaluate which techniques are triggered most or least often in comparison to your Microsoft Sentinel MITRE ATT&CK (preview) coverage. This analysis is crucial to determine if your analytic rules are sufficiently robust to identify these frequently used techniques.
// KQL - Summarization of Techniques Triggered

SecurityAlert
| where TimeGenerated > ago(90d)
| mv-expand todynamic(Techniques)
| extend MitreAttackTechniques = tostring(Techniques)
| where MitreAttackTechniques != ""
| summarize Technique_Count=count() by MitreAttackTechniques
| sort by Technique_Count desc

// MITRE ATT&CK Mapping

//The KQL code is designed to map security alerts to specific MITRE ATT&CK techniques. Each technique identified in the Techniques field corresponds to a specific tactic or technique in the MITRE ATT&CK framework. Here are some common techniques that might be detected:

// T1078: Valid Accounts: Detection of compromised accounts.
// T1059: Command and Scripting Interpreter: Detection of script execution.
// T1105: Ingress Tool Transfer: Detection of tools being transferred into the environment.
// T1027: Obfuscated Files or Information: Detection of obfuscated files or information.

// Title: Sentinel All-In-One IP ThreatHunt.kql
// Source: https://www.kqlsearch.com/query/Sentinel%20All-In-One%20IP%20ThreatHunt&clzh2b648002p5ivo7knnqpqo
// Section: KQL
// Author: Steven Lim
// Description:
// Sentinel All-In-One IP ThreatHunt
// https://www.linkedin.com/pulse/microsoft-sentinel-kql-solo-leveling-steven-lim-8hsqc/
// This KQL query searches across these Sentinel log tables for the ip variable that is defined at the start:
// Anomalies, CloudAppEvents, CommonSecurityLog, DeviceEvents, DeviceFileEvents, DeviceInfo, DeviceLogonEvents, AzureActivity DeviceNetworkEvents, EmailEvents, OfficeActivity, SecurityEvent, ThreatIntelligenceIndicator, UrlClickEvents, BehaviorAnalytics

let ip = "127.0.0.1";
search in (Anomalies,CloudAppEvents,CommonSecurityLog,DeviceEvents,DeviceFileEvents,DeviceInfo,DeviceLogonEvents,AzureActivity,
DeviceNetworkEvents,EmailEvents,OfficeActivity,SecurityEvent,ThreatIntelligenceIndicator,UrlClickEvents,BehaviorAnalytics)
TimeGenerated between (ago(1d) .. now())
and (
// ** Events initiated by this IP **
DestinationIpAddress == ip          // Anomalies, UrlClickEvents  
or IPAddress == ip                  // CloudAppEvents
or RemoteIP == ip                   // CommonSecurityLog, DeviceEvents, DeviceLogonEvents, DeviceNetworkEvents  
or FileOriginIP == ip               // DeviceFileEvents
or SenderIPv4 == ip                 // EmailEvents
or ClientIP == ip                   // OfficeActivity
or NetworkDestinationIP == ip       // ThreatIntelligenceIndicator
or DestinationIPAddress == ip       // BehaviorAnalytics 
//
// ** Events affecting this IP **
or SourceIpAddress == ip            // Anomalies
or SourceIP == ip                   // CommonSecurityLog, DeviceEvents
or CallerIpAddress == ip            // AzureActivity
or RequestSourceIP == ip            // DeviceFileEvents
or PublicIP == ip                   // DeviceInfo
or LocalIP == ip                    // DeviceNetworkEvents
or ClientIPAddress == ip            // SecurityEvent
or NetworkSourceIP == ip            // ThreatIntelligenceIndicator
or SourceIPAddress == ip            // BehaviorAnalytics 
)

// MITRE ATT&CK Mapping

// EmailEvents (SenderIPv4): Phishing (T1566)
// UrlClickEvents (DestinationIpAddress): Drive-by Compromise (T1189) 
// DeviceLogonEvents (RemoteIP): Remote Services (T1021)
// DeviceFileEvents (FileOriginIP): Indicator Removal on Host (T1070)
// DeviceNetworkEvents (LocalIP): Network Service Scanning (T1046)

// Title: Sentinel All-In-One UPN ThreatHunt.kql
// Source: https://www.kqlsearch.com/query/Sentinel%20All-In-One%20UPN%20ThreatHunt&clzh2beb0002q5ivo4m1opv8o
// Section: KQL
// Author: Steven Lim
// Description:
// Sentinel All-In-One UPN ThreatHunt
// https://www.linkedin.com/pulse/microsoft-sentinel-kql-solo-leveling-steven-lim-8hsqc/
// This KQL query searches across these Sentinel log tables for the UPN variable that is defined at the start:
// Anomalies, CloudAppEvents, CommonSecurityLog, DeviceEvents, DeviceFileEvents, DeviceLogonEvents, AzureActivity, EmailEvents, OfficeActivity, SecurityEvent, BehaviorAnalytics

let upn = "FirstName.LastName@onmicrosoft.com";
search in (Anomalies,CloudAppEvents,CommonSecurityLog,DeviceEvents,DeviceFileEvents,DeviceLogonEvents,AzureActivity,
EmailEvents,OfficeActivity,SecurityEvent,BehaviorAnalytics)
TimeGenerated between (ago(1d) .. now())
and (
// ** Events initiated by this UPN **
UserPrincipalName == upn                        // Anomalies, BehaviorAnalytics 
or tostring(RawEventData.UserId) == upn         // CloudAppEvents 
or SourceUserName == upn                        // CommonSecurityLog
or AccountName == upn                           // DeviceEvents
or InitiatingProcessAccountUpn  == upn          // DeviceFileEvents, DeviceLogonEvents  
or Caller == upn                                // AzureActivity
or RecipientEmailAddress == upn                 // EmailEvents
or SenderMailFromAddress == upn                 // EmailEvents
or UserId == upn                                // OfficeActivity
or Entities contains upn                        // SecurityEvent
) 

// MITRE ATT&CK Mapping

// Based on the fields and data sources used in the KQL query, here are some potential MITRE ATT&CK techniques that could be detected:

// T1078 - Valid Accounts: The query checks for events where the UPN is used, which can help identify the use of valid accounts across different services and logs.
// T1059 - Command and Scripting Interpreter: If the DeviceEvents or DeviceFileEvents tables include script execution logs, this technique could be relevant.
// T1071 - Application Layer Protocol: The EmailEvents table checks for email activities, which can be mapped to this technique if emails are used for command and control.
// T1106 - Execution: The DeviceLogonEvents and DeviceFileEvents tables can help detect execution of processes or files.
// T1110 - Brute Force: The SecurityEvent table can be used to detect brute force attempts if it includes authentication logs.
// T1040 - Network Sniffing: If CommonSecurityLog includes network traffic logs, this technique could be relevant.
// T1087 - Account Discovery: The AzureActivity table can help detect account discovery activities in Azure environments.

