## Logic App
```json
{
    "definition": {
        "metadata": {
            "notes": {}
        },
        "$schema": "https://schema.management.azure.com/providers/Microsoft.Logic/schemas/2016-06-01/workflowdefinition.json#",
        "contentVersion": "1.0.0.0",
        "triggers": {
            "Recurrence": {
                "type": "Recurrence",
                "recurrence": {
                    "interval": 7,
                    "frequency": "Day",
                    "timeZone": "W. Europe Standard Time",
                    "startTime": "2026-06-11T03:00:00Z",
                    "schedule": {
                        "hours": [
                            3
                        ]
                    }
                }
            }
        },
        "actions": {
            "Run_Advanced_Hunting_Query": {
                "type": "Http",
                "inputs": {
                    "uri": "https://graph.microsoft.com/v1.0/security/runHuntingQuery",
                    "method": "POST",
                    "headers": {
                        "Content-Type": "application/json"
                    },
                    "body": {
                        "query": "let DeviceCategories = DeviceInfo\n| summarize arg_max(Timestamp, *) by DeviceId\n| extend DeviceCategory = case(\n    DeviceType has_any (\"NetworkDevice\", \"Router\", \"Switch\", \"Firewall\"), \"Network Components\",\n    OSPlatform startswith \"WindowsServer\" or OSPlatform has \"Server\", \"Windows Server\",\n    OSPlatform startswith \"Windows\" and not(OSPlatform has \"Server\"), \"Windows Clients\",\n    OSPlatform startswith \"macOS\" or OSPlatform has \"macOS\", \"macOS\",\n    OSPlatform startswith \"Linux\" or OSPlatform has \"Linux\", \"Linux Server\",\n    \"Others / Unknown\"\n);\nlet VulnerabilityKB = DeviceTvmSoftwareVulnerabilitiesKB\n| project CveId, CvssScore, IsExploitAvailable;\nDeviceTvmSoftwareVulnerabilities\n| join kind=inner (\n    DeviceCategories\n    | project DeviceId, DeviceCategory, DeviceName\n) on DeviceId\n| join kind=inner VulnerabilityKB on CveId\n| summarize\n    Vulnerability_Count = count(),\n    Unique_CVEs = dcount(CveId),\n    Unique_CVEs_With_Exploit = dcountif(CveId, IsExploitAvailable == 1),\n    Affected_Devices = dcount(DeviceId),\n    Avg_CVSS_Score = round(avg(toreal(CvssScore)), 4)\n    by DeviceCategory\n| extend Avg_Vulnerabilities_Per_Device = round(toreal(Vulnerability_Count) / Affected_Devices, 4)\n| extend TimeGenerated = now()\n| sort by Vulnerability_Count desc"
                    },
                    "authentication": {
                        "type": "ManagedServiceIdentity",
                        "audience": "https://graph.microsoft.com"
                    }
                },
                "runAfter": {}
            },
            "POST_to_Log_Ingestion_API": {
                "type": "Http",
                "inputs": {
                    "uri": "https://p-dce-mgmtgeneral-01-1pac.switzerlandnorth-1.ingest.monitor.azure.com/dataCollectionRules/dcr-53154c288e6c409bb9378473206f8d13/streams/Custom-Vulnerabilitystatistics_CL?api-version=2023-01-01",
                    "method": "POST",
                    "headers": {
                        "Content-Type": "application/json"
                    },
                    "body": "@body('Run_Advanced_Hunting_Query')?['results']",
                    "authentication": {
                        "type": "ManagedServiceIdentity",
                        "audience": "https://monitor.azure.com"
                    }
                },
                "runAfter": {
                    "Run_Advanced_Hunting_Query": [
                        "Succeeded"
                    ]
                }
            },
            "Check_Ingestion_Response": {
                "type": "If",
                "expression": {
                    "and": [
                        {
                            "greaterOrEquals": [
                                "@outputs('POST_to_Log_Ingestion_API')['statusCode']",
                                200
                            ]
                        },
                        {
                            "less": [
                                "@outputs('POST_to_Log_Ingestion_API')['statusCode']",
                                300
                            ]
                        }
                    ]
                },
                "actions": {
                    "Ingestion_Succeeded": {
                        "type": "Compose",
                        "inputs": {
                            "status": "success",
                            "message": "TVM Weekly Summary successfully ingested into VulnerabilityStats_CL",
                            "timestamp": "@utcNow()",
                            "rows_ingested": "@length(body('Run_Advanced_Hunting_Query')?['results'])"
                        }
                    }
                },
                "else": {
                    "actions": {
                        "Ingestion_Failed": {
                            "type": "Compose",
                            "inputs": {
                                "status": "failed",
                                "message": "TVM Weekly Summary ingestion failed",
                                "timestamp": "@utcNow()",
                                "http_status_code": "@outputs('POST_to_Log_Ingestion_API')['statusCode']",
                                "response_body": "@body('POST_to_Log_Ingestion_API')"
                            }
                        },
                        "Terminate_with_Failure": {
                            "type": "Terminate",
                            "inputs": {
                                "runStatus": "Failed",
                                "runError": {
                                    "code": "IngestionFailed",
                                    "message": "Log Ingestion API returned non-2xx status code"
                                }
                            },
                            "runAfter": {
                                "Ingestion_Failed": [
                                    "Succeeded"
                                ]
                            }
                        }
                    }
                },
                "runAfter": {
                    "POST_to_Log_Ingestion_API": [
                        "Succeeded",
                        "Failed"
                    ]
                }
            }
        },
        "outputs": {},
        "parameters": {
            "$connections": {
                "type": "Object",
                "defaultValue": {}
            }
        }
    },
    "parameters": {
        "$connections": {
            "type": "Object",
            "value": {}
        }
    }
}

