| where type == "microsoft.operationalinsights/workspaces"
| where properties['retentionInDays'] == 90

// Title: WscriptInternetConnection.KQL
// Source: https://www.kqlsearch.com/query/WscriptInternetConnection&clz0ybmsa002c5iog6u15tj0p
// Section: KQL
// Author: Ali Hussein
