// Title: X-1 LabelDowngrade x CloudAppExternalUpload.kql
// Source: https://www.kqlsearch.com/query/X-1_LabelDowngrade_x_CloudAppExternalUpload&cmqsuk6zt006zjqzcxnm716kn
// Section: KQL
// Author: David Alonso
// Description:
// X-1 - Purview label downgrade ⨯ CloudAppEvents external upload (10 min window)
// Run in: security.microsoft.com -> Hunting -> Advanced hunting (UNIFIED PORTAL ONLY)
// Requires: Sentinel onboarded to Defender XDR so MicrosoftPurviewInformationProtection is queryable beside CloudAppEvents

let downgrades =
    MicrosoftPurviewInformationProtection
    | where TimeGenerated > ago(7d)
    | where isnotempty(OldSensitivityLabelId) and OldSensitivityLabelId != SensitivityLabelId
    | project DowngradeTime=TimeGenerated, AccountUpn=UserId, ItemName, ObjectId,
              OldLabel=OldSensitivityLabelId, NewLabel=SensitivityLabelId;
let cloudUploads =
    CloudAppEvents
    | where Timestamp > ago(7d)
    | where ActionType in ("FileUploaded","FileSharedExternally","FileDownloaded")
    | project UploadTime=Timestamp, AccountUpn=AccountObjectId, AccountUserName=AccountDisplayName,
              ApplicationName=Application, ActionType, ObjectName, IPAddress;
downgrades
| join kind=inner cloudUploads on AccountUpn
| where UploadTime between (DowngradeTime .. (DowngradeTime + 10m))
| project DowngradeTime, UploadTime, AccountUpn, ItemName, ObjectName,
          OldLabel, NewLabel, ApplicationName, ActionType, IPAddress
| order by DowngradeTime desc

// Title: X-2 PurviewDLP x OfficeActivity Downloads.kql
// Source: https://www.kqlsearch.com/query/X-2_PurviewDLP_x_OfficeActivity_Downloads&cmqsukbkq0070jqzcmlwspz37
// Section: KQL
// Author: David Alonso
// Description:
// X-2 - Purview DLP match ⨯ OfficeActivity SharePoint download by same user (±30 min)
// Run in: security.microsoft.com -> Hunting -> Advanced hunting (UNIFIED PORTAL)

let dlpMatches =
    MicrosoftPurviewInformationProtection
    | where TimeGenerated > ago(1d)
    | where isnotempty(ExecutionRuleName)
    | project DlpTime=TimeGenerated, UserId, ItemName, PolicyName, ExecutionRuleName;
let spDownloads =
    OfficeActivity
    | where TimeGenerated > ago(1d)
    | where Operation in ("FileDownloaded","FileSyncDownloadedFull","FileAccessed")
    | project SpTime=TimeGenerated, UserId, OfficeObjectId, ClientIP, UserAgent;
dlpMatches
| join kind=inner spDownloads on UserId
| where SpTime between (DlpTime - 30m .. DlpTime + 30m)
| summarize Hits=count(),
            DlpRules=make_set(ExecutionRuleName, 10),
            Files=make_set(ItemName, 20),
            SpObjects=make_set(OfficeObjectId, 20),
            FirstSeen=min(DlpTime), LastSeen=max(DlpTime)
        by UserId, ClientIP
| where Hits >= 5
| order by Hits desc

// Title: X-3 InsiderRisk x ConfidentialLabelMovement.kql
// Source: https://www.kqlsearch.com/query/X-3_InsiderRisk_x_ConfidentialLabelMovement&cmqsukhax0071jqzc3zqna2g1
// Section: KQL
// Author: David Alonso
// Description:
// X-3 - Insider Risk behavior ⨯ Purview confidential label movement (±1h)
// Run in: security.microsoft.com -> Hunting -> Advanced hunting (UNIFIED PORTAL)

let irBehaviors =
    DataSecurityBehaviors
    | where Timestamp > ago(7d)
    | where IsAnomalous == 1
    | project IrTime=Timestamp, AccountUpn, ActionType, Categories, ActivityCount;
let confMoves =
    MicrosoftPurviewInformationProtection
    | where TimeGenerated > ago(7d)
    | where LabelName has_any ("Confidential","Highly Confidential","Restricted")
    | project MoveTime=TimeGenerated, AccountUpn=UserId, ItemName, ObjectId, Operation, LabelName, Receivers;
irBehaviors
| join kind=inner confMoves on AccountUpn
| where MoveTime between (IrTime - 1h .. IrTime + 1h)
| project IrTime, MoveTime, AccountUpn, ActionType, Categories, Operation, LabelName, ItemName, Receivers
| order by IrTime desc

// Title: ZeroLogon Ports.txt
// Source: https://www.kqlsearch.com/query/ZeroLogon_Ports&clmp1tj8u00swmc0kn2i1ilid
// Section: KQL
// Author: Rod Trent
// Description:
// Ports accessed by Zerologon

DeviceNetworkEvents
| where RemotePort == 135 or RemotePort between (49670 .. 49680)
| summarize (Timestamp, InitiatingProcessFileName, InitiatingProcessCommandLine, InitiatingProcessAccountSid)=arg_min(ReportId, Timestamp, InitiatingProcessFileName, InitiatingProcessCommandLine, InitiatingProcessAccountSid), TargetDevicePorts=make_set(RemotePort) by DeviceId, DeviceName, RemoteIP, RemoteUrl
| project-rename SourceComputerName=DeviceName, SourceDeviceId=DeviceId, TargetDeviceIP=RemoteIP, TargetComputerName=RemoteUrl

// Title: Zscalar IP Sign-in Check.kql
// Source: https://www.kqlsearch.com/query/Zscalar%20IP%20Sign-in%20Check&cma2htqs102b4p10f7ysn4xgg
// Section: KQL
// Author: Jay Kerai
// Description:
// Experimental, query needs optimization.

let Zscaler = externaldata (prefixes: dynamic) [@'https://config.zscaler.com/api/zscaler.net/future/json'] with (format=json, ignoreFirstRecord=True)
//| mv-expand prefixes
//| summarize by ZscalerIP= tostring(prefixes)
| extend Dummy = 1;
SigninLogs
| where TimeGenerated > ago(90d)
| where ResultType == 0
| extend Dummy = 1
| join kind=fullouter Zscaler on Dummy //map every sign-in to all zscaler Ips
| where ipv4_is_in_any_range(IPAddress, prefixes)
| project-away prefixes
